const BOOK=[{"n":0,"slug":"00-introduction","label":"Introduction","title":"Introduction","audio":"00-introduction.mp3","dur":665,"imgs":["00-introduction-01.jpg","00-introduction-02.jpg","00-introduction-03.jpg","00-introduction-04.jpg","00-introduction-05.jpg","00-introduction-06.jpg","00-introduction-07.jpg","00-introduction-08.jpg","00-introduction-09.jpg","00-introduction-10.jpg","00-introduction-11.jpg","00-introduction-12.jpg","00-introduction-13.jpg"],"secs":[{"t":24,"lv":2,"h":"1909 \u2014 Selling Trucks, Hating Life","b":"<ul><li class=\"d0\"><b>1909</b> \u2014 one of the unhappiest lads in New York</li><li class=\"d0\">Sold <b>motor trucks</b> \u2014 didn&#x27;t know how they ran, didn&#x27;t care to</li><li class=\"d0\">Despised the job</li><li class=\"d0\">Despised the room \u2014 cheap furnished, <b>West 56th Street</b>, infested with <b>cockroaches</b></li><li class=\"d1\">neckties on the wall \u2014 reach for one, roaches scatter</li><li class=\"d0\">Nightly <b>sick headache</b> \u2014 disappointment, worry, bitterness, rebellion</li></ul>","img":["00-introduction-01.jpg"]},{"t":77,"lv":2,"h":"The Rubicon","b":"<ul><li class=\"d0\">College dreams had become nightmares</li><li class=\"d0\">Nothing to lose by quitting; not after money, after <b>living</b></li><li class=\"d0\">Reached <b>&quot;the Rubicon&quot;</b> \u2014 the moment of decision</li></ul>","img":["00-introduction-02.jpg"]},{"t":128,"lv":2,"h":"The Decision","b":"<ul><li class=\"d0\">Gave up the job</li><li class=\"d0\"><b>Four years</b> at State Teachers College, <b>Warrensburg, Missouri</b></li><li class=\"d0\">Would teach adult <b>night classes</b> \u2014 days free to write</li></ul>","img":["00-introduction-03.jpg"]},{"t":184,"lv":2,"h":"Why Public Speaking","b":"<ul><li class=\"d0\">His own public speaking training \u2014 most valuable thing from college</li><li class=\"d1\">wiped out timidity</li><li class=\"d1\"><b>leadership gravitates to the man who can stand up and say what he thinks</b></li><li class=\"d0\">Applied to <b>Columbia</b> and <b>NYU</b> \u2014 both turned him down</li><li class=\"d0\">Now thanks God they did</li></ul>","img":["00-introduction-04.jpg"]},{"t":237,"lv":2,"h":"YMCA \u2014 Had to Deliver","b":"<ul><li class=\"d0\">Taught at <b>YMCA</b> night schools \u2014 had to show <b>results, fast</b></li><li class=\"d0\">Students wanted to solve problems, not earn credits</li><li class=\"d1\">speak at a meeting without fainting from fright</li><li class=\"d1\">call on a tough customer without circling the block three times</li><li class=\"d0\">Paid on <b>percentage of profits</b>, not salary \u2014 installment tuition</li><li class=\"d1\">felt like a handicap; was really priceless training</li></ul>","img":["00-introduction-05.jpg"]},{"t":289,"lv":2,"h":"Five a Night to Thirty","b":"<ul><li class=\"d0\">Within <b>three seasons</b></li><li class=\"d0\">YMCA had refused him <b>$5 a night</b></li><li class=\"d0\">Now paying him <b>$30 a night</b></li></ul>","img":["00-introduction-06.jpg"]},{"t":344,"lv":2,"h":"The Book That Grew","b":"<ul><li class=\"d0\">Students also needed <b>human relations</b> \u2014 no textbook existed</li><li class=\"d0\">Wrote his own \u2014 <b>grew out of</b> the classes, not written the usual way</li><li class=\"d0\">Called it <b>How to Win Friends and Influence People</b></li><li class=\"d0\">Had already written <b>four other books</b> nobody had heard of</li><li class=\"d0\">Now &quot;one of the most astonished authors now living&quot;</li></ul>","img":["00-introduction-07.jpg"]},{"t":344,"lv":2,"h":"Worry \u2014 The Next Problem","b":"<ul><li class=\"d0\">Worry emerged as adults&#x27; biggest problem</li><li class=\"d0\">Students: businessmen, salesmen, engineers, accountants, housewives</li><li class=\"d0\">Looked for a textbook on conquering worry</li></ul>","img":[]},{"t":394,"lv":2,"h":"22 Books on Worry, 189 on Worms","b":"<ul><li class=\"d0\"><b>New York Public Library</b>, Fifth Avenue and 42nd Street</li><li class=\"d0\">Only <b>22 books</b> under &quot;Worry&quot; \u2014 <b>189</b> under &quot;Worms&quot;</li><li class=\"d0\">Almost <b>nine times</b> as many books on worms as on worry</li><li class=\"d0\">No college course anywhere on stopping worry</li><li class=\"d0\"><b>David Seabury</b>: we come to maturity as unprepared for pressure as a bookworm asked to do a ballet</li><li class=\"d0\">More than <b>half</b> of hospital beds \u2014 nervous, emotional trouble</li><li class=\"d0\">Bought every worry book he could find \u2014 still nothing usable</li></ul>","img":["00-introduction-08.jpg"]},{"t":450,"lv":2,"h":"Building the Book","b":"<ul><li class=\"d0\">Resolved to write it himself \u2014 began <b>seven years</b> before writing it</li><li class=\"d0\">Read the philosophers on worry; hundreds of biographies, <b>Confucius to Churchill</b></li><li class=\"d0\">Interviewed <b>Jack Dempsey, General Omar Bradley, General Mark Clark, Henry Ford, Eleanor Roosevelt, Dorothy Dixon</b></li></ul>","img":["00-introduction-09.jpg"]},{"t":503,"lv":2,"h":"The Laboratory","b":"<ul><li class=\"d0\">More important still: <b>five years</b> running a <b>laboratory for conquering worry</b>, inside his own classes</li><li class=\"d0\">First and only laboratory of its kind, as far as he knew</li><li class=\"d0\">Gave students <b>rules</b>, had them apply them, report results to class</li><li class=\"d0\">Heard more talks on &quot;how I conquered worry&quot; than any person alive</li></ul>","img":["00-introduction-10.jpg"]},{"t":562,"lv":2,"h":"Not an Ivory Tower","b":"<ul><li class=\"d0\">No academic preachment \u2014 a <b>fast-moving, documented report</b> on worry actually conquered</li><li class=\"d0\"><b>Val\u00e9ry</b>: science is a collection of successful recipes</li><li class=\"d0\">This book \u2014 <b>successful, time-tested recipes</b></li></ul>","img":["00-introduction-11.jpg"]},{"t":613,"lv":2,"h":"The Warning","b":"<ul><li class=\"d0\">Nothing new inside \u2014 but much <b>not generally applied</b></li><li class=\"d0\">We already know enough \u2014 Golden Rule, Sermon on the Mount</li><li class=\"d0\">Trouble isn&#x27;t <b>ignorance</b> \u2014 it&#x27;s <b>inaction</b></li></ul>","img":["00-introduction-12.jpg"]},{"t":613,"lv":2,"h":"The Purpose","b":"<ul><li class=\"d0\">Restate, streamline, glorify old truths</li><li class=\"d0\"><b>Kick you in the shins</b> \u2014 make you act</li></ul>","img":["00-introduction-13.jpg"]},{"t":613,"lv":2,"h":"The Challenge","b":"<ul><li class=\"d0\">Read <b>Parts One and Two</b></li><li class=\"d0\">No new power, no new inspiration \u2014 <b>toss the book away</b></li><li class=\"d0\"><i>How to Stop Worrying and Start Living</i> \u2014 Part 1: Fundamental facts you should know about worry</li></ul>","img":[]}]},{"n":1,"slug":"ch-01-live-in-day-tight-compartments","label":"Chapter 1","title":"Live in \"Day-Tight Compartments\"","audio":"ch-01-live-in-day-tight-compartments.mp3","dur":1448,"imgs":["ch-01-live-in-day-tight-compartments-01.jpg","ch-01-live-in-day-tight-compartments-02.jpg","ch-01-live-in-day-tight-compartments-03.jpg","ch-01-live-in-day-tight-compartments-04.jpg","ch-01-live-in-day-tight-compartments-05.jpg","ch-01-live-in-day-tight-compartments-06.jpg","ch-01-live-in-day-tight-compartments-07.jpg","ch-01-live-in-day-tight-compartments-08.jpg","ch-01-live-in-day-tight-compartments-09.jpg","ch-01-live-in-day-tight-compartments-10.jpg","ch-01-live-in-day-tight-compartments-11.jpg"],"secs":[{"t":0,"lv":2,"h":"Osler and the 21 words","b":"<ul><li class=\"d0\">Spring <b>1871</b> - med student, <b>Montreal General Hospital</b></li><li class=\"d1\">worried: passing finals, where to go, how to build a practice, how to make a living</li><li class=\"d0\">Picked up a book, read <b>21 words</b> from <b>Thomas Carlyle</b></li><li class=\"d1\"><i>&quot;Our main business is not to see what lies dimly at a distance, but to do what lies clearly at hand.&quot;</i></li><li class=\"d0\">That student: <b>Sir William Osler</b></li><li class=\"d1\">founded <b>Johns Hopkins School of Medicine</b></li><li class=\"d1\"><b>Regius professor of Medicine, Oxford</b> - highest honor in the British Empire</li><li class=\"d1\">knighted by the King</li><li class=\"d1\">obituary took <b>2 volumes, 1,466 pages</b></li></ul>","img":["ch-01-live-in-day-tight-compartments-01.jpg"]},{"t":107,"lv":2,"h":"The Yale address - 42 years later","b":"<ul><li class=\"d0\">Spring night, tulips on the campus</li><li class=\"d0\">Told the students his brains were <b>&quot;of the most mediocre character&quot;</b> - friends knew it</li><li class=\"d0\">Secret was not brains. Secret was <b>living in day-tight compartments</b></li></ul>","img":["ch-01-live-in-day-tight-compartments-02.jpg"]},{"t":168,"lv":3,"h":"Where the phrase came from","b":"<ul><li class=\"d0\">Months earlier, crossed the Atlantic on a liner</li><li class=\"d0\">Captain presses a <b>button</b> -&gt; clanging machinery, ship seals into <b>watertight compartments</b></li><li class=\"d0\">Osler to the students: <i>you are a more marvelous organization than the liner, on a longer voyage</i></li><li class=\"d1\"><b>get on the bridge</b>, check the bulkheads work</li><li class=\"d1\">touch a button -&gt; <b>iron doors shut out the past</b>, the dread yesterdays</li><li class=\"d1\">touch another -&gt; <b>metal curtain on the future</b>, the unborn tomorrows</li><li class=\"d1\"><b>&quot;Then you are safe for today.&quot;</b></li><li class=\"d0\"><b>&quot;The load of tomorrow added to that of yesterday carried today makes the strongest falter.&quot;</b></li></ul>","img":["ch-01-live-in-day-tight-compartments-03.jpg"]},{"t":222,"lv":2,"h":"Not &quot;don&#x27;t prepare&quot;","b":"<ul><li class=\"d0\">Osler was <b>not</b> saying skip planning</li><li class=\"d0\"><b>Best preparation for tomorrow = do today&#x27;s work superbly today.</b> Only possible way.</li><li class=\"d0\"><b>&quot;Give us this day our daily bread&quot;</b> - asks for <i>today&#x27;s</i> bread only</li><li class=\"d1\">doesn&#x27;t complain about yesterday&#x27;s stale loaf</li><li class=\"d1\">doesn&#x27;t beg about next fall&#x27;s drought or a lost job</li><li class=\"d0\">Penniless philosopher, crowd on a hill, <b>26 words</b>: <i>take no thought for the morrow</i></li><li class=\"d1\">Rejected as mysticism - &quot;I must insure my family, save for old age, plan ahead.&quot; <b>Right, of course you must.</b></li><li class=\"d1\"><b>Translation problem:</b> in King James English, <b>&quot;thought&quot; meant anxiety</b></li><li class=\"d1\">Modern reading: <b>have no anxiety for tomorrow.</b> Take thought - plan, prepare - but no dread.</li><li class=\"d0\"><b>Admiral Ernest J. King</b> (WWII, US Navy): best men, best equipment, wisest mission - <b>&quot;That is all I can do.&quot;</b></li><li class=\"d0\"><b>Good thinking</b> -&gt; causes and effects, constructive planning. <b>Bad thinking</b> -&gt; tension, breakdown.</li></ul>","img":["ch-01-live-in-day-tight-compartments-04.jpg"]},{"t":282,"lv":2,"h":"Three people who learned it","b":"","img":[]},{"t":393,"lv":3,"h":"Arthur Hays Sulzberger - publisher, NY Times (1935-1961)","b":"<ul><li class=\"d0\">WWII broke over Europe - so worried he couldn&#x27;t sleep</li><li class=\"d0\">Got out of bed at night, canvas and paint, <b>tried to paint his own portrait in the mirror</b></li><li class=\"d1\">knew nothing about painting; did it to get his mind off worry</li><li class=\"d0\">No peace until he adopted <b>five words</b>: <i>&quot;One step enough for me.&quot;</i></li></ul>","img":["ch-01-live-in-day-tight-compartments-05.jpg"]},{"t":620,"lv":3,"h":"Ted Benjamino - Baltimore, 94th Infantry Division","b":"<ul><li class=\"d0\"><b>Graves registration NCO</b> - records of killed, missing, hospitalized; personal effects back to families</li><li class=\"d0\"><b>April 1945</b> - spasmodic transverse colon, intense pain</li><li class=\"d1\">worried about mistakes, about surviving, about <b>a 16-month-old son he&#x27;d never seen</b></li><li class=\"d1\"><b>lost 34 pounds</b>, hands skin and bone, wept whenever alone</li><li class=\"d0\">Army doctor after full exam: <b>&quot;your troubles are mental&quot;</b></li><li class=\"d1\"><b>The hourglass:</b> thousands of grains on top, all pass through the <b>narrow neck</b></li><li class=\"d1\">nothing makes <b>more than one grain</b> pass without wrecking the glass</li><li class=\"d1\">hundreds of tasks each morning - take them one at a time or <b>break your own structure</b></li><li class=\"d0\"><b>&quot;One grain of sand at a time, one task at a time.&quot;</b></li><li class=\"d1\">carried it into civilian work (PR/advertising director) - same pileup, same cure</li></ul>","img":["ch-01-live-in-day-tight-compartments-06.jpg"]},{"t":833,"lv":3,"h":"Mrs. E.K. Shields - Saginaw, Michigan","b":"<ul><li class=\"d0\"><b>1937</b> - husband died, depressed, nearly penniless</li><li class=\"d0\">Got her old job back selling <b>world books to rural school boards</b>; down payment on a used car</li><li class=\"d0\"><b>Spring 1938, Versailles, Missouri</b> - poor schools, bad roads, driving alone, eating alone</li><li class=\"d1\">afraid of car payments, room rent, food, failing health, no money for a doctor</li><li class=\"d1\"><b>considered suicide</b> - stopped only by her sister&#x27;s grief and no money for funeral expenses</li><li class=\"d0\">Read one sentence in an article: <b>&quot;Every day is a new life to a wise man.&quot;</b></li><li class=\"d1\">typed it, <b>pasted it on her windshield</b></li><li class=\"d1\"><i>&quot;Today is a new life&quot;</i> each morning -&gt; fear of loneliness and wanting gone</li></ul>","img":["ch-01-live-in-day-tight-compartments-07.jpg"]},{"t":940,"lv":2,"h":"The cost of living in the two eternities","b":"<ul><li class=\"d0\">Once, <b>half of all hospital beds</b> were reserved for nervous and mental cases</li><li class=\"d1\">collapsed under <b>accumulated yesterdays and fearful tomorrows</b></li><li class=\"d1\">most could have avoided it</li><li class=\"d0\">We stand at <b>the meeting place of two eternities</b> - the vast past, the plunging future</li><li class=\"d1\"><b>can&#x27;t live in either, not for a split second</b> - but trying wrecks body and mind</li><li class=\"d0\">Live <b>from now until bedtime</b></li><li class=\"d1\"><b>Robert Louis Stevenson:</b> anyone can carry his burden, however hard, <b>until nightfall</b>; live sweetly till the sun goes down - <i>&quot;this is all that life really means&quot;</i></li></ul>","img":["ch-01-live-in-day-tight-compartments-08.jpg"]},{"t":1002,"lv":2,"h":"The habit of putting off living","b":"<ul><li class=\"d0\"><b>Horace</b>, 30 years before Christ: <i>happy he who can call today his own</i> - sounds modern, isn&#x27;t</li><li class=\"d0\">We dream of a <b>magical rose garden over the horizon</b> instead of the <b>roses blooming outside the window</b></li><li class=\"d0\"><b>Stephen Leacock&#x27;s procession:</b> <i>when I&#x27;m a big boy</i> -&gt; <i>when I grow up</i> -&gt; <i>when I get married</i> -&gt; <i>when I retire</i></li><li class=\"d1\">then looks back - <b>a cold wind over the landscape. He missed it all.</b></li><li class=\"d1\"><b>&quot;Life is in the living, in the tissue of every day and hour.&quot;</b></li></ul>","img":[]},{"t":1105,"lv":3,"h":"Edward S. Evans - Detroit","b":"<ul><li class=\"d0\">Poverty -&gt; sold newspapers -&gt; grocer&#x27;s clerk -&gt; <b>assistant librarian</b>, 7 people dependent on him</li><li class=\"d1\"><b>8 years</b> before he had the courage to go out on his own</li><li class=\"d0\"><b>$55 borrowed</b> -&gt; a business making <b>$20,000/year</b></li><li class=\"d0\">Then the frost: <b>endorsed a note</b> for a friend who went bankrupt; <b>his bank collapsed</b></li><li class=\"d1\">lost every cent, <b>$16,000 in debt</b></li><li class=\"d0\">Fainted on the sidewalk, couldn&#x27;t walk, body broke out in boils, <b>doctor gave him two weeks</b></li><li class=\"d1\">drew up his will, lay back, <b>gave up, relaxed</b> - and slept like a baby for the first time in weeks</li><li class=\"d1\">appetite back, weight back, <b>crutches in a few weeks, back at work in six</b></li><li class=\"d0\">Took a <b>$30/week</b> job selling <b>wheel blocks</b> for freight shipping - after $20,000/year</li><li class=\"d1\"><b>&quot;No more regret about the past. No more dread of the future.&quot;</b></li><li class=\"d0\">Became president of <b>Evans Products Company</b> - NYSE-listed; <b>Evans Field</b> in Greenland named for him</li></ul>","img":["ch-01-live-in-day-tight-compartments-09.jpg"]},{"t":1270,"lv":2,"h":"The closers","b":"<ul><li class=\"d0\"><b>White Queen&#x27;s rule:</b> jam tomorrow, jam yesterday, <b>never jam today</b></li><li class=\"d1\">we stew over both instead of <b>spreading today&#x27;s jam on our bread</b></li><li class=\"d0\"><b>Montaigne:</b> <i>&quot;My life has been full of terrible misfortunes, most of which never happened.&quot;</i></li><li class=\"d0\"><b>Dante:</b> this day will never dawn again - and we&#x27;re racing through space <b>19 miles every second</b></li><li class=\"d0\"><b>Lowell Thomas</b> - Psalm 118 framed in his broadcasting studio</li><li class=\"d0\"><b>John Ruskin</b> - plain stone on the desk, one word carved: <b>TODAY</b></li><li class=\"d0\"><b>Kalidasa, &quot;Salutation to the Dawn&quot;</b> - Osler kept it on his desk, Carnegie on his shaving mirror</li><li class=\"d1\"><i>yesterday is a dream, tomorrow a vision; today well lived makes every yesterday a dream of happiness</i></li></ul>","img":["ch-01-live-in-day-tight-compartments-10.jpg"]},{"t":1379,"lv":2,"h":"Rule 1","b":"<ul><li class=\"p\"><b>Shut the iron doors on the past and the future. Live in day-tight compartments.</b></li></ul>","img":["ch-01-live-in-day-tight-compartments-11.jpg"]},{"t":1379,"lv":3,"h":"Five questions to answer in writing","b":"<ul><li class=\"num\"><span>1</span>Do I put off living in the present to worry about the future or yearn for a rose garden over the horizon?</li><li class=\"num\"><span>2</span>Do I embitter the present by regretting what is over and done with?</li><li class=\"num\"><span>3</span>Do I get up determined to <b>seize the day</b> - to get the utmost out of these 24 hours?</li><li class=\"num\"><span>4</span>Can I get more out of life by living in day-tight compartments?</li><li class=\"num\"><span>5</span><b>When shall I start?</b> Next week? Tomorrow? Today?</li></ul>","img":[]}]},{"n":2,"slug":"ch-02-a-magic-formula-for-solving-worry-situations","label":"Chapter 2","title":"A Magic Formula for Solving Worry Situations","audio":"ch-02-a-magic-formula-for-solving-worry-situations.mp3","dur":883,"imgs":["ch-02-a-magic-formula-for-solving-worry-situations-01.jpg","ch-02-a-magic-formula-for-solving-worry-situations-02.jpg","ch-02-a-magic-formula-for-solving-worry-situations-03.jpg","ch-02-a-magic-formula-for-solving-worry-situations-04.jpg","ch-02-a-magic-formula-for-solving-worry-situations-05.jpg","ch-02-a-magic-formula-for-solving-worry-situations-06.jpg","ch-02-a-magic-formula-for-solving-worry-situations-07.jpg","ch-02-a-magic-formula-for-solving-worry-situations-08.jpg","ch-02-a-magic-formula-for-solving-worry-situations-09.jpg","ch-02-a-magic-formula-for-solving-worry-situations-10.jpg","ch-02-a-magic-formula-for-solving-worry-situations-11.jpg"],"secs":[{"t":0,"lv":2,"h":"The setup","b":"<ul><li class=\"d0\">Promise: a <b>quick, sure-fire recipe</b> for worry, usable right away</li><li class=\"d0\">Source: <b>Willis H. Carrier</b>, engineer who <b>launched the air conditioning industry</b>, headed <b>Carrier Corporation</b>, Syracuse, NY</li><li class=\"d0\">Told to Carnegie over lunch at the <b>Engineers Club</b>, New York</li></ul>","img":["ch-02-a-magic-formula-for-solving-worry-situations-01.jpg","ch-02-a-magic-formula-for-solving-worry-situations-02.jpg"]},{"t":50,"lv":2,"h":"Carrier&#x27;s own crisis","b":"<ul><li class=\"d0\">Young man, worked for <b>Buffalo Forge Company</b>, Buffalo, NY</li><li class=\"d0\">Assignment: install a <b>gas-cleaning device</b> at <b>Pittsburgh Plate Glass Co.</b>, Crystal City, Missouri</li><li class=\"d1\">plant cost <b>millions</b></li><li class=\"d1\">purpose: strip impurities so gas could burn without injuring the engine</li><li class=\"d1\">method was <b>new</b> - tried only once before, under different conditions</li><li class=\"d0\"><b>Unforeseen difficulties</b> - worked, but not well enough to meet the guarantees</li><li class=\"d0\">Reaction: <b>stunned</b>, &quot;like a blow on the head,&quot; stomach twisting, <b>couldn&#x27;t sleep</b></li><li class=\"d0\">Common sense: worry <b>wasn&#x27;t getting him anywhere</b> - built a method instead</li><li class=\"d0\">Used it <b>30+ years</b> since</li></ul>","img":["ch-02-a-magic-formula-for-solving-worry-situations-03.jpg","ch-02-a-magic-formula-for-solving-worry-situations-04.jpg"]},{"t":102,"lv":3,"h":"The three steps","b":"<ul><li class=\"d0\"><b>Step 1 - face the worst</b></li><li class=\"d1\">analyze fearlessly, honestly</li><li class=\"d1\">worst case: no jail, no shooting</li><li class=\"d1\">could lose his <b>position</b></li><li class=\"d1\">employer could lose the <b>$20,000</b> invested in machinery</li><li class=\"d0\"><b>Step 2 - accept it</b></li><li class=\"d1\">reconciled himself: losing the job survivable - &quot;I can always get another position&quot;</li><li class=\"d1\">$20,000 could be charged to research - it&#x27;s an experiment</li><li class=\"d1\">result: <b>immediate relaxation</b>, a peace he hadn&#x27;t felt in days</li><li class=\"d0\"><b>Step 3 - improve on the worst</b></li><li class=\"d1\">calmly worked to reduce the $20,000 loss</li><li class=\"d1\">ran tests, found: spend another <b>$5,000</b> on equipment</li><li class=\"d1\">did it - instead of losing $20,000, the firm <b>made $15,000</b></li><li class=\"d0\">Worry <b>destroys concentration</b> - mind jumps everywhere, loses power of decision</li><li class=\"d1\">facing the worst + accepting it clears the &quot;vague imaginings,&quot; frees the mind to concentrate</li></ul>","img":["ch-02-a-magic-formula-for-solving-worry-situations-05.jpg"]},{"t":260,"lv":2,"h":"Why it works, psychologically","b":"<ul><li class=\"d0\">Yanks a worrier <b>down out of the gray clouds</b></li><li class=\"d0\">Plants feet <b>on solid ground</b> - can&#x27;t think anything through without it</li><li class=\"d0\"><b>Professor William James</b>, father of applied psychology, dead since <b>1910</b></li><li class=\"d1\">his own words: <b>&quot;be willing to have it so&quot;</b></li><li class=\"d1\">acceptance of what has happened = first step in overcoming any misfortune</li></ul>","img":["ch-02-a-magic-formula-for-solving-worry-situations-06.jpg","ch-02-a-magic-formula-for-solving-worry-situations-07.jpg"]},{"t":368,"lv":2,"h":"Example: the blackmailed oil dealer","b":"<ul><li class=\"d0\">New York oil dealer, student in Carnegie&#x27;s class</li><li class=\"d0\"><b>War regulations</b> - oil rationed</li><li class=\"d0\">Drivers secretly shorting deliveries, reselling the surplus themselves</li><li class=\"d0\">A fake <b>&quot;government inspector&quot;</b> shows up, demands <b>hush money</b></li><li class=\"d1\">documentary proof, threatens to go to the <b>district attorney</b></li><li class=\"d0\">Dealer personally clean, but firm liable for its employees&#x27; acts</li><li class=\"d1\">feared bad publicity would ruin the business his <b>father founded 24 years before</b></li><li class=\"d0\"><b>3 days and nights</b> - no eating, no sleeping, &quot;going around in crazy circles&quot;</li><li class=\"d0\">The dilemma: pay <b>$5,000</b>, or tell the man to do his damnedest</li><li class=\"d0\">Sunday night: picks up the worry booklet from his <b>Carnegie public-speaking class</b>, reads the <b>Carrier story</b></li><li class=\"d1\"><b>Step 1</b>: worst case = business ruined by publicity, not jail</li><li class=\"d1\"><b>Step 2</b>: accepts it - could get a job, knows oil</li><li class=\"d1\">the &quot;blue funk&quot; starts to lift, can think again</li><li class=\"d1\"><b>Step 3</b>: new angle appears - tell his <b>attorney</b> the whole situation</li><li class=\"d0\">Sees the lawyer first thing next morning - lawyer says go tell the <b>DA</b> the truth</li><li class=\"d0\">DA reveals: this blackmail racket had been running for <b>months</b> - the &quot;inspector&quot; a <b>crook wanted by police</b></li><li class=\"d0\">Slept &quot;like a log&quot; that night; huge relief after</li></ul>","img":["ch-02-a-magic-formula-for-solving-worry-situations-08.jpg"]},{"t":574,"lv":2,"h":"Example: Earl P. Haney&#x27;s world voyage","b":"<ul><li class=\"d0\"><b>Earl P. Haney</b>, Winchester, Massachusetts</li><li class=\"d0\">told to Carnegie <b>November 17, 1948</b>, Hotel Statler, Boston</li><li class=\"d0\"><b>Back in the 20s</b>: worry led to stomach <b>ulcers</b>, then a bad <b>hemorrhage</b></li><li class=\"d0\">Hospital tied to <b>Northwestern University</b> School of Medicine, Chicago</li><li class=\"d0\">Weight dropped: <b>175 lbs to 90 lbs</b></li><li class=\"d0\"><b>3 doctors</b>, including an ulcer specialist, call the case <b>incurable</b></li><li class=\"d0\">Diet: alkaline powders, a <b>tablespoon of half milk, half cream, every hour</b></li><li class=\"d0\">A nurse pumps his stomach with a <b>rubber tube</b>, night and morning, for months</li><li class=\"d0\">Decision: nothing left to lose - take the <b>trip around the world</b> he&#x27;d always wanted</li><li class=\"d1\">doctors: shocked, &quot;impossible,&quot; warned he&#x27;d be <b>buried at sea</b></li><li class=\"d1\">Haney: no - arranges a <b>casket</b>, ships it aboard, deal with the steamship line to freeze his body until it can go home to the family plot in <b>Broken Bow, Nebraska</b></li><li class=\"d1\">quotes <b>Omar Khayyam</b> on making the most before &quot;dust into dust&quot;</li><li class=\"d0\">Boards the <b>SS President Adams</b>, Los Angeles, heads for the Orient</li><li class=\"d1\">felt better the moment he boarded</li><li class=\"d1\">drops the powders and the stomach pump</li><li class=\"d1\">eats <b>strange native foods</b>, smokes <b>black cigars</b>, drinks <b>highballs</b></li><li class=\"d1\">sails through <b>monsoons and typhoons</b></li><li class=\"d1\">plays games, sings, makes friends, stays up half the night</li><li class=\"d1\">reaches <b>China and India</b> - his old business cares look like paradise next to real poverty and hunger</li><li class=\"d0\">Comes home: <b>gained back 90 lbs</b>, almost forgot he&#x27;d had an ulcer, never ill again</li><li class=\"d0\">Realizes in hindsight he&#x27;d used Carrier&#x27;s formula unconsciously:</li><li class=\"d1\">worst = <b>death</b></li><li class=\"d1\">accepted it - no choice, doctors said hopeless</li><li class=\"d1\">improved on it - squeeze the utmost enjoyment from the time left</li><li class=\"d0\">If he&#x27;d kept worrying aboard ship, he believes he&#x27;d have made the return voyage <b>inside his coffin</b></li><li class=\"d0\">Calm gave him a <b>new burst of energy</b> that <b>saved his life</b></li></ul>","img":["ch-02-a-magic-formula-for-solving-worry-situations-09.jpg","ch-02-a-magic-formula-for-solving-worry-situations-10.jpg"]},{"t":835,"lv":2,"h":"Rule 2","b":"<ul><li class=\"p\">\u2192 If you have a worry problem, apply Willis H. Carrier&#x27;s magic formula:</li><li class=\"num\"><span>1</span><b>What is the worst that can possibly happen?</b></li><li class=\"num\"><span>2</span><b>Prepare to accept it</b>, if you have to</li><li class=\"num\"><span>3</span><b>Then calmly proceed to improve</b> on the worst</li></ul>","img":["ch-02-a-magic-formula-for-solving-worry-situations-11.jpg"]}]},{"n":3,"slug":"ch-03-what-worry-may-do-to-you","label":"Chapter 3","title":"What Worry May Do to You","audio":"ch-03-what-worry-may-do-to-you.mp3","dur":1455,"imgs":["ch-03-what-worry-may-do-to-you-01.jpg","ch-03-what-worry-may-do-to-you-02.jpg","ch-03-what-worry-may-do-to-you-03.jpg","ch-03-what-worry-may-do-to-you-04.jpg","ch-03-what-worry-may-do-to-you-05.jpg","ch-03-what-worry-may-do-to-you-06.jpg","ch-03-what-worry-may-do-to-you-07.jpg","ch-03-what-worry-may-do-to-you-08.jpg","ch-03-what-worry-may-do-to-you-09.jpg","ch-03-what-worry-may-do-to-you-10.jpg"],"secs":[{"t":1,"lv":2,"h":"Epigraph","b":"<ul><li class=\"d0\">Dr. <b>Alexis Carrel</b>: &quot;Those who do not know how to fight worry die young.&quot;</li></ul>","img":["ch-03-what-worry-may-do-to-you-01.jpg"]},{"t":1,"lv":2,"h":"The doorbell that never rang","b":"<ul><li class=\"d0\">Neighbor rings Carnegie&#x27;s bell: get vaccinated against <b>smallpox</b></li><li class=\"d1\">thousands of volunteers ringing doorbells across NYC; stations in hospitals, firehouses, police precincts, plants</li><li class=\"d1\"><b>2,000+ doctors/nurses</b> working day and night</li><li class=\"d1\">cause of it all: <b>8 people</b> had smallpox, <b>2 died</b> - out of nearly <b>8 million</b></li><li class=\"d0\">No one ever rang his bell about <b>worry</b></li><li class=\"d1\">worry did <b>10,000x more damage</b> than smallpox in the same period</li><li class=\"d1\"><b>1 in 10</b> Americans will have a <b>nervous breakdown</b>, mostly from worry</li><li class=\"d0\">Carrel again: businessmen, housewives, horse doctors, bricklayers - all die young from worry</li></ul>","img":["ch-03-what-worry-may-do-to-you-02.jpg"]},{"t":108,"lv":2,"h":"What doctors say worry actually does","b":"<ul><li class=\"d0\">Vacation with <b>Dr. O.F. Gober</b>, chief physician, Gulf, Colorado &amp; Santa Fe Hospital Assoc.</li><li class=\"d1\"><b>70%</b> of his patients could cure themselves if rid of fears and worries</li><li class=\"d1\">illnesses <b>real</b>, not imaginary - &quot;sometimes a hundred times&quot; worse than a toothache</li><li class=\"d1\">nervous indigestion, stomach ulcers, heart disturbance, insomnia, headaches, paralysis</li><li class=\"d1\">Gober himself: <b>stomach ulcer for 12 years</b></li><li class=\"d1\">fear \u2192 worry \u2192 tense nerves \u2192 <b>gastric juices</b> turn abnormal \u2192 ulcers</li><li class=\"d0\"><b>Dr. Joseph Montague</b>, <i>Nervous Stomach Trouble</i>: not what you eat - <b>what&#x27;s eating you</b></li><li class=\"d0\"><b>Dr. W.C. Alvarez</b>, Mayo Clinic: ulcers rise and fall with emotional stress</li><li class=\"d1\">study of <b>15,000 patients</b>: <b>4 in 5</b> had no physical basis - fear, worry, hate, selfishness</li><li class=\"d0\"><i>Life</i> magazine: stomach ulcers now <b>10th</b> on the list of fatal diseases</li><li class=\"d0\"><b>Dr. Harold Habein</b>, Mayo Clinic: study of <b>176 executives</b>, average age <b>44.3</b></li><li class=\"d1\">just over <b>a third</b> already had heart disease, ulcers, or high blood pressure</li></ul>","img":[]},{"t":326,"lv":2,"h":"What price success?","b":"<ul><li class=\"d0\">Even owning the whole world - one bed, three meals a day</li><li class=\"d0\">Famous <b>cigarette manufacturer</b>: millions, dropped dead of heart failure at <b>61</b>, vacationing in the Canadian woods</li><li class=\"d0\">Carnegie&#x27;s father: <b>Missouri farmer</b>, died at <b>89</b> without a dollar - &quot;not half as successful&quot; as the millionaire</li></ul>","img":["ch-03-what-worry-may-do-to-you-03.jpg"]},{"t":389,"lv":2,"h":"The mind and body are one","b":"<ul><li class=\"d0\"><b>Mayo brothers</b>: over half of hospital beds hold people with nervous troubles</li><li class=\"d1\">under the microscope, post-mortem, nerves as healthy as <b>Jack Dempsey&#x27;s</b></li><li class=\"d1\">damage is emotional - futility, frustration, anxiety, fear, despair</li><li class=\"d0\"><b>Plato</b>: physicians&#x27; greatest mistake - curing the body without the mind</li><li class=\"d1\">took <b>2,300 years</b> to catch on \u2192 new field, <b>psychosomatic medicine</b></li><li class=\"d0\">medicine wiped out smallpox, cholera, yellow fever - still can&#x27;t touch worry, fear, hate, despair</li><li class=\"d0\">WWII draft: <b>1 in 6</b> young men rejected for <b>psychiatric reasons</b></li><li class=\"d0\">anxious person, unable to face reality, retreats into a private dream world \u2192 insanity</li></ul>","img":[]},{"t":500,"lv":2,"h":"Two books on the shelf","b":"<ul><li class=\"d0\">Podolsky, <i>Stop Worrying and Get Well</i> - chapters on worry and the heart, blood pressure, rheumatism, stomach, colds, thyroid, diabetes</li><li class=\"d0\">Menninger, <i>Man Against Himself</i> - how anxiety, frustration, hatred, resentment destroy body and mind</li></ul>","img":["ch-03-what-worry-may-do-to-you-04.jpg"]},{"t":550,"lv":2,"h":"Grant&#x27;s headache","b":"<ul><li class=\"d0\">Civil War: Grant besieging <b>Richmond</b>, nine months - Lee&#x27;s army ragged, deserting, burning warehouses, fleeing by night</li><li class=\"d0\">Grant falls behind, <b>half blind</b>, violent sick headache</li><li class=\"d1\">bathes feet in hot water and mustard, mustard plasters on wrists and neck</li><li class=\"d0\">Cured <b>instantly</b> - not by the mustard, but by a horseman bringing Lee&#x27;s <b>surrender</b> letter</li></ul>","img":[]},{"t":657,"lv":2,"h":"Morgenthau&#x27;s dizziness","b":"<ul><li class=\"d0\"><b>Henry Morgenthau Jr.</b>, Treasury Secretary under FDR</li><li class=\"d0\">FDR buys <b>4,400,000 bushels</b> of wheat in one day to raise the price</li><li class=\"d0\">Morgenthau: felt &quot;literally dizzy&quot; - went to bed for <b>two hours</b></li></ul>","img":["ch-03-what-worry-may-do-to-you-05.jpg"]},{"t":657,"lv":2,"h":"Close to home","b":"<ul><li class=\"d0\">Carnegie doesn&#x27;t need a library - <b>one block</b> from his own house:</li><li class=\"d1\">one house: worry \u2192 nervous breakdown</li><li class=\"d1\">another: worry over the stock market \u2192 <b>diabetes</b> (blood/urine sugar rose)</li><li class=\"d0\"><b>Montaigne</b>, mayor of Bordeaux: &quot;I am willing to take your affairs into my hands, but not into my <b>liver and lungs</b>&quot;</li><li class=\"d0\">even his own house: the former owner worried himself into an early grave</li></ul>","img":[]},{"t":770,"lv":2,"h":"Arthritis","b":"<ul><li class=\"d0\"><b>Dr. Russell L. Cecil</b>, arthritis authority - four commonest triggers:</li><li class=\"num\"><span>1</span>marital shipwreck</li><li class=\"num\"><span>2</span>financial disaster and grief</li><li class=\"num\"><span>3</span>loneliness and worry</li><li class=\"num\"><span>4</span>long-cherished resentments</li><li class=\"d0\">friend hit by the <b>Depression</b> - gas shut off, mortgage foreclosed</li><li class=\"d1\">his wife: sudden arthritis attack, persisted until their finances improved</li></ul>","img":["ch-03-what-worry-may-do-to-you-06.jpg"]},{"t":826,"lv":2,"h":"Teeth and thyroid","b":"<ul><li class=\"d0\"><b>Dr. McGonigal</b>: worry upsets <b>calcium balance</b> \u2192 decay</li><li class=\"d1\">patient with perfect teeth, wife suddenly ill - <b>3 weeks</b> in hospital \u2192 <b>9 cavities</b></li><li class=\"d0\">overactive thyroid: trembling, shaking, &quot;furnace... with all its drafts wide open&quot; - may <b>burn himself out</b> and die</li><li class=\"d1\"><b>Dr. Israel Bram</b>, Philadelphia, 38 years treating it - waiting-room sign: relaxation, recreation, healthy religion, sleep, music, laughter, faith</li><li class=\"d1\">heart trouble, ulcers, diabetes - all &quot;<b>first cousins</b>&quot;</li></ul>","img":["ch-03-what-worry-may-do-to-you-07.jpg"]},{"t":992,"lv":2,"h":"Merle Oberon&#x27;s mirror","b":"<ul><li class=\"d0\">refused to worry - it would ruin her <b>looks</b>, her one real asset</li><li class=\"d0\">breaking into film in <b>London</b>: no contacts, no jobs, <b>two weeks on crackers and water</b></li><li class=\"d0\">looked in the mirror, saw the <b>lines</b> worry was forming - decided then to stop</li><li class=\"d0\">worry generally: curdles the expression, forms a <b>permanent scowl</b>, turns hair gray or makes it fall out, causes rashes and pimples</li></ul>","img":[]},{"t":1047,"lv":2,"h":"Heart disease, by the numbers","b":"<ul><li class=\"d0\">the <b>#1 killer</b> in America</li><li class=\"d0\">WWII: <b>1/3 million</b> men killed in combat vs. <b>2 million</b> civilians killed by heart disease</li><li class=\"d1\"><b>1 million</b> of those from the worry/high-tension kind</li><li class=\"d0\"><b>William James</b>: &quot;The Lord may forgive us our sins, but the nervous system never does.&quot;</li><li class=\"d0\">more Americans die by suicide each year than from the <b>five</b> most common communicable diseases combined</li></ul>","img":["ch-03-what-worry-may-do-to-you-08.jpg"]},{"t":1047,"lv":2,"h":"The water torture","b":"<ul><li class=\"d0\">Chinese warlords: prisoners bound, a bag of water dripping on the head, day and night, until it drives them insane</li><li class=\"d1\">same method used in the Spanish Inquisition and German concentration camps under <b>Hitler</b></li><li class=\"d0\">worry: the same constant <b>drip, drip</b></li><li class=\"d0\">Carnegie as a Missouri boy, scared by Billy Sunday&#x27;s sermons on hellfire - Sunday never mentioned the real agony waiting for worriers: <b>angina pectoris</b></li></ul>","img":[]},{"t":1161,"lv":2,"h":"The way out","b":"<ul><li class=\"d0\">Carrel again: those who keep &quot;the peace of their inner selves&quot; amid the city&#x27;s tumult are immune to nervous disease</li><li class=\"d0\"><b>Thoreau</b>, <i>Walden</i>: no fact more encouraging than man&#x27;s power to elevate his life by conscious endeavor</li></ul>","img":["ch-03-what-worry-may-do-to-you-09.jpg"]},{"t":1214,"lv":2,"h":"Olga K. Jarvi&#x27;s story","b":"<ul><li class=\"d0\">of <b>Coeur d&#x27;Alene, Idaho</b> - <b>8.5 years</b> earlier condemned to a slow death from <b>cancer</b>, confirmed by the <b>Mayo brothers</b></li><li class=\"d0\">her doctor, impatient: &quot;Haven&#x27;t you any fight in you? ... face the facts, quit worrying, then do something about it.&quot;</li><li class=\"d0\">her oath: nails dug into her flesh, cold chills down her spine - &quot;I am not going to worry ... I am going to live.&quot;</li><li class=\"d0\">normal treatment: X-rays <b>10.5 minutes/day for 30 days</b> - she took <b>14.5 minutes/day for 49 days</b></li><li class=\"d0\">never cried once - forced herself to <b>smile</b>; believes a <b>cheerful attitude</b> helps the body fight</li><li class=\"d0\">result: one of the &quot;miracle cures&quot;</li></ul>","img":[]},{"t":1319,"lv":2,"h":"Close","b":"<ul><li class=\"d0\">repeats the title: &quot;Those who do not know how to fight worry die young.&quot;</li><li class=\"d0\">followers of <b>Muhammad</b> tattooed verses from the Koran on their breasts - Carnegie wishes he could tattoo this title on every reader&#x27;s breast</li></ul>","img":["ch-03-what-worry-may-do-to-you-10.jpg"]},{"t":1370,"lv":3,"h":"\u2192 Part One in a nutshell: Fundamental facts you should know about worry","b":"<ul><li class=\"d0\"><b>Rule 1</b>: live in <b>day-tight compartments</b> (Sir William Osler) - don&#x27;t stew about the future, live till bedtime</li><li class=\"d0\"><b>Rule 2</b>: <b>Willis H. Carrier&#x27;s</b> magic formula for Trouble-with-a-capital-T</li><li class=\"d1\">A. ask the <b>worst</b> that can possibly happen</li><li class=\"d1\">B. prepare mentally to <b>accept</b> it</li><li class=\"d1\">C. calmly try to <b>improve</b> on the worst</li><li class=\"d0\"><b>Rule 3</b>: remind yourself of the exorbitant price worry costs in <b>health</b></li><li class=\"p\">\u2192 Part Two: Basic techniques in analyzing worry</li></ul>","img":[]}]},{"n":4,"slug":"ch-04-how-to-analyze-and-solve-worry-problems","label":"Chapter 4","title":"How to Analyze and Solve Worry Problems","audio":"ch-04-how-to-analyze-and-solve-worry-problems.mp3","dur":901,"imgs":[],"secs":[{"t":0,"lv":2,"h":"Opening","b":"<ul><li class=\"d0\">Epigraph - <b>Kipling</b>: &quot;six honest serving men&quot; - what, why, when, how, where, who</li><li class=\"d0\">Does <b>Carrier&#x27;s magic formula</b> (Part 1, Ch. 2) solve all worry problems? <b>No.</b></li><li class=\"d0\">Answer: <b>three basic steps of problem analysis</b></li><li class=\"num\"><span>1</span><b>Get the facts</b></li><li class=\"num\"><span>2</span><b>Analyze the facts</b></li><li class=\"num\"><span>3</span><b>Arrive at a decision</b> - then <b>act</b> on it</li><li class=\"d0\"><b>Aristotle</b> taught and used it</li></ul>","img":[]},{"t":54,"lv":2,"h":"Rule 1: Get the facts","b":"<ul><li class=\"d0\">Without facts: just <b>stew in confusion</b></li><li class=\"d0\"><b>Dean Herbert E. Hawkes</b>, Columbia College - <b>22 years</b> - helped <b>200,000 students</b></li><li class=\"d1\">confusion = <b>chief cause of worry</b></li><li class=\"d1\">&quot;half the worry in the world&quot; - people deciding <b>before</b> sufficient knowledge</li><li class=\"d1\">his practice: problem due <b>3 o&#x27;clock next Tuesday</b> - refuses to decide till then, just gathers facts</li><li class=\"d1\">&quot;worries usually <b>evaporate</b> in the light of knowledge&quot;</li><li class=\"d1\">his own life now &quot;almost totally devoid of worry&quot;</li><li class=\"d0\">Most people don&#x27;t gather facts fairly</li><li class=\"d1\"><b>Edison</b>: &quot;no expedient to which a man will not resort to avoid the labor of thinking&quot;</li><li class=\"d1\">hunt &quot;<b>like bird dogs</b>&quot; only for facts that bolster what they already think</li><li class=\"d1\"><b>Andre Maurois</b>: agreeable facts &quot;seem true&quot;; disagreeable ones &quot;put us into a rage&quot;</li><li class=\"d1\">same as insisting <b>2 + 2 = 5</b> - or 500</li></ul>","img":[]},{"t":274,"lv":2,"h":"Getting the facts objectively","b":"<ul><li class=\"d0\">Hard when emotions &quot;riding high&quot;</li><li class=\"d0\">Two of Carnegie&#x27;s own techniques:</li><li class=\"num\"><span>1</span>Pretend gathering facts <b>for someone else</b>, not himself - kills the emotion</li><li class=\"num\"><span>2</span>Pretend to be a <b>lawyer arguing the other side</b> - write down both sides - truth usually lies <b>between</b> the two</li><li class=\"d0\">Not <b>Einstein</b>, not the <b>Supreme Court</b>, can decide well without facts first</li><li class=\"d0\"><b>Edison</b> left <b>2,500 notebooks</b> of facts at his death</li><li class=\"p\">\u2192 Rule 1 restated: get the facts, impartially, before attempting a solution</li></ul>","img":[]},{"t":332,"lv":2,"h":"Rule 2: Analyze the facts","b":"<ul><li class=\"d0\">Easier to analyze facts once <b>written down</b></li><li class=\"d0\"><b>Charles Kettering</b>: &quot;a problem well stated is a problem half solved&quot;</li></ul>","img":[]},{"t":439,"lv":2,"h":"Case: Galen Litchfield - Shanghai, 1942","b":"<ul><li class=\"d0\">Old acquaintance of Carnegie - top American businessman in the <b>Far East</b></li><li class=\"d0\">Manager, <b>Asia Life Insurance Company</b>, Shanghai</li><li class=\"d0\">Japan bombs <b>Pearl Harbor</b> - army swarms into Shanghai</li><li class=\"d0\">Japanese <b>liquidator</b> (an admiral) orders him to help liquidate the company&#x27;s assets - no choice; &quot;or else&quot; meant <b>death</b></li><li class=\"d0\">Left one block of securities off the list - worth <b>$750,000</b> - belonged to the Hong Kong branch</li><li class=\"d0\">Discovered - admiral <b>flew into a rage</b>, called him <b>thief and traitor</b></li><li class=\"d0\">Feared the <b>Bridge House</b> - the Japanese Gestapo&#x27;s torture chamber</li><li class=\"d1\">friends had <b>killed themselves</b> rather than be taken there</li><li class=\"d1\">friends had <b>died</b> there after <b>10 days</b> of questioning and torture</li><li class=\"d0\">Heard the news on a <b>Sunday afternoon</b></li></ul>","img":[]},{"t":542,"lv":3,"h":"His technique","b":"<ul><li class=\"d0\">Old habit: go to the <b>typewriter</b>, write two questions and their answers - writing clarifies thinking</li><li class=\"num\"><span>1</span><b>What am I worrying about?</b></li><li class=\"num\"><span>2</span><b>What can I do about it?</b></li><li class=\"d0\">That Sunday, at his room in the <b>Shanghai YMCA</b>:</li><li class=\"d1\">Q1: fear of the Bridge House <b>Monday morning</b></li><li class=\"d1\">Q2: hours spent listing <b>four possible courses of action</b> with likely consequences</li><li class=\"num\"><span>1</span><b>Explain</b> to the admiral - no English; interpreter might &quot;stir him up&quot; - risk of death</li><li class=\"num\"><span>2</span><b>Escape</b> - impossible; checks in and out of his room tracked - would be shot</li><li class=\"num\"><span>3</span><b>Stay in his room</b>, avoid the office - admiral grows suspicious, sends soldiers, no chance to explain</li><li class=\"num\"><span>4</span><b>Go to the office as usual</b> Monday - two chances to avoid the Bridge House</li><li class=\"d1\">Chose <b>plan four</b> - felt &quot;immensely relieved&quot;</li><li class=\"d0\">Monday morning: admiral glares, <b>cigarette dangling</b> from his mouth, says nothing</li><li class=\"d0\"><b>Six weeks later</b> the admiral recalled to <b>Tokyo</b> - worry over</li></ul>","img":[]},{"t":702,"lv":3,"h":"Litchfield&#x27;s reflection","b":"<ul><li class=\"d0\">Believes the exercise <b>saved his life</b></li><li class=\"d0\">Failure to reach a fixed decision - &quot;round and round in maddening circles&quot; - drives men to <b>nervous breakdowns</b></li><li class=\"d0\"><b>50%</b> of worry vanishes on reaching a <b>clear, definite decision</b></li><li class=\"d0\">another <b>40%</b> vanishes once he <b>starts carrying it out</b></li><li class=\"d0\">roughly <b>90%</b> of worry banished by four steps:</li><li class=\"num\"><span>1</span>Write precisely what he is worrying about</li><li class=\"num\"><span>2</span>Write what he can do about it</li><li class=\"num\"><span>3</span>Decide what to do</li><li class=\"num\"><span>4</span><b>Start immediately</b></li><li class=\"d0\">Later became <b>Far Eastern Director, Starr, Park and Freeman Inc.</b> - one of the most important American businessmen in Asia</li><li class=\"d0\">Credits much of his success to this method</li></ul>","img":[]},{"t":806,"lv":2,"h":"Rule 3: Act on the decision","b":"<ul><li class=\"d0\">Litchfield&#x27;s method: <b>efficient, concrete</b>, goes straight to the heart of the problem</li><li class=\"d0\">Climaxed by the indispensable third step - <b>do something about it</b></li><li class=\"d0\">Without action, fact-finding and analysis is &quot;<b>whistling up wind</b>&quot; - a sheer waste of energy</li><li class=\"d0\"><b>William James</b>: once a decision is reached and execution is due, &quot;dismiss absolutely all responsibility and care about the outcome&quot;</li><li class=\"d1\">don&#x27;t hesitate, doubt, or keep looking back over your shoulder</li><li class=\"d0\"><b>Waite Phillips</b>, prominent <b>Oklahoma</b> oil man, on carrying out decisions:</li><li class=\"d1\">past a certain point, more thinking only breeds <b>confusion and worry</b></li><li class=\"d1\">a time comes to <b>decide, act, and never look back</b></li></ul>","img":[]},{"t":860,"lv":2,"h":"The challenge","b":"<ul><li class=\"p\">Write down the answers to Litchfield&#x27;s four questions, right now, for one worry:</li><li class=\"num\"><span>1</span>What am I worrying about?</li><li class=\"num\"><span>2</span>What can I do about it?</li><li class=\"num\"><span>3</span>Here&#x27;s what I am going to do about it.</li><li class=\"num\"><span>4</span>When am I going to start doing it?</li></ul>","img":[]}]},{"n":5,"slug":"ch-05-how-to-eliminate-fifty-percent-of-your-business-worries","label":"Chapter 5","title":"How to Eliminate Fifty Percent of Your Business Worries","audio":"ch-05-how-to-eliminate-fifty-percent-of-your-business-worries.mp3","dur":559,"imgs":["ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-01.jpg","ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-02.jpg","ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-03.jpg","ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-04.jpg","ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-05.jpg","ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-06.jpg","ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-07.jpg","ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-08.jpg","ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-09.jpg","ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-10.jpg","ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-11.jpg"],"secs":[{"t":10,"lv":2,"h":"Chapter 5: How to Eliminate Fifty Percent of Your Business Worries","b":"","img":["ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-01.jpg","ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-02.jpg"]},{"t":63,"lv":2,"h":"Opening challenge","b":"<ul><li class=\"d0\">Skeptical businessman, <b>19 years</b> running his own company - &quot;absurd&quot; to think anyone can cut his worries</li><li class=\"d0\">Carnegie: can&#x27;t promise 50% himself - &quot;no one can do that except yourself&quot;</li><li class=\"d0\">Recalls Dr. <b>Alexis Carrel</b> - those who don&#x27;t know how to fight worry <b>die young</b></li><li class=\"d0\">Would <b>10%</b> be worth having?</li><li class=\"d0\">Promise: an executive who cut not 50% but <b>75%</b> of the time he spent worrying in conferences</li><li class=\"d0\">Real name, real place, checkable - <b>Leon Shimkin</b>, general manager, <b>Simon and Schuster</b>, Rockefeller Center, New York</li></ul>","img":["ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-03.jpg"]},{"t":118,"lv":2,"h":"Shimkin&#x27;s story","b":"<ul><li class=\"d0\"><b>15 years</b>: half of every business day in conferences arguing problems</li><li class=\"d1\">tense, twisting in chairs, walking the floor, arguing, going in circles</li><li class=\"d1\">end of day: utterly <b>exhausted</b></li><li class=\"d1\">assumed this was just how it would always be</li><li class=\"d0\">Devised a plan, used it <b>8 years</b> - transformed efficiency, health, happiness</li></ul>","img":["ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-04.jpg"]},{"t":169,"lv":3,"h":"Old way (scrapped)","b":"<ul><li class=\"d0\">Associate recites all the details of what went wrong</li><li class=\"d0\">Ends with &quot;what shall we do?&quot;</li></ul>","img":["ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-05.jpg"]},{"t":221,"lv":3,"h":"New rule","b":"<ul><li class=\"d0\">Anyone bringing him a problem first submits a memo answering:</li><li class=\"num\"><span>1</span>What is the problem?</li><li class=\"num\"><span>2</span>What is the cause of the problem?</li><li class=\"num\"><span>3</span>What are all the possible solutions of the problem?</li><li class=\"num\"><span>4</span>What solution do you suggest?</li></ul>","img":["ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-06.jpg"]},{"t":271,"lv":3,"h":"Result","b":"<ul><li class=\"d0\">Associates stopped bringing him problems at all - answering the four questions forces the facts and the thinking first</li><li class=\"d0\"><b>3/4</b> of cases: the solution &quot;popped out like a piece of bread popping out from an electric toaster&quot; - no consult needed</li><li class=\"d0\">Remaining cases: discussion time cut to about <b>1/3</b> of what it used to be</li><li class=\"d0\">Far less time spent worrying about what&#x27;s wrong, far more action toward making things right</li></ul>","img":["ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-07.jpg"]},{"t":321,"lv":2,"h":"Bettger&#x27;s story","b":"<ul><li class=\"d0\">Friend <b>Frank Bettger</b> - one of the top insurance men in America</li><li class=\"d0\">Same kind of method - worries down, income nearly <b>doubled</b></li><li class=\"d0\">Started full of enthusiasm, then grew discouraged - nearly quit</li><li class=\"d0\">One <b>Saturday morning</b>: sat down to find the root of the worry</li><li class=\"num\"><span>1</span>What is the problem? - not enough return for the calls he was making</li><li class=\"d1\">sold well right up to the close, then: &quot;I&#x27;ll think it over... come in and see me again&quot;</li><li class=\"d1\">the follow-up calls were the drain, the source of the discouragement</li><li class=\"num\"><span>2</span>What are the possible solutions? - studied the facts</li><li class=\"d1\">pulled his record book, last <b>12 months</b></li><li class=\"d1\">discovery: <b>70%</b> of sales closed on the 1st interview</li><li class=\"d1\"><b>23%</b> closed on the 2nd interview</li><li class=\"d1\">only <b>7%</b> closed on the 3rd, 4th, 5th+ interviews</li><li class=\"d1\">those follow-ups ate half his working day for <b>7%</b> of his sales</li><li class=\"num\"><span>3</span>What is the answer? - obvious once seen</li><li class=\"d1\">cut every visit beyond the 2nd interview</li><li class=\"d1\">put the freed time into new prospects</li><li class=\"d1\">cash value of every visit he made <b>doubled</b></li><li class=\"d0\">Went from near quitting to one of the best-known life insurance salesmen in the country</li></ul>","img":["ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-08.jpg"]},{"t":426,"lv":2,"h":"The four questions, again","b":"<ul><li class=\"num\"><span>1</span>What is the problem?</li><li class=\"num\"><span>2</span>What is the cause of the problem?</li><li class=\"num\"><span>3</span>What are all possible solutions to the problem?</li><li class=\"num\"><span>4</span>What solution do you suggest?</li><li class=\"d0\">Claim: apply these, cut your worries by <b>50%</b></li></ul>","img":["ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-09.jpg"]},{"t":480,"lv":2,"h":"Part 2: Basic techniques in analyzing worry","b":"<ul><li class=\"num\"><span>1</span><b>Get the facts</b> - Dean <b>Hawkes</b> of <b>Columbia University</b>: half the world&#x27;s worry comes from people deciding before they have enough facts to decide on</li><li class=\"num\"><span>2</span>Weigh all the facts, then <b>come to a decision</b></li><li class=\"num\"><span>3</span>Once decided, <b>act</b> - get busy, dismiss all anxiety about the outcome</li><li class=\"num\"><span>4</span>When tempted to worry, write out and answer:</li><li class=\"p\">A. What is the problem?</li><li class=\"p\">B. What is the cause of the problem?</li><li class=\"p\">C. What are all possible solutions?</li><li class=\"p\">D. What is the best solution?</li></ul>","img":["ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-10.jpg"]},{"t":480,"lv":2,"h":"Leads into","b":"<ul><li class=\"d0\">Part 3: How to break the worry habit before it breaks you</li></ul>","img":["ch-05-how-to-eliminate-fifty-percent-of-your-business-worries-11.jpg"]}]},{"n":6,"slug":"ch-06-how-to-crowd-worry-out-of-your-mind","label":"Chapter 6","title":"How to Crowd Worry Out of Your Mind","audio":"ch-06-how-to-crowd-worry-out-of-your-mind.mp3","dur":1209,"imgs":["ch-06-how-to-crowd-worry-out-of-your-mind-01.jpg","ch-06-how-to-crowd-worry-out-of-your-mind-02.jpg","ch-06-how-to-crowd-worry-out-of-your-mind-03.jpg","ch-06-how-to-crowd-worry-out-of-your-mind-04.jpg","ch-06-how-to-crowd-worry-out-of-your-mind-05.jpg","ch-06-how-to-crowd-worry-out-of-your-mind-06.jpg","ch-06-how-to-crowd-worry-out-of-your-mind-07.jpg","ch-06-how-to-crowd-worry-out-of-your-mind-08.jpg","ch-06-how-to-crowd-worry-out-of-your-mind-09.jpg","ch-06-how-to-crowd-worry-out-of-your-mind-10.jpg"],"secs":[{"t":0,"lv":2,"h":"Chapter 6 \u2014 How to Crowd Worry Out of Your Mind","b":"","img":["ch-06-how-to-crowd-worry-out-of-your-mind-01.jpg"]},{"t":52,"lv":3,"h":"Notes","b":"","img":["ch-06-how-to-crowd-worry-out-of-your-mind-02.jpg"]},{"t":52,"lv":2,"h":"Marion J. Douglas \u2014 double tragedy","b":"<ul><li class=\"d0\">Real story, <b>pseudonym</b> used at his request</li><li class=\"d0\">Lost <b>five-year-old daughter</b></li><li class=\"d0\"><b>10 months later</b> \u2014 second daughter died in <b>five days</b></li><li class=\"d0\">Couldn&#x27;t sleep, eat, rest, relax</li><li class=\"d0\">Doctors: <b>sleeping pills</b>, a <b>trip</b> \u2014 neither helped</li><li class=\"d0\">Felt &quot;encased in a <b>vise</b>,&quot; jaws tightening \u2014 the tension of grief</li></ul>","img":[]},{"t":103,"lv":2,"h":"The boat","b":"<ul><li class=\"d0\">One child left \u2014 <b>four-year-old son</b></li><li class=\"d0\">Son: &quot;Daddy, will you build a boat for me?&quot;</li><li class=\"d0\">Reluctant \u2014 gave in anyway</li><li class=\"d0\">Took about <b>three hours</b></li><li class=\"d0\">First <b>mental relaxation and peace</b> in months</li><li class=\"d0\">Realized: <b>hard to worry while busy planning and thinking</b></li><li class=\"d0\">Boat &quot;knocked worry out of the ring&quot;</li></ul>","img":["ch-06-how-to-crowd-worry-out-of-your-mind-03.jpg"]},{"t":154,"lv":2,"h":"Filling the life","b":"<ul><li class=\"d0\">Next night: room to room, listing jobs needing repair</li><li class=\"d1\">bookcases, stair steps, storm windows, shades, knobs, locks, leaky faucets</li><li class=\"d0\">Two weeks \u2192 list of <b>242 items</b></li><li class=\"d0\">Most completed over <b>two years</b></li><li class=\"d0\">Added: adult education classes, <b>two nights a week</b>, New York</li><li class=\"d0\"><b>Chairman of the school board</b></li><li class=\"d0\">Collects money for the <b>Red Cross</b></li><li class=\"d0\">&quot;So busy now... no time for worry&quot;</li></ul>","img":["ch-06-how-to-crowd-worry-out-of-your-mind-04.jpg"]},{"t":204,"lv":2,"h":"Busy men who couldn&#x27;t afford to worry","b":"<ul><li class=\"d0\"><b>Winston Churchill</b> \u2014 18-hour days at the height of the war</li><li class=\"d1\">&quot;<b>I&#x27;m too busy. I have no time for worry.</b>&quot;</li><li class=\"d0\"><b>Charles Kettering</b> \u2014 inventing the automobile <b>self-starter</b></li><li class=\"d1\">Later vice president, <b>General Motors Research</b></li><li class=\"d1\">Then: too poor \u2014 lab in a <b>barn hayloft</b></li><li class=\"d1\"><b>$1,500</b> his wife earned giving piano lessons</li><li class=\"d1\">Borrowed <b>$500</b> on his life insurance</li><li class=\"d1\">Wife: &quot;I was so worried I couldn&#x27;t sleep&quot; \u2014 he wasn&#x27;t, too absorbed</li><li class=\"d0\"><b>Pasteur</b> \u2014 peace found in libraries and laboratories</li><li class=\"d1\">too absorbed in work to worry about themselves</li><li class=\"d1\">research men rarely have nervous breakdowns</li></ul>","img":[]},{"t":254,"lv":2,"h":"The one-thought law","b":"<ul><li class=\"d0\">Fundamental law of psychology: mind can&#x27;t hold <b>two thoughts at once</b></li><li class=\"d0\">Try it \u2014 Statue of Liberty + tomorrow&#x27;s plans, never both together</li><li class=\"d0\">Same true of emotions \u2014 enthusiasm and worry can&#x27;t coexist</li></ul>","img":["ch-06-how-to-crowd-worry-out-of-your-mind-05.jpg"]},{"t":365,"lv":2,"h":"Army psychiatry","b":"<ul><li class=\"d0\">WWII \u2014 shattered men labeled <b>psychoneurotic</b></li><li class=\"d0\">Cure: &quot;<b>Keep &#x27;em busy</b>&quot;</li><li class=\"d0\">Outdoor activity: fishing, hunting, ball, golf, photography, gardening, dancing</li><li class=\"d0\">No time left for brooding</li><li class=\"d0\">Term: <b>occupational therapy</b></li><li class=\"d1\">Greek physicians used it <b>500 years before Christ</b></li><li class=\"d1\">Quakers, <b>Philadelphia</b>, Ben Franklin&#x27;s era</li><li class=\"d1\">Visitor to a Quaker sanitarium, <b>1774</b> \u2014 patients spinning flax, improved by the work</li></ul>","img":[]},{"t":418,"lv":2,"h":"Longfellow","b":"<ul><li class=\"d0\">Wife died \u2014 sealing wax caught her clothes on fire</li><li class=\"d0\">Nearly lost his mind to the memory</li><li class=\"d0\"><b>Three small children</b> needed him</li><li class=\"d0\">Walks, stories, games \u2014 wrote &quot;<b>The Children&#x27;s Hour</b>&quot;</li><li class=\"d0\">Translated <b>Dante</b></li><li class=\"d0\">Kept so busy he regained his peace of mind</li></ul>","img":["ch-06-how-to-crowd-worry-out-of-your-mind-06.jpg"]},{"t":522,"lv":2,"h":"Tennyson / the vacuum","b":"<ul><li class=\"d0\">On losing friend <b>Arthur Hallam</b>: &quot;<b>I must lose myself in action lest I wither in despair</b>&quot;</li><li class=\"d0\">Idle mind = nature&#x27;s vacuum \u2014 like a broken light bulb, air rushes in</li><li class=\"d0\">Empty mind fills with <b>emotion</b> \u2014 worry, fear, hate, jealousy, envy</li><li class=\"d0\"><b>James L. Mercell</b>, Columbia Teachers College \u2014 worry rides hardest once the day&#x27;s work is done</li><li class=\"d1\">idle mind = &quot;<b>motor operating without its load</b>&quot; \u2014 races, burns its bearings</li></ul>","img":["ch-06-how-to-crowd-worry-out-of-your-mind-07.jpg"]},{"t":623,"lv":2,"h":"Chicago housewife","b":"<ul><li class=\"d0\">Met on a train, New York to Missouri farm</li><li class=\"d0\">Son joined up the <b>day after Pearl Harbor</b></li><li class=\"d0\">Dismissed her maid, did the housework herself \u2014 didn&#x27;t help, too mechanical</li><li class=\"d0\">Took a job: <b>saleswoman</b>, department store</li><li class=\"d0\">Customers swarming all day \u2014 no second to think</li><li class=\"d0\">Fell into bed each night \u2014 &quot;<b>neither time nor energy to worry</b>&quot;</li><li class=\"d0\">Echoes <b>John Cowper Powys</b> \u2014 absorbed work brings a &quot;happy numbness&quot;</li></ul>","img":[]},{"t":731,"lv":2,"h":"Osa Johnson","b":"<ul><li class=\"d0\">Book: &quot;<b>I Married Adventure</b>&quot;</li><li class=\"d0\">Married <b>Martin Johnson</b> at <b>16</b>, from Chanute, Kansas, to the jungle trails of <b>Borneo</b></li><li class=\"d0\"><b>25 years</b> filming vanishing wildlife across Asia and Africa</li><li class=\"d0\">Plane out of <b>Denver</b> plunged into a mountain \u2014 Martin killed instantly</li><li class=\"d0\">Doctors: she would never leave her bed again</li><li class=\"d0\"><b>Three months later</b> \u2014 lecturing from a wheelchair</li><li class=\"d0\">Addressed <b>over 100 audiences</b> that season</li><li class=\"d0\">&quot;I did it so I would have no time for sorrow and worry&quot;</li><li class=\"d0\">Echoes Tennyson \u2014 lose herself in action</li></ul>","img":["ch-06-how-to-crowd-worry-out-of-your-mind-08.jpg"]},{"t":783,"lv":2,"h":"Admiral Byrd","b":"<ul><li class=\"d0\"><b>Five months alone</b>, shack buried in the South Pole ice cap</li><li class=\"d0\">Ice cap larger than the <b>United States and Europe combined</b></li><li class=\"d0\">No living creature within <b>100 miles</b></li><li class=\"d0\">Book: &quot;<b>Alone</b>&quot;</li><li class=\"d0\">Nightly ritual \u2014 blocked out tomorrow&#x27;s hours:</li><li class=\"num\"><span>1</span>an hour \u2014 the escape tunnel</li><li class=\"num\"><span>2</span>a half hour \u2014 leveling drift</li><li class=\"num\"><span>3</span>an hour \u2014 straightening the fuel drums</li><li class=\"num\"><span>4</span>an hour \u2014 cutting bookshelves in the food tunnel</li><li class=\"num\"><span>5</span>two hours \u2014 renewing a broken bridge in the sledge</li><li class=\"d0\">Gave him an &quot;extraordinary sense of command over myself&quot;</li><li class=\"d0\">Without purpose, days &quot;end in disintegration&quot;</li></ul>","img":["ch-06-how-to-crowd-worry-out-of-your-mind-09.jpg"]},{"t":952,"lv":2,"h":"Cabot and Darwin","b":"<ul><li class=\"d0\"><b>Dr. Richard C. Cabot</b>, Harvard \u2014 <i>What Men Live By</i></li><li class=\"d0\">Work cures the &quot;<b>trembling palsy of the soul</b>&quot;</li><li class=\"d0\">Courage from work \u2014 Emerson&#x27;s self-reliance</li><li class=\"d0\"><b>Charles Darwin&#x27;s</b> term: &quot;<b>wibber jibbers</b>&quot; \u2014 old-fashioned gremlins hatched by idleness, destroy will and action</li></ul>","img":[]},{"t":1003,"lv":2,"h":"Tremper Ongman","b":"<ul><li class=\"d0\">Story told <b>18 years</b> after it happened, late supper after class</li><li class=\"d0\">Treasurer, <b>Crown Fruit and Extract Company</b></li><li class=\"d0\"><b>Half a million dollars</b> in strawberries, packed in gallon tins</li><li class=\"d0\"><b>20 years</b> selling to ice cream manufacturers</li><li class=\"d0\"><b>National Dairy</b> and <b>Borton</b> switch to buying in barrels \u2014 sales stop cold</li><li class=\"d0\">Still under contract for <b>a million dollars more</b> strawberries, next 12 months</li><li class=\"d0\">Already borrowed <b>$350,000</b> from the banks</li><li class=\"d0\">Trip to <b>Watsonville, California</b> factory; sold the surplus fresh in <b>San Francisco</b></li><li class=\"d0\">Still worried \u2014 habit \u2014 cherries from Italy, pineapples from Hawaii</li><li class=\"d0\">Cure: worked <b>15 to 16 hours a day</b> instead of seven</li><li class=\"d1\">8 a.m. to nearly midnight, for <b>three months</b></li><li class=\"d1\">Broke the habit \u2014 back to a normal 7-8 hour day</li><li class=\"d1\"><b>No insomnia or worry since</b> \u2014 18 years running</li></ul>","img":["ch-06-how-to-crowd-worry-out-of-your-mind-10.jpg"]},{"t":1159,"lv":2,"h":"Shaw / Rule One","b":"<ul><li class=\"d0\"><b>George Bernard Shaw</b>: the secret of misery is leisure to wonder if you&#x27;re happy</li><li class=\"d0\">&quot;Spit on your hands and get busy&quot;</li><li class=\"d0\">A busy body drives worry from the mind</li><li class=\"d0\"><b>Rule One: Keep busy.</b> The worried person must lose himself in action, lest he wither in despair.</li></ul>","img":[]}]},{"n":7,"slug":"ch-07-don-t-let-the-beetles-get-you-down","label":"Chapter 7","title":"Don't Let the Beetles Get You Down","audio":"ch-07-don-t-let-the-beetles-get-you-down.mp3","dur":932,"imgs":["ch-07-don-t-let-the-beetles-get-you-down-01.jpg","ch-07-don-t-let-the-beetles-get-you-down-02.jpg","ch-07-don-t-let-the-beetles-get-you-down-03.jpg","ch-07-don-t-let-the-beetles-get-you-down-04.jpg","ch-07-don-t-let-the-beetles-get-you-down-05.jpg","ch-07-don-t-let-the-beetles-get-you-down-06.jpg","ch-07-don-t-let-the-beetles-get-you-down-07.jpg","ch-07-don-t-let-the-beetles-get-you-down-08.jpg","ch-07-don-t-let-the-beetles-get-you-down-09.jpg","ch-07-don-t-let-the-beetles-get-you-down-10.jpg","ch-07-don-t-let-the-beetles-get-you-down-11.jpg"],"secs":[{"t":1,"lv":2,"h":"The Submarine \u2014 Robert Moore&#x27;s Story","b":"<ul><li class=\"d0\">Told by <b>Robert Moore</b>, Maplewood, NJ</li><li class=\"d0\"><b>March 1945</b>, submarine <b>Baya SS318</b>, off <b>Indochina</b></li><li class=\"d0\"><b>88 men</b> aboard, submerged at <b>276ft</b></li><li class=\"d0\">Periscope sighting: destroyer escort, tanker, minelayer</li><li class=\"d0\">Fired <b>3 torpedoes</b> \u2014 all missed, mechanical failure</li><li class=\"d0\">Japanese plane spotted sub at 60ft, radioed the minelayer</li><li class=\"d0\">Dove to <b>150ft</b>, rigged for depth charge</li><li class=\"d1\">extra bolts on the hatches</li><li class=\"d1\">fans, cooling, all electrical gear shut off \u2014 total silence</li><li class=\"d0\">3 minutes later: <b>6 depth charges</b>, sub pushed to ocean floor at 276ft</li><li class=\"d0\">Under 1,000ft = dangerous; under 500ft = almost always fatal \u2014 they were in barely half that</li><li class=\"d0\">Charge within <b>17ft</b> blows a hole; scores landed within <b>50ft</b></li><li class=\"d0\">Ordered to lie in bunks, stay calm</li><li class=\"d0\">Air <b>over 100\u00b0</b> \u2014 yet he wore a <b>sweater and fur-lined jacket</b>, still shivered, teeth chattered, cold clammy sweat</li><li class=\"d0\">Attack lasted <b>15 hours</b> \u2014 felt like &quot;15 million years&quot;</li><li class=\"d0\">Life flashed back: worried over</li><li class=\"d1\">bank clerk job \u2014 long hours, low pay, no advancement</li><li class=\"d1\">no house, no car, no nice clothes for his wife</li><li class=\"d1\">a nagging boss</li><li class=\"d1\">quarrels with his wife over trifles</li><li class=\"d1\">a <b>scar</b> on his forehead from a car wreck</li><li class=\"d0\">Vowed: see the sun and stars again, <b>never worry again</b></li><li class=\"d0\">Learned more in 15 hours than <b>4 years</b> at <b>Syracuse University</b></li></ul>","img":["ch-07-don-t-let-the-beetles-get-you-down-01.jpg","ch-07-don-t-let-the-beetles-get-you-down-02.jpg"]},{"t":334,"lv":2,"h":"Big Disasters vs. Tiny Irritations","b":"<ul><li class=\"d0\"><b>Samuel Pepys</b>&#x27;s diary: Sir Harry Vane, facing execution, pled only that the axeman spare the <b>boil</b> on his neck</li><li class=\"d0\"><b>Admiral Byrd</b>, polar camp, <b>80 below zero</b></li><li class=\"d1\">bunkmates stopped speaking \u2014 each accused the other of stealing gear space</li><li class=\"d1\">one man skipped the mess hall to dodge a man who chewed <b>28 times</b> before swallowing</li><li class=\"d1\">&quot;little things... drive even disciplined men to the edge of insanity&quot;</li><li class=\"d0\">Same in marriage:</li><li class=\"d1\"><b>Judge Joseph Sabbath</b>, Chicago \u2014 arbiter in <b>40,000</b> unhappy marriages: trivialities at the bottom of most marital unhappiness</li><li class=\"d1\"><b>Frank S. Hogan</b>, former DA of NY County \u2014 <b>half</b> of criminal cases start with little things: barroom bravado, an insulting remark, a rude action</li></ul>","img":["ch-07-don-t-let-the-beetles-get-you-down-03.jpg"]},{"t":390,"lv":2,"h":"Little Things That Wreck a Dinner","b":"<ul><li class=\"d0\"><b>Eleanor Roosevelt</b>, young bride, worried for days over a <b>poor meal</b> from a new cook \u2014 later: &quot;I would shrug my shoulders and forget it&quot;</li><li class=\"d0\"><b>Catherine the Great</b> laughed off a spoiled meal</li><li class=\"d0\">Carnegie&#x27;s dinner in Chicago: host fumbled carving; his wife scolded him in front of guests \u2014 &quot;he&#x27;s always making mistakes&quot; \u2014 married <b>20 years</b></li><li class=\"d1\">Carnegie: would rather eat <b>hot dogs with mustard</b> in peace than Peking duck amid scolding</li><li class=\"d0\">Carnegie&#x27;s own party: <b>3 napkins</b> didn&#x27;t match the tablecloth, the other three at the laundry, guests already at the door</li><li class=\"d1\">Mrs. Carnegie: almost cried, decided to let it go \u2014 went in, had a good time \u2014 no one noticed</li><li class=\"d0\">Latin maxim: <b>de minimis non curat lex</b> \u2014 the law itself ignores trifles</li></ul>","img":["ch-07-don-t-let-the-beetles-get-you-down-04.jpg","ch-07-don-t-let-the-beetles-get-you-down-05.jpg"]},{"t":500,"lv":2,"h":"Changing the Story \u2014 Homer Croy&#x27;s Radiators","b":"<ul><li class=\"d0\"><b>Homer Croy</b>, author of <i>They Had to See Paris</i> \u2014 New York apartment radiators drove him crazy</li><li class=\"d0\">Camping trip: fire limbs crackling \u2014 sounded just like the radiator</li><li class=\"d0\">Told himself the radiator noise was the same pleasant crackle \u2014 aware for a few days, then forgot it completely</li></ul>","img":["ch-07-don-t-let-the-beetles-get-you-down-06.jpg"]},{"t":662,"lv":2,"h":"Life Is Too Short to Be Little","b":"<ul><li class=\"d0\"><b>Disraeli</b>: &quot;Life is too short to be little&quot; \u2014 quoted by Andre Maurois in <i>This Week</i></li><li class=\"d0\"><b>Rudyard Kipling</b> married <b>Caroline Balestier</b>, built a home in <b>Brattleboro, Vermont</b></li><li class=\"d1\">brother-in-law <b>Beatty Balestier</b>, once his best friend, kept rights to cut hay off land Kipling bought</li><li class=\"d1\">Kipling planted a <b>flower garden</b> on the hayfield \u2014 Balestier furious</li><li class=\"d1\">Balestier later forced Kipling off his bicycle with a team of horses</li><li class=\"d1\">Kipling \u2014 author of &quot;If you can keep your head&quot; \u2014 lost his own, swore a warrant for Balestier&#x27;s arrest</li><li class=\"d1\">Sensational trial, reporters poured in from the big cities, story flashed worldwide, nothing settled</li><li class=\"d1\">Kipling and his wife abandoned their American home for life \u2014 all over <b>a load of hay</b></li><li class=\"d0\"><b>Pericles</b>, 24 centuries ago: &quot;we sit too long on trifles&quot;</li></ul>","img":["ch-07-don-t-let-the-beetles-get-you-down-07.jpg"]},{"t":767,"lv":2,"h":"The Beetles and the Giant Tree","b":"<ul><li class=\"d0\">Told by <b>Dr. Harry Emerson Fosdick</b></li><li class=\"d0\"><b>Long&#x27;s Peak, Colorado</b> \u2014 tree stood roughly <b>400 years</b></li><li class=\"d1\">a seedling when Columbus landed at San Salvador</li><li class=\"d1\">half-grown when the Pilgrims settled Plymouth</li><li class=\"d0\">Struck by lightning <b>14 times</b>, survived four centuries of storms and avalanches</li><li class=\"d0\">Finally felled by an army of <b>beetles</b> \u2014 ate through the bark, destroyed its inner strength</li><li class=\"d0\">Beetles small enough to crush between a finger and thumb</li><li class=\"d0\">&quot;Aren&#x27;t we all like that battling giant... only to let our hearts be eaten out by little beetles of worry?&quot;</li></ul>","img":["ch-07-don-t-let-the-beetles-get-you-down-08.jpg","ch-07-don-t-let-the-beetles-get-you-down-09.jpg"]},{"t":838,"lv":2,"h":"The Whistle \u2014 Charles Seyfried","b":"<ul><li class=\"d0\">Carnegie in <b>Teton National Park, Wyoming</b>, with <b>Charles Seyfried</b>, Wyoming highway superintendent</li><li class=\"d0\">Headed to the <b>John D. Rockefeller</b> estate \u2014 Carnegie&#x27;s car took a wrong turn, arrived an hour late</li><li class=\"d0\">Seyfried held the only key \u2014 waited an hour in hot, <b>mosquito</b>-infested woods</li><li class=\"d0\">Instead of cussing, he cut a limb from an <b>aspen</b> and carved a whistle</li><li class=\"d0\">Carnegie kept the whistle as a memento of a man who put trifles in their place</li></ul>","img":["ch-07-don-t-let-the-beetles-get-you-down-10.jpg"]},{"t":890,"lv":2,"h":"Rule 2","b":"<ul><li class=\"d0\">Don&#x27;t let ourselves be upset by small things we should despise and forget</li><li class=\"d0\">Remember: <b>life is too short to be little</b></li></ul>","img":["ch-07-don-t-let-the-beetles-get-you-down-11.jpg"]}]},{"n":8,"slug":"ch-08-a-law-that-will-outlaw-many-of-your-worries","label":"Chapter 8","title":"A Law That Will Outlaw Many of Your Worries","audio":"ch-08-a-law-that-will-outlaw-many-of-your-worries.mp3","dur":845,"imgs":[],"secs":[{"t":0,"lv":2,"h":"Chapter 8: A Law That Will Outlaw Many of Your Worries","b":"","img":[]},{"t":0,"lv":3,"h":"Dale Carnegie","b":"","img":[]},{"t":0,"lv":2,"h":"Childhood on the Missouri farm","b":"<ul><li class=\"d0\">Pitting <b>cherries</b> with his mother, began to <b>cry</b></li><li class=\"d0\">Blubbered: afraid of being <b>buried alive</b></li><li class=\"d0\">Thunderstorms \u2192 feared killed by <b>lightning</b></li><li class=\"d0\">Hard times \u2192 feared not enough to <b>eat</b></li><li class=\"d0\">Feared going to <b>hell</b></li><li class=\"d0\">Older boy <b>Sam White</b> threatened to cut off his big <b>ears</b></li><li class=\"d0\">Feared girls would <b>laugh</b> if he tipped his hat to them</li><li class=\"d0\">Feared no girl would ever <b>marry</b> him</li><li class=\"d0\">Agonized for hours behind the plow: what would he say to his wife riding home in a <b>surrey with a fringe on top</b></li></ul>","img":[]},{"t":102,"lv":3,"h":"The discovery, years later","b":"<ul><li class=\"d0\"><b>99%</b> of the things he worried about <b>never happened</b></li><li class=\"d0\">Lightning odds, per the <b>National Safety Council</b>: <b>1 in 350,000</b> in any one year</li><li class=\"d0\">Buried alive: probably not even <b>1 in 10 million</b></li><li class=\"d0\"><b>1 in 8</b> people dies of <b>cancer</b> \u2014 that was the real thing worth worrying about</li><li class=\"d0\">Adult worries &quot;almost as absurd&quot; as a boy&#x27;s</li><li class=\"d0\">Checking the <b>law of averages</b> could wipe out <b>9/10</b> of our worries right now</li></ul>","img":[]},{"t":160,"lv":2,"h":"Lloyd&#x27;s of London","b":"<ul><li class=\"d0\">The most famous insurance company on earth</li><li class=\"d0\">Makes millions off people worrying about things that <b>rarely happen</b></li><li class=\"d0\">Calls it insurance \u2014 really it&#x27;s <b>betting</b>, based on the law of averages</li><li class=\"d0\">Going strong over <b>200 years</b>; Carnegie: still strong 50 centuries from now</li><li class=\"d0\">Insures &quot;<b>shoes and ships and sealing wax</b>&quot; against disasters that don&#x27;t happen nearly as often as feared</li></ul>","img":[]},{"t":213,"lv":2,"h":"The Gettysburg comparison","b":"<ul><li class=\"d0\">Facing 5 years of a battle as bloody as <b>Gettysburg</b> \u2192 would take out all the life insurance he could, draw up his <b>will</b></li><li class=\"d0\">Fact: living from age <b>50 to 55</b> in peacetime is, by the law of averages, just as fatal per thousand</li><li class=\"d0\">Same death rate as among the <b>163,000 soldiers</b> who fought at Gettysburg</li></ul>","img":[]},{"t":265,"lv":2,"h":"Mrs. Herbert H. Salinger of San Francisco","b":"<ul><li class=\"d0\">Met at <b>James Simpson&#x27;s Numteega Lodge</b>, Bow Lake, Canadian Rockies</li><li class=\"d0\">Looked <b>poised</b>, <b>serene</b> \u2014 but:</li><li class=\"d0\">&quot;My life was almost <b>ruined</b>&quot; by worry \u2014 <b>11 years</b> of self-made hell</li><li class=\"d0\">Irritable, hot-tempered, lived under terrific tension</li><li class=\"d0\">Weekly bus, <b>San Mateo</b> to San Francisco, to shop</li><li class=\"d0\">Mid-shopping panic: iron left on? house on fire? maid run off? children hit by a <b>car</b> on their bikes?</li><li class=\"d0\">Would rush home in a cold sweat to check</li><li class=\"d0\">First <b>marriage ended in disaster</b></li></ul>","img":[]},{"t":428,"lv":3,"h":"Second husband&#x27;s method","b":"<ul><li class=\"d0\">A <b>lawyer</b> \u2014 quiet, analytical, never worries</li><li class=\"d0\">His line: &quot;Relax. Let&#x27;s think this thing out... let&#x27;s examine the <b>law of averages</b>&quot;</li><li class=\"d0\">Example \u2014 Albuquerque to Carlsbad Caverns, dirt road, rainstorm, car sliding: &quot;by the law of averages, we won&#x27;t be hurt&quot;</li><li class=\"d0\">Example \u2014 Token Valley, Canadian Rockies, camped <b>7,000 ft</b> up, storm tearing at the tent: &quot;<b>Brewster&#x27;s Guide</b> \u2014 pitching tents in these mountains <b>60 years</b>... it won&#x27;t blow away tonight&quot;</li><li class=\"d0\">Example \u2014 infantile paralysis epidemic across California: worst-ever count <b>1,835</b> children stricken statewide; usual number <b>200\u2013300</b>; odds for any one child remote</li></ul>","img":[]},{"t":484,"lv":3,"h":"Her verdict","b":"<ul><li class=\"d0\">&quot;By the law of averages, it won&#x27;t happen&quot; \u2014 destroyed <b>90%</b> of her worries</li><li class=\"d0\">Made the past <b>20 years</b> &quot;beautiful and peaceful beyond my highest expectations&quot;</li><li class=\"d0\">Worry comes from <b>imagination</b>, not reality</li></ul>","img":[]},{"t":484,"lv":2,"h":"Jim Grant \u2014 James A. Grant Distributing Co., New York City","b":"<ul><li class=\"d0\">Ordered <b>10 to 15 carloads</b> of Florida oranges and grapefruit at a time</li><li class=\"d0\">Tortured himself: train wreck? fruit strewn everywhere? bridge collapse?</li><li class=\"d0\">Fruit was insured, but feared losing his <b>market</b> if late</li><li class=\"d0\">Worried himself toward <b>stomach ulcers</b>, went to a doctor</li><li class=\"d0\">Doctor: nothing wrong \u2014 just <b>jumpy nerves</b></li></ul>","img":[]},{"t":592,"lv":3,"h":"His arithmetic","b":"<ul><li class=\"num\"><span>1</span>Fruit cars handled over the years: about <b>25,000</b></li><li class=\"num\"><span>2</span>Cars ever wrecked: about <b>5</b></li><li class=\"num\"><span>3</span>Ratio: <b>5,000 to 1</b> against any car of his being wrecked</li><li class=\"num\"><span>4</span>Cars ever lost to a bridge collapse: <b>none</b></li><li class=\"d0\">Let the law of averages &quot;do the worrying for me&quot; \u2014 ulcer trouble gone since</li></ul>","img":[]},{"t":592,"lv":2,"h":"Al Smith, Governor of New York","b":"<ul><li class=\"d0\">Answered political attacks by repeating: &quot;<b>Let&#x27;s examine the record</b>&quot;</li><li class=\"d0\">Then gave the facts</li><li class=\"d0\">Carnegie&#x27;s tip: do the same with our own worries</li></ul>","img":[]},{"t":642,"lv":2,"h":"Frederick J. Maulstead \u2014 Rule 3 in action","b":"<ul><li class=\"d0\">Told to one of Carnegie&#x27;s New York classes</li><li class=\"d0\">Early <b>June 1944</b>, <b>Omaha Beach</b>, <b>999th Signal Service Company</b>, just dug in at Normandy</li><li class=\"d0\">Slit trench, a rectangular hole \u2014 &quot;looks just like a grave&quot;</li><li class=\"d0\">German bombers at <b>11pm</b>, bombs falling \u2014 scared stiff</li><li class=\"d0\">First <b>2\u20133 nights</b>: no sleep at all</li><li class=\"d0\"><b>4th\u20135th night</b>: nearly a nervous wreck</li></ul>","img":[]},{"t":696,"lv":3,"h":"Turning it around","b":"<ul><li class=\"d0\">Reminder: <b>5 nights</b> passed, still alive \u2014 so was every man in the outfit</li><li class=\"d0\">Only <b>2</b> injured \u2014 not by German bombs, by falling <b>flak</b> from their own anti-aircraft guns</li><li class=\"d0\">Built a thick <b>wooden roof</b> over the trench</li><li class=\"d0\">Only a <b>direct hit</b> could kill him in that deep, narrow trench</li><li class=\"d0\">Chance of a direct hit: not even <b>1 in 10,000</b></li><li class=\"d0\">Calmed down, slept \u2014 even through the raids</li></ul>","img":[]},{"t":757,"lv":2,"h":"US Navy \u2014 tanker morale","b":"<ul><li class=\"d0\">Sailors on <b>high-octane tankers</b> believed one torpedo hit meant instant destruction for everyone</li><li class=\"d0\">Navy issued the real figures:</li><li class=\"num\"><span>1</span>Of <b>100 tankers</b> hit by torpedoes, <b>60 stayed afloat</b></li><li class=\"num\"><span>2</span>Of the <b>40</b> that sank, only <b>5</b> sank in under <b>10 minutes</b></li><li class=\"d0\">Told by <b>Clyde W. Moss</b> of <b>St. Paul, Minnesota</b>, an ex-sailor</li><li class=\"d0\">&quot;This knowledge of the law of averages wiped out my jitters&quot; \u2014 whole crew felt better</li></ul>","img":[]},{"t":808,"lv":2,"h":"Rule 3","b":"<ul><li class=\"num\"><span>1</span><b>Let&#x27;s examine the record</b></li><li class=\"num\"><span>2</span>Ask: what are the chances, by the <b>law of averages</b>, that this thing I am worrying about will ever occur?</li></ul>","img":[]}]},{"n":9,"slug":"ch-09-cooperate-with-the-inevitable","label":"Chapter 9","title":"Cooperate With the Inevitable","audio":"ch-09-cooperate-with-the-inevitable.mp3","dur":1257,"imgs":[],"secs":[{"t":1,"lv":2,"h":"Chapter 9: Cooperate With the Inevitable","b":"","img":[]},{"t":1,"lv":3,"h":"Notes","b":"","img":[]},{"t":1,"lv":2,"h":"Opening stories - accepting fast","b":"<ul><li class=\"d0\">Boy in attic, abandoned log house, <b>northwest Missouri</b></li><li class=\"d1\">Ring on left forefinger caught a nail head, jumped, finger torn off</li><li class=\"d1\">Screamed, sure he&#x27;d <b>die</b></li><li class=\"d1\">After it healed - never worried about it again</li><li class=\"d1\">Now often <b>three fingers and thumb</b> on left hand, forgets for a month at a time</li><li class=\"d0\">Freight elevator operator, downtown <b>New York</b> office building</li><li class=\"d1\">Left hand cut off at the <b>wrist</b></li><li class=\"d1\">&quot;Oh, no. I hardly ever think about it. I&#x27;m not married.&quot;</li><li class=\"d1\">Only time he thinks of it: threading a needle</li><li class=\"d0\">Inscription on ruins of a <b>15th century cathedral</b>, Amsterdam, Holland</li><li class=\"d1\">Flemish: &quot;<b>It is so. It cannot be otherwise.</b>&quot;</li><li class=\"d1\">Unpleasant situations ahead - accept and adjust, or rebel into nervous breakdown</li></ul>","img":[]},{"t":111,"lv":2,"h":"Philosophers and a wartime letter","b":"<ul><li class=\"d0\"><b>William James</b>: &quot;<b>Be willing to have it so</b>&quot; - acceptance is the first step to overcoming any misfortune</li><li class=\"d0\"><b>Elizabeth Conley</b>, Portland, Oregon</li><li class=\"d1\">Letter written the day America celebrated victory in <b>North Africa</b></li><li class=\"d1\">Telegram from War Department: nephew missing in action</li><li class=\"d1\">Second telegram: <b>dead</b></li><li class=\"d1\">Prostrate with grief, neglected work and friends, clearing her desk to quit</li><li class=\"d1\">Found an old letter from the nephew (written when her own mother died)</li><li class=\"d1\">&quot;I know you&#x27;ll carry on... you taught me to smile and take whatever comes like a man&quot;</li><li class=\"d1\">Went back to work, wrote letters to soldiers, joined an <b>adult education class</b> at night</li><li class=\"d1\">&quot;I have made peace with life. I have accepted my fate.&quot;</li><li class=\"d0\"><b>George V</b> - framed words on his library wall, <b>Buckingham Palace</b>: &quot;Teach me neither to cry for the moon nor over spilt milk&quot;</li><li class=\"d0\"><b>Schopenhauer</b>: &quot;A good supply of resignation is of the first importance in providing for the journey of life&quot;</li><li class=\"d0\">Jesus: kingdom of heaven is within you - so is the kingdom of hell</li><li class=\"d0\">We are <b>stronger than we think</b></li></ul>","img":[]},{"t":377,"lv":2,"h":"Tarkington, Fuller, Carnegie&#x27;s own failure, the cattle","b":"<ul><li class=\"d0\"><b>Booth Tarkington</b>: could take anything except <b>blindness</b> - &quot;I could never endure that&quot;</li><li class=\"d1\">In his <b>60s</b> - carpet colors blurred, went to a specialist</li><li class=\"d1\">Losing his sight, one eye nearly blind, then the other</li><li class=\"d1\">Felt quite gay, used humor - floating specks: &quot;hello, there&#x27;s Grandfather again&quot;</li><li class=\"d1\">Total darkness closed in</li><li class=\"d1\">&quot;I found I could take the loss of my eyesight... it is in the mind we see and in the mind we live&quot;</li><li class=\"d1\">More than <b>12 operations within one year</b>, local anesthetic</li><li class=\"d1\">Refused a private room, chose a ward with others - tried to cheer them up</li><li class=\"d1\">&quot;How wonderful that science now has the skill to operate on anything so delicate as the human eye&quot;</li><li class=\"d1\">Would not exchange the experience for a happier one</li><li class=\"d1\">John Milton: not miserable to be blind - only miserable not to be able to endure blindness</li><li class=\"d0\"><b>Margaret Fuller</b>: &quot;I accept the universe&quot;</li><li class=\"d1\"><b>Thomas Carlyle</b> snorted: &quot;by gad, she&#x27;d better&quot;</li><li class=\"d0\">Carnegie&#x27;s own confession</li><li class=\"d1\">Once refused to accept an inevitable situation, railed and rebelled</li><li class=\"d1\">Nights of <b>insomnia hell</b></li><li class=\"d1\">A full <b>year</b> of self-torture before finally accepting</li><li class=\"d1\">Should have remembered <b>Walt Whitman</b>: confront night storms, hunger, ridicule, accident, rebuffs, as the trees and animals do</li><li class=\"d0\">Carnegie spent <b>12 years</b> working with cattle</li><li class=\"d1\">Never saw a Jersey cow run a temperature over a burning pasture, sleet and cold, or her boyfriend&#x27;s attention to another heifer</li><li class=\"d1\">Not advocating <b>fatalism</b> - fight while there&#x27;s a chance to save a situation</li><li class=\"d0\"><b>Dean Hawks</b> of Columbia University - his Mother Goose rhyme:</li><li class=\"num\"><span>1</span>For every ailment under the sun, there is a remedy or there is none</li><li class=\"num\"><span>2</span>If there be one, try to find it</li><li class=\"num\"><span>3</span>If there be none, never mind it</li></ul>","img":[]},{"t":754,"lv":2,"h":"Business leaders, Sarah Bernhardt, trees and tires","b":"<ul><li class=\"d0\"><b>J.C. Penney</b>, founder of the Penney stores: wouldn&#x27;t worry losing every dollar - leaves results &quot;in the laps of the gods&quot;</li><li class=\"d0\"><b>Henry Ford</b>: &quot;When I can&#x27;t handle events, I let them handle themselves&quot;</li><li class=\"d0\"><b>K.T. Keller</b>, president of <b>Chrysler Corporation</b>: &quot;If I can do anything about it, I do it. If I can&#x27;t, I just forget it.&quot;</li><li class=\"d0\"><b>Epictetus</b>, Rome, <b>19 centuries ago</b>: only one way to happiness - stop worrying about things beyond the power of our will</li><li class=\"d0\"><b>Sarah Bernhardt</b>, &quot;the divine Sarah&quot; - reigning queen of theatre, <b>four continents</b>, half a century</li><li class=\"d1\">Age <b>71</b>, broke, had lost all her money</li><li class=\"d1\">Physician <b>Professor Pozzi</b> of Paris: leg must be amputated</li><li class=\"d1\">Fell on deck in a storm crossing the Atlantic, phlebitis, leg shrank</li><li class=\"d1\">&quot;If it has to be. It was fate.&quot;</li><li class=\"d1\">Son stood weeping - she waved: &quot;Don&#x27;t go away. I&#x27;ll be right back.&quot;</li><li class=\"d1\">Recited a scene from one of her plays en route to the operating room - to cheer up the doctors and nurses</li><li class=\"d1\">Toured the world another <b>seven years</b> after the amputation</li><li class=\"d0\"><b>Elsie McCormick</b>, Reader&#x27;s Digest: stop fighting the inevitable and we release energy to create a richer life</li><li class=\"d0\">Carnegie&#x27;s Missouri farm - planted a <b>score of trees</b></li><li class=\"d1\">Sleet storm encrusted every twig with ice</li><li class=\"d1\">Trees resisted, broke, split - had to be destroyed</li><li class=\"d1\">Canada&#x27;s evergreen forests - hundreds of miles traveled, never saw a spruce or pine broken by sleet</li><li class=\"d1\">They know how to <b>bend</b></li><li class=\"d0\">Jiu-jitsu masters: &quot;<b>bend like the willow, don&#x27;t resist like the oak</b>&quot;</li><li class=\"d0\">Tires: built to resist the road&#x27;s shocks - cut to ribbons</li><li class=\"d1\">Built to <b>absorb</b> the shocks - could take it</li><li class=\"d1\">Resist life&#x27;s jolts instead -&gt; worried, tense, strained, neurotic</li><li class=\"d1\">Reject reality entirely -&gt; insane</li></ul>","img":[]},{"t":1022,"lv":2,"h":"Cassilis, Socrates, the prayer","b":"<ul><li class=\"d0\"><b>William H. Cassilis</b>, Glendale, New York - Coast Guard talk</li><li class=\"d1\">Cracker salesman made supervisor of <b>explosives</b></li><li class=\"d1\">Only <b>two days</b> of instruction</li><li class=\"d1\">First assignment: dark, cold, foggy day, <b>Caven Point pier, Bayonne, New Jersey</b></li><li class=\"d1\">Hold No. <b>5</b>, with <b>five longshoremen</b> who knew nothing about explosives</li><li class=\"d1\">Blockbusters - each <b>one ton of TNT</b> - lowered on <b>two cable slings</b></li><li class=\"d1\">Trembled, mouth dry, knees sagging, heart pounding - couldn&#x27;t run, that meant desertion</li><li class=\"d1\">Talked himself through it: &quot;so you&#x27;re blown up, so what... much better than dying by cancer&quot;</li><li class=\"d1\">Overcame his fear by accepting the inevitable</li><li class=\"d1\">Now, whenever tempted to worry: &quot;forget it&quot;</li><li class=\"d0\"><b>Socrates</b> - most famous death scene in history, from <b>Plato</b></li><li class=\"d1\">Men of Athens trumped up charges, condemned him to death</li><li class=\"d1\">Jailer with the poison cup: &quot;<b>Try to bear lightly what needs must be</b>&quot;</li><li class=\"d1\">Spoken <b>399 years before Christ</b></li><li class=\"d0\">Best single piece of worry advice Carnegie found, in <b>27 words</b> - <b>Dr. Reinhold Niebuhr&#x27;s</b> prayer, to paste on the bathroom mirror:</li><li class=\"d1\">&quot;God grant me the serenity to accept the things I cannot change, the courage to change the things I can, and the wisdom to know the difference&quot;</li></ul>","img":[]},{"t":1231,"lv":2,"h":"Rule 4","b":"<ul><li class=\"d0\"><b>Cooperate with the inevitable</b></li></ul>","img":[]}]},{"n":10,"slug":"ch-10-put-a-stop-loss-order-on-your-worries","label":"Chapter 10","title":"Put a \"Stop-Loss\" Order on Your Worries","audio":"ch-10-put-a-stop-loss-order-on-your-worries.mp3","dur":899,"imgs":[],"secs":[{"t":10,"lv":2,"h":"Chapter 10: Put a &quot;Stop-Loss&quot; Order on Your Worries","b":"","img":[]},{"t":10,"lv":3,"h":"The Wall Street story","b":"<ul><li class=\"d0\"><b>Charles Roberts</b>, investment counselor \u2014 told Carnegie this story</li><li class=\"d0\">Came to New York from <b>Texas</b> with <b>$20,000</b> \u2014 friends&#x27; money, to invest</li><li class=\"d0\">Thought he knew the market \u2014 <b>lost every cent</b></li><li class=\"d1\">Made profits on some deals, but ended up losing it all</li><li class=\"d0\">Worse than the money: guilt over losing <b>friends&#x27;</b> money</li><li class=\"d1\">Dreaded facing them again</li><li class=\"d1\">They were good sports about it \u2014 &quot;incurable optimists&quot;</li><li class=\"d0\">Realized: he&#x27;d been trading <b>by ear</b> \u2014 luck and other people&#x27;s opinions</li></ul>","img":[]},{"t":119,"lv":3,"h":"Learning the rule","b":"<ul><li class=\"d0\">Sought out <b>Burton S. Cassells</b> \u2014 a speculator successful year after year</li><li class=\"d0\">Cassells&#x27; principle: a <b>stop loss order</b> on every commitment</li><li class=\"d1\">Buy a stock at, say, <b>$50</b> a share</li><li class=\"d1\">Place a stop loss order at <b>45</b></li><li class=\"d1\">If it drops <b>5 points</b>, it sells automatically \u2014 loss capped</li><li class=\"d1\">Profits, intelligently made, run <b>10, 25, even 50 points</b></li><li class=\"d1\">So: you can be <b>wrong more than half the time</b> and still make money</li><li class=\"d0\">Roberts adopted it at once \u2014 saved clients &quot;many thousands of dollars&quot;</li></ul>","img":[]},{"t":171,"lv":3,"h":"Beyond the market","b":"<ul><li class=\"d0\">Realized the principle works on <b>any annoyance or resentment</b>, not just stocks</li><li class=\"d0\">Example: a friend, <b>Bill</b>, always late to lunch</li><li class=\"d1\">Used to wait half the lunch hour for him</li><li class=\"d1\">Told him: stop loss on waiting = exactly <b>10 minutes</b></li><li class=\"d1\">Past that, the lunch is &quot;sold down the river&quot; \u2014 Roberts is gone</li><li class=\"d0\">Wishes he&#x27;d applied it sooner to: <b>impatience</b>, <b>temper</b>, need for <b>self-justification</b>, <b>regrets</b></li></ul>","img":[]},{"t":286,"lv":3,"h":"Carnegie&#x27;s own crisis","b":"<ul><li class=\"d0\">The question he wishes he&#x27;d asked himself sooner: this is worth just so much fussing about, <b>and no more</b></li><li class=\"d0\">One time he <i>did</i> have the sense \u2014 a real crisis</li><li class=\"d1\">Early <b>30s</b> \u2014 decided to write novels</li><li class=\"d1\">Wanted to be a second <b>Frank Norris</b>, <b>Jack London</b>, or <b>Thomas Hardy</b></li><li class=\"d1\">Spent <b>two years in Europe</b>, living cheap on dollars, post-WWI inflation</li><li class=\"d1\">Wrote his &quot;magnum opus,&quot; titled <b><i>The Blizzard</b></i></li><li class=\"d1\">Reception &quot;as cold as any blizzard ... across the plains of the Dakotas&quot;</li><li class=\"d1\">His <b>literary agent</b>: worthless, no gift for fiction</li><li class=\"d1\">Left the office &quot;in a daze&quot; \u2014 <b>stunned</b>, <b>stupefied</b></li><li class=\"d1\">Weeks passed before he came out of it</li><li class=\"d1\">Without knowing the phrase yet, he put a stop loss on it:</li><li class=\"d1\">Wrote off the two years as <b>&quot;a noble experiment&quot;</b></li><li class=\"d1\">Went back to teaching adult education, writing biographies and nonfiction</li><li class=\"d1\">Never regretted it \u2014 &quot;I feel like dancing in the street for sheer joy&quot;</li></ul>","img":[]},{"t":336,"lv":3,"h":"Thoreau&#x27;s measure","b":"<ul><li class=\"d0\"><b>Henry Thoreau</b>, Walden Pond \u2014 a screech owl in the woods, goose quill, homemade ink</li><li class=\"d0\">Wrote: the cost of a thing is the amount of <b>life</b> exchanged for it, &quot;immediately or in the long run&quot;</li></ul>","img":[]},{"t":396,"lv":3,"h":"Gilbert and Sullivan \u2014 paid too much","b":"<ul><li class=\"d0\">Created beloved light operas: <b><i>Patience</b></i>, <b><i>Pinafore</b></i>, <b><i>The Mikado</b></i></li><li class=\"d0\">Could make gaiety in art, not in their own lives</li><li class=\"d0\">Feud over the price of a <b>carpet</b> \u2014 Sullivan ordered it, Gilbert saw the bill and &quot;hit the roof&quot;</li><li class=\"d0\">Battled it out in <b>court</b> \u2014 never spoke to each other again</li><li class=\"d0\">Mailed music and lyrics back and forth instead of speaking</li><li class=\"d0\">One shared curtain call: stood on <b>opposite sides of the stage</b>, bowed in <b>different directions</b></li></ul>","img":[]},{"t":451,"lv":3,"h":"Lincoln \u2014 the contrast","b":"<ul><li class=\"d0\">During the <b>Civil War</b>, friends denounced his bitter enemies</li><li class=\"d0\">Lincoln: &quot;you have more of a feeling of personal resentment than I have... I never thought it paid&quot;</li><li class=\"d0\">&quot;If any man ceases to attack me, I never remember the past against him&quot;</li></ul>","img":[]},{"t":502,"lv":3,"h":"Aunt Edith and Uncle Frank","b":"<ul><li class=\"d0\">Lived on a <b>mortgaged farm</b> \u2014 cockleburs, poor soil, ditches</li><li class=\"d0\">Aunt Edith bought curtains and small items on credit at <b>Dan Eversole&#x27;s</b> dry goods store, <b>Maryville, Missouri</b></li><li class=\"d0\">Uncle Frank secretly told the store to cut off her credit</li><li class=\"d0\">She found out, hit the roof \u2014 still angry <b>almost 50 years</b> later</li><li class=\"d0\">Carnegie confronted her in her <b>late 70s</b>: her decades of complaining were worse than the original wrong</li><li class=\"d0\">She &quot;paid for them with her own peace of mind&quot;</li></ul>","img":[]},{"t":555,"lv":3,"h":"Franklin&#x27;s whistle","b":"<ul><li class=\"d0\">Age <b>seven</b> \u2014 fell in love with a whistle in a toy shop</li><li class=\"d0\">Piled his coppers on the counter, paid without asking the price</li><li class=\"d0\">Siblings mocked him for overpaying \u2014 he &quot;cried with vexation&quot;</li><li class=\"d0\">Remembered it <b>70 years</b> later, even as <b>ambassador to France</b></li><li class=\"d0\">Lesson: much of mankind&#x27;s misery comes from <b>false estimates of value</b> \u2014 &quot;giving too much for their whistles&quot;</li></ul>","img":[]},{"t":719,"lv":3,"h":"Tolstoy \u2014 the highest price","b":"<ul><li class=\"d0\">Author of <b><i>War and Peace</b></i> and <b><i>Anna Karenina</b></i></li><li class=\"d0\">Per Encyclopedia Britannica: most venerated man in the world for <b>20 years</b> (<b>1890\u20131910</b>)</li><li class=\"d0\">Married a woman he loved deeply \u2014 early years of &quot;heavenly ecstasy&quot;</li><li class=\"d0\">His wife grew jealous:</li><li class=\"d1\">Dressed as a peasant to spy on him</li><li class=\"d1\">Shot a hole in a photograph of their daughter</li><li class=\"d1\">Held an opium bottle to her lips, threatened suicide \u2014 children screamed in terror</li><li class=\"d0\">Tolstoy kept a private diary blaming her</li><li class=\"d0\">She tore out and burned pages, kept her own diary, wrote a novel \u2014 <b><i>Whose Fault?</b></i> \u2014 casting him as villain, herself as martyr</li><li class=\"d0\">Both driven by wanting posterity to exonerate them</li><li class=\"d0\">Result: <b>50 years</b> in what Tolstoy himself called a &quot;lunatic asylum&quot;</li></ul>","img":[]},{"t":824,"lv":3,"h":"Rule 5","b":"<ul><li class=\"d0\">Develop a <b>private gold standard</b> \u2014 what things are worth in terms of life</li><li class=\"d0\">Could <b>annihilate 50%</b> of all worries with a decent sense of values</li><li class=\"d0\">Three questions, before throwing good money after bad:</li><li class=\"num\"><span>1</span>How much does this thing I am worrying about really matter to me?</li><li class=\"num\"><span>2</span>At what point shall I set a stop loss order on this worry \u2014 and forget it?</li><li class=\"num\"><span>3</span>Exactly how much shall I pay for this whistle? Have I already paid more than it is worth?</li></ul>","img":[]}]},{"n":11,"slug":"ch-11-don-t-try-to-saw-sawdust","label":"Chapter 11","title":"Don't Try to Saw Sawdust","audio":"ch-11-don-t-try-to-saw-sawdust.mp3","dur":791,"imgs":[],"secs":[{"t":0,"lv":2,"h":"Dale Carnegie","b":"","img":[]},{"t":0,"lv":3,"h":"Chapter 11: Don&#x27;t Try to Saw Sawdust","b":"","img":[]},{"t":0,"lv":2,"h":"Opening image \u2014 dinosaur tracks","b":"<ul><li class=\"d0\">Tracks in <b>shale and stone</b>, in Carnegie&#x27;s own garden</li><li class=\"d1\">Bought from the <b>Peabody Museum</b>, Yale University</li><li class=\"d1\">Curator&#x27;s letter: made <b>180 million years</b> ago</li><li class=\"d0\">Even a &quot;Mongolian idiot&quot; wouldn&#x27;t try to change them</li><li class=\"d1\">Yet worry tries to change what happened <b>180 seconds</b> ago</li><li class=\"d1\">Can modify the <i>effects</i> \u2014 can&#x27;t change the event itself</li><li class=\"d0\">Only way to fix the past: <b>analyze</b>, <b>profit</b>, <b>forget</b></li><li class=\"d1\">Carnegie: have I always had the courage to do it? No.</li></ul>","img":[]},{"t":55,"lv":2,"h":"Carnegie&#x27;s own $300,000 mistake","b":"<ul><li class=\"d0\">Adult education venture, branches in many cities</li><li class=\"d1\">Spent <b>lavishly</b> on overhead and advertising</li><li class=\"d1\">Too busy teaching \u2014 no business manager watching expenses</li><li class=\"d0\">After about <b>a year</b>: huge intake, <b>zero net profit</b></li><li class=\"d0\">Should have done two things</li><li class=\"num\"><span>1</span>Written it off, like <b>George Washington Carver</b></li><li class=\"num\"><span>2</span><b>Analyzed</b> the mistake and learned from it</li><li class=\"d0\">Did <b>neither</b></li><li class=\"d1\">Months of worry \u2014 lost sleep, lost weight</li><li class=\"d1\">Repeated the <b>same mistake</b> again, smaller scale</li><li class=\"d0\">Admits: easier to teach the lesson than to live it himself</li></ul>","img":[]},{"t":111,"lv":3,"h":"George Washington Carver contrast","b":"<ul><li class=\"d0\">Lost <b>$40,000</b> \u2014 a lifetime&#x27;s savings \u2014 in a bank crash</li><li class=\"d0\">Asked if he knew he was bankrupt: &quot;<b>Yes, I heard</b>&quot; \u2014 went on teaching</li><li class=\"d0\">Never mentioned the loss again</li></ul>","img":[]},{"t":211,"lv":2,"h":"Dr. Paul Brandwine&#x27;s milk bottle lesson","b":"<ul><li class=\"d0\">Told to Carnegie by <b>Alan Saunders</b></li><li class=\"d1\">Studied under Dr. <b>Paul Brandwine</b>, hygiene class</li><li class=\"d1\"><b>George Washington High School</b>, New York</li><li class=\"d1\">Saunders as a teen: chronic worrier \u2014 fretted over exams, chewed his nails</li><li class=\"d0\">Class files into the science lab \u2014 milk bottle sits on the desk&#x27;s edge</li><li class=\"d1\">Brandwine <b>sweeps it into the sink</b> \u2014 crash</li><li class=\"d1\">&quot;<b>Don&#x27;t cry over spilt milk</b>&quot;</li><li class=\"d1\">Makes them all come look at the wreckage</li><li class=\"d0\">With care it could&#x27;ve been saved \u2014 now it&#x27;s gone</li><li class=\"d1\">Write it off, forget it, go on to the next thing</li><li class=\"d0\">Stuck with Saunders longer than <b>four years</b> of geometry and Latin</li></ul>","img":[]},{"t":317,"lv":2,"h":"Old proverbs still hold","b":"<ul><li class=\"d0\">&quot;Don&#x27;t cry over spilt milk&quot;</li><li class=\"d0\">&quot;<b>Don&#x27;t cross your bridges</b> till you come to them&quot;</li><li class=\"d0\">Hackneyed, but the <b>distilled wisdom</b> of the human race</li><li class=\"d0\">Book&#x27;s purpose: not new knowledge \u2014 <b>remind</b> you, and &quot;kick you in the shins&quot;</li></ul>","img":[]},{"t":382,"lv":2,"h":"Fred Fuller Shedd \u2014 sawing sawdust","b":"<ul><li class=\"d0\">Editor, the <b>Philadelphia Bulletin</b></li><li class=\"d0\">Addressing a college graduating class</li><li class=\"d1\">&quot;How many have ever <b>sawed wood</b>?&quot; \u2014 most hands up</li><li class=\"d1\">&quot;How many have ever sawed <b>sawdust</b>?&quot; \u2014 no hands</li><li class=\"d1\">&quot;Of course you can&#x27;t saw sawdust \u2014 <b>it&#x27;s already sawed</b>&quot;</li><li class=\"d0\">Same with the past: worrying over what&#x27;s done = <b>trying to saw sawdust</b></li></ul>","img":[]},{"t":432,"lv":2,"h":"Connie Mack \u2014 baseball","b":"<ul><li class=\"d0\"><b>81 years old</b> when Carnegie asked him</li><li class=\"d0\">Did he ever worry over lost games? &quot;Used to&quot; \u2014 got over the foolishness</li><li class=\"d1\">&quot;Didn&#x27;t get me anywhere at all&quot;</li><li class=\"d0\">Can&#x27;t <b>grind grain</b> with water already down the creek</li><li class=\"d0\">Can&#x27;t saw logs with water already gone \u2014 but <i>can</i> saw <b>wrinkles</b> into your face, <b>ulcers</b> into your stomach</li></ul>","img":[]},{"t":482,"lv":2,"h":"Jack Dempsey \u2014 the lost title","b":"<ul><li class=\"d0\">Thanksgiving dinner, turkey and cranberry sauce</li><li class=\"d0\">Lost the heavyweight title to <b>Gene Tunney</b></li><li class=\"d1\">End of the <b>10th round</b> \u2014 still on his feet, face puffed and cut, eyes nearly closed</li><li class=\"d1\">Referee raises Tunney&#x27;s hand</li><li class=\"d1\">Walked back through the rain, through the crowd</li><li class=\"d0\">Fought Tunney again a <b>year later</b> \u2014 no use, through forever</li><li class=\"d0\">Told himself: not living in the past, taking the blow on the chin</li><li class=\"d0\">Didn&#x27;t do it by repeating &quot;I won&#x27;t worry&quot; \u2014 did it by <b>getting busy</b></li><li class=\"d1\">Ran the <b>Jack Dempsey Restaurant</b>, Broadway</li><li class=\"d1\"><b>Great Northern Hotel</b>, 57th Street</li><li class=\"d1\">Promoted prize fights, gave boxing exhibitions</li><li class=\"d0\">&quot;Better time in the last <b>10 years</b>&quot; than when he was champion</li><li class=\"d0\">Echoes Shakespeare: wise men &quot;cheerily seek how to redress their harms&quot;</li></ul>","img":[]},{"t":597,"lv":2,"h":"Sing Sing \u2014 Warden Lewis E. Lawes","b":"<ul><li class=\"d0\">Carnegie&#x27;s visit: prisoners about as happy as people outside</li><li class=\"d0\">New arrivals: resentful, bitter</li><li class=\"d0\">After a few months, the more intelligent ones <b>write off</b> the misfortune, settle down</li><li class=\"d0\">One prisoner \u2014 a <b>gardener</b> \u2014 sang while tending the vegetables and flowers</li><li class=\"d0\">&quot;The moving finger writes... nor all your tears wash out a word of it&quot;</li></ul>","img":[]},{"t":650,"lv":2,"h":"Napoleon","b":"<ul><li class=\"d0\">Lost <b>one-third</b> of all his important battles</li><li class=\"d0\">&quot;Perhaps our batting average is no worse than Napoleon&#x27;s&quot;</li><li class=\"d0\"><b>All the king&#x27;s horses and all the king&#x27;s men</b> can&#x27;t put the past back together</li></ul>","img":[]},{"t":701,"lv":2,"h":"Rule 6 \u2014 and the Part Three recap","b":"<ul><li class=\"d0\"><b>Rule 6</b>: Let the past bury its dead. <b>Don&#x27;t try to saw sawdust.</b></li><li class=\"d0\">Part Three in a nutshell \u2014 <i>How to Break the Worry Habit Before It Breaks You</i></li><li class=\"num\"><span>1</span>Crowd worry out by <b>keeping busy</b></li><li class=\"num\"><span>2</span>Don&#x27;t fuss about <b>trifles</b> \u2014 the &quot;termites of life&quot;</li><li class=\"num\"><span>3</span>Use the <b>law of averages</b> to outlaw your worries</li><li class=\"num\"><span>4</span><b>Cooperate with the inevitable</b></li><li class=\"num\"><span>5</span>Put a <b>stop-loss order</b> on your worries</li><li class=\"num\"><span>6</span><b>Let the past bury its dead</b></li><li class=\"d0\">Next: Part 4 \u2014 <b>7 Ways</b> to cultivate a mental attitude that brings peace and happiness</li></ul>","img":[]}]},{"n":12,"slug":"ch-12-eight-words-that-can-transform-your-life","label":"Chapter 12","title":"Eight Words That Can Transform Your Life","audio":"ch-12-eight-words-that-can-transform-your-life.mp3","dur":1834,"imgs":[],"secs":[{"t":0,"lv":2,"h":"Chapter 12: Eight Words That Can Transform Your Life","b":"","img":[]},{"t":0,"lv":2,"h":"The Question","b":"<ul><li class=\"d0\">Radio program: biggest lesson ever learned</li><li class=\"d0\">Answer: <b>importance of what we think</b></li><li class=\"d0\">&quot;If I knew what you think, I would know what you are&quot;</li><li class=\"d0\">Mental attitude = the <b>X factor</b> in our fate</li><li class=\"d0\">Emerson: &quot;a man is what he thinks about all day long&quot;</li><li class=\"d0\">The one real problem: choosing the <b>right thoughts</b></li></ul>","img":[]},{"t":59,"lv":2,"h":"Marcus Aurelius&#x27; Eight Words","b":"<ul><li class=\"d0\">Roman Emperor, philosopher</li><li class=\"d0\">&quot;<b>Our life is what our thoughts make it</b>&quot;</li><li class=\"d1\">happy thoughts \u2192 happy</li><li class=\"d1\">miserable thoughts \u2192 miserable</li><li class=\"d1\">fear thoughts \u2192 fearful</li><li class=\"d1\">sickly thoughts \u2192 probably ill</li><li class=\"d1\">failure thoughts \u2192 fail</li><li class=\"d1\">self-pity \u2192 shunned</li><li class=\"d0\">Norman Vincent Peale: not &quot;what you think you are,&quot; but &quot;<b>what</b> you think, you are&quot;</li><li class=\"d0\">Not preaching Pollyanna \u2014 <b>positive</b> attitude, not negative</li><li class=\"d0\"><b>Concern vs. worry</b></li><li class=\"d1\">concern = see the problem, calmly act</li><li class=\"d1\">worry = <b>maddening, futile circles</b></li><li class=\"d1\">example: crossing traffic-jammed New York streets, concerned not worried</li></ul>","img":[]},{"t":166,"lv":2,"h":"Lowell Thomas \u2014 Concerned, Not Worried","b":"<ul><li class=\"d0\">Carnegie presented Thomas&#x27;s WWI films</li><li class=\"d0\">Subjects: <b>Allenby</b>&#x27;s Holy Land campaign, <b>T.E. Lawrence</b> and his Arabian army</li><li class=\"d0\">&quot;With Allenby in Palestine and Lawrence in Arabia&quot; \u2014 sensation in London</li><li class=\"d1\">opera season postponed <b>six weeks</b>, shown at Covent Garden</li><li class=\"d0\">Two years filming India, Afghanistan \u2014 then a run of bad luck</li><li class=\"d0\">Ended up <b>broke in London</b></li><li class=\"d1\">cheap meals at Lyons Corner House</li><li class=\"d1\">borrowed money from a Scotsman, <b>James McBay</b>, renowned artist</li><li class=\"d0\">Every morning: bought a <b>flower</b> for his buttonhole, walked Oxford Street head high</li><li class=\"d0\">To him, being licked was just &quot;part of the game&quot;</li></ul>","img":[]},{"t":276,"lv":2,"h":"Mental Attitude and Physical Strength \u2014 Hadfield&#x27;s Test","b":"<ul><li class=\"d0\"><b>J. A. Hadfield</b>, British psychiatrist, booklet <i>The Psychology of Power</i> (54 pages)</li><li class=\"d0\">Three men gripped a dynamometer under three conditions:</li><li class=\"num\"><span>1</span>Normal waking state \u2014 average <b>101 lbs</b></li><li class=\"num\"><span>2</span>Hypnotized, told they were weak \u2014 <b>29 lbs</b> (less than a third)</li><li class=\"d1\">the prize fighter: arm felt &quot;tiny, like a baby&#x27;s&quot;</li><li class=\"num\"><span>3</span>Hypnotized, told they were strong \u2014 <b>142 lbs</b></li><li class=\"d0\">Positive suggestion: strength up almost <b>50%</b></li></ul>","img":[]},{"t":440,"lv":2,"h":"Mary Baker Eddy","b":"<ul><li class=\"d0\">Frosty October night, just after the Civil War</li><li class=\"d0\">Homeless <b>Mrs. Glover</b> \u2014 scarcely 100 lbs, &quot;skin and bones&quot; \u2014 knocks at <b>Mother Webster</b>&#x27;s door, Amesbury, Massachusetts</li><li class=\"d0\">Taken in \u2014 until son-in-law <b>Bill Ellis</b> shoves her out into the rain: &quot;no vagabonds&quot;</li><li class=\"d0\">She becomes <b>Mary Baker Eddy</b>, founder of Christian Science</li><li class=\"d1\">first husband died shortly after marriage</li><li class=\"d1\">second husband deserted her, died in a poorhouse</li><li class=\"d1\">only son given up at <b>4</b>, not seen again for <b>31 years</b></li><li class=\"d0\">Turning point: slips on ice in Lynn, Massachusetts, spine injured, doctor says she&#x27;ll never walk</li><li class=\"d0\">Reads a Bible healing passage \u2014 rises, walks</li><li class=\"d0\">Calls it her &quot;falling apple&quot; \u2014 only major religion founded by a woman</li><li class=\"d0\">Carnegie: not a Christian Scientist, but convinced of thought&#x27;s power over worry, fear, illness</li></ul>","img":[]},{"t":654,"lv":2,"h":"The Student&#x27;s Nervous Breakdown","b":"<ul><li class=\"d0\">Worried about <b>everything</b> \u2014 too thin, losing his hair, money, marriage, fatherhood, the girl, stomach ulcers</li><li class=\"d0\">Tension like &quot;<b>a boiler without a safety valve</b>&quot;</li><li class=\"d0\">Breakdown: couldn&#x27;t talk to family, jumped at noises, cried without reason, thought of the river</li><li class=\"d0\">Sent to Florida \u2014 father&#x27;s letter sealed until arrival</li><li class=\"d0\">No hotel room (tourist season) \u2014 rented a room over a garage</li><li class=\"d0\">Letter: &quot;You are <b>1,500 miles</b> from home... you took with you the one thing that is the cause of all your trouble \u2014 yourself&quot;</li><li class=\"d0\">Furious \u2014 vowed never to go home</li><li class=\"d0\">That night, wanders into a Miami church: &quot;He who conquers his spirit is mightier than he who taketh a city&quot;</li><li class=\"d0\">Realizes only thing needing change: &quot;<b>the focus of the lens of the camera</b>&quot; \u2014 his own mind</li><li class=\"d0\">Packs, goes home next morning</li><li class=\"d1\"><b>1 week</b> later: back on the job</li><li class=\"d1\"><b>4 months</b> later: marries the girl</li><li class=\"d1\">now: <b>5</b> children</li><li class=\"d1\">was night foreman of <b>18</b> people \u2192 now superintendent, over <b>450</b> people</li><li class=\"d0\">&quot;Get that camera back in focus&quot;</li></ul>","img":[]},{"t":973,"lv":2,"h":"Peace of Mind Is Not About Circumstance","b":"<ul><li class=\"d0\"><b>John Brown</b>, hanged for the raid on Harper&#x27;s Ferry \u2014 rides to the gallows sitting on his coffin, calm, admiring the Blue Ridge Mountains: &quot;what a beautiful country&quot;</li><li class=\"d0\"><b>Robert Falcon Scott</b>, first Englishmen to reach the South Pole</li><li class=\"d1\">return trip: food gone, fuel gone, blizzard <b>11 days and nights</b></li><li class=\"d1\">carried opium for an easy death \u2014 refused it</li><li class=\"d1\">died singing songs of cheer</li><li class=\"d1\">farewell letter found <b>8 months</b> later</li><li class=\"d0\"><b>Milton</b>, blind, 300 years ago: &quot;The mind is its own place... can make a heaven of hell, a hell of heaven&quot;</li><li class=\"d0\"><b>Napoleon</b> at St. Helena, with glory, power, riches: &quot;I have never known six happy days in my life&quot;</li><li class=\"d0\"><b>Helen Keller</b>, blind, deaf, dumb: &quot;I have found life so beautiful&quot;</li><li class=\"d0\">Emerson, <i>Self-Reliance</i>: no external event truly lifts you \u2014 &quot;<b>nothing can bring you peace but yourself</b>&quot;</li></ul>","img":[]},{"t":1137,"lv":2,"h":"Medical Backing","b":"<ul><li class=\"d0\"><b>Epictetus</b>, Stoic, 19 centuries ago: more concerned with wrong thoughts than tumors and abscesses</li><li class=\"d0\">Dr. <b>G. Canby Robinson</b>: <b>4 out of 5</b> patients at Johns Hopkins Hospital \u2014 conditions rooted in emotional strain</li><li class=\"d0\"><b>Montaigne</b>&#x27;s 17-word motto: &quot;A man is not hurt so much by what happens as by his <b>opinion</b> of what happens&quot;</li></ul>","img":[]},{"t":1245,"lv":2,"h":"Changing Attitude by Action \u2014 William James","b":"<ul><li class=\"d0\">Can attitude change &quot;by an effort of the will&quot;? <b>Yes</b></li><li class=\"d0\">James: action and feeling go together</li><li class=\"d1\">can&#x27;t control feeling directly \u2014 can control <b>action</b></li><li class=\"d1\">regulate action \u2192 indirectly regulate feeling</li><li class=\"d1\">&quot;sovereign voluntary path to cheerfulness&quot;: <b>act</b> cheerful</li><li class=\"d0\">Try it: big smile, shoulders back, deep breath, sing \u2014 or whistle \u2014 or hum</li><li class=\"d0\">Can&#x27;t stay blue while acting radiantly happy</li></ul>","img":[]},{"t":1300,"lv":2,"h":"Two Case Studies","b":"<ul><li class=\"d0\">Woman in California, a widow \u2014 refuses to act happy</li><li class=\"d1\">husband left insurance enough for life; married children give her a home</li><li class=\"d1\">complains sons-in-law are &quot;stingy and selfish,&quot; daughters give no presents \u2014 while she hoards her own money</li><li class=\"d1\">rarely smiles; could transform herself, doesn&#x27;t</li><li class=\"d0\"><b>H. J. Englert</b>, Tell City, Indiana</li><li class=\"d1\"><b>10 years</b> earlier: scarlet fever \u2192 nephritis</li><li class=\"d1\">blood pressure hits <b>214</b> \u2014 doctor calls it fatal, &quot;put your affairs in order&quot;</li><li class=\"d1\">pays up insurance, apologizes to his Maker, a week of gloomy self-pity \u2014 makes the whole family miserable</li><li class=\"d1\">then: &quot;you are acting like a fool&quot; \u2014 throws back his shoulders, forces a smile, acts normal</li><li class=\"d1\">begins to feel better; blood pressure comes down</li><li class=\"d1\">months later: alive, well, happy</li></ul>","img":[]},{"t":1512,"lv":2,"h":"As a Man Thinketh \u2014 James Allen","b":"<ul><li class=\"d0\">Book with &quot;lasting and profound effect&quot; on Carnegie</li><li class=\"d0\">&quot;A man will find that as he alters his thoughts... people will alter towards him&quot;</li><li class=\"d0\">&quot;Men do not attract that which they want, but that which <b>they are</b>&quot;</li><li class=\"d0\">&quot;All that a man achieves is the direct result of his own thought&quot;</li><li class=\"d0\">Genesis: dominion over the earth \u2014 Carnegie wants dominion over <b>himself</b>: thoughts, fears, mind, spirit</li></ul>","img":[]},{"t":1681,"lv":2,"h":"Just for Today \u2014 Sybil F. Partridge","b":"<ul><li class=\"d0\">Program Carnegie gave away &quot;hundreds of copies&quot; of</li><li class=\"d0\">Goal: la joie de vivre</li><li class=\"d0\">Ten points:</li><li class=\"num\"><span>1</span>I will be happy (Lincoln: as happy as we make up our minds to be)</li><li class=\"num\"><span>2</span>I will adjust myself to what is</li><li class=\"num\"><span>3</span>I will take care of my body</li><li class=\"num\"><span>4</span>I will strengthen my mind \u2014 read something requiring effort</li><li class=\"num\"><span>5</span>I will exercise my soul \u2014 a good turn unnoticed; two things I don&#x27;t want to do</li><li class=\"num\"><span>6</span>I will be agreeable \u2014 dress well, talk low, criticize nothing</li><li class=\"num\"><span>7</span>I will try to live through <b>this day only</b></li><li class=\"num\"><span>8</span>I will have a program \u2014 an hourly written plan</li><li class=\"num\"><span>9</span>I will have a quiet half hour alone</li><li class=\"num\"><span>10</span>I will be unafraid \u2014 unafraid even to be happy</li></ul>","img":[]},{"t":1789,"lv":2,"h":"Rule 1","b":"<ul><li class=\"p\"><b>&quot;Think and act cheerfully, and you will feel cheerful.&quot;</b></li></ul>","img":[]}]},{"n":13,"slug":"ch-13-the-high-cost-of-getting-even","label":"Chapter 13","title":"The High Cost of Getting Even","audio":"ch-13-the-high-cost-of-getting-even.mp3","dur":1111,"imgs":[],"secs":[{"t":1,"lv":2,"h":"Dale Carnegie","b":"","img":[]},{"t":1,"lv":3,"h":"Chapter 13: The High Cost of Getting Even","b":"","img":[]},{"t":54,"lv":2,"h":"Opening: Yellowstone","b":"<ul><li class=\"d0\"><b>Yellowstone Park</b>, bleachers, tourists watching a <b>grizzly bear</b> eat garbage dumped from a park hotel kitchen</li><li class=\"d0\">Forest ranger <b>Major Martindale</b>: grizzly can whip any animal in the West except the <b>buffalo</b> and the <b>Kodiak bear</b></li><li class=\"d0\">Only one animal the grizzly lets come eat beside him: a <b>skunk</b></li><li class=\"d1\">Could kill it with one swipe of his paw \u2014 doesn&#x27;t</li><li class=\"d1\">Learned from <b>experience</b> it doesn&#x27;t pay</li><li class=\"d0\">Carnegie: trapped four-legged skunks along <b>Missouri</b> hedgerows as a farm boy; met two-legged skunks on <b>New York</b> sidewalks</li><li class=\"d0\"><b>Hate gives our enemies power</b> over us \u2014 sleep, appetite, blood pressure, health, happiness</li><li class=\"d0\">Enemies would &quot;dance with joy&quot; to know how they worry us \u2014 the hate wounds us, not them</li></ul>","img":[]},{"t":109,"lv":2,"h":"The cost is physical","b":"<ul><li class=\"d0\"><b>Milwaukee police department bulletin</b>: &quot;cross them off your list, but don&#x27;t try to get even... you hurt yourself more than the other fellow&quot;</li><li class=\"d0\"><b>Life magazine</b>: chief trait of people with hypertension is <b>resentment</b></li><li class=\"d1\">chronic resentment \u2192 hypertension \u2192 heart trouble</li><li class=\"d0\">Jesus: &quot;love your enemies&quot; / &quot;forgive <b>70 times 7</b>&quot; \u2014 not just ethics, <b>20th-century medicine</b></li><li class=\"d0\">Friend&#x27;s serious <b>heart attack</b> \u2014 doctor&#x27;s order: never get angry, no matter what</li><li class=\"d0\"><b>William Falkaber</b>, age <b>68</b>, cafe owner in <b>Spokane, Washington</b></li><li class=\"d1\">Enraged when his cook drank coffee from a saucer</li><li class=\"d1\">Grabbed a revolver, chased him \u2014 dropped dead of heart failure, still gripping the gun</li><li class=\"d1\">Letter from <b>Jerry Sporthout</b>, then Spokane police chief</li><li class=\"d1\">Coroner ruled anger the cause of death</li></ul>","img":[]},{"t":219,"lv":2,"h":"The cost to looks and appetite","b":"<ul><li class=\"d0\">Hate <b>wrinkles and hardens</b> faces \u2014 no cosmetic surgery beats a heart full of forgiveness</li><li class=\"d0\">Bible: &quot;better a dinner of herbs where love is, than a stalled ox and hatred therewith&quot;</li><li class=\"d0\"><b>Shakespeare</b>: &quot;heat not a furnace for your foe, so hot that it do singe yourself&quot;</li></ul>","img":[]},{"t":375,"lv":2,"h":"The cost to business \u2014 George Rona","b":"<ul><li class=\"d0\">Letter from <b>George Rona of Uppsala, Sweden</b></li><li class=\"d1\">Vienna attorney, fled during the <b>war</b>, needed work, spoke several languages</li><li class=\"d1\">One firm&#x27;s reply: rude \u2014 said Rona &quot;can&#x27;t even write good Swedish,&quot; his letter &quot;full of mistakes&quot;</li><li class=\"d1\">Rona furious, drafted a scorching reply</li><li class=\"d1\">Paused: <i>how do I know this man isn&#x27;t right?</i> \u2014 Swedish isn&#x27;t his native tongue</li><li class=\"d1\"><b>Tore up</b> the angry letter, wrote a <b>thank-you</b> instead \u2014 apologized, thanked him for the push to improve</li><li class=\"d1\">Days later: invited to meet the man \u2014 <b>got the job</b></li><li class=\"d1\">&quot;A soft answer turneth away wrath&quot;</li></ul>","img":[]},{"t":476,"lv":2,"h":"Forgive and forget","b":"<ul><li class=\"d0\"><b>Confucius</b>: to be wronged or robbed is nothing \u2014 unless you keep remembering it</li><li class=\"d0\">Asked <b>General Eisenhower&#x27;s son John</b> if his father held resentments</li><li class=\"d1\">&quot;No \u2014 dad never wastes a minute thinking about people he doesn&#x27;t like&quot;</li><li class=\"d0\">&quot;A man is a fool who can&#x27;t be angry, but wise who won&#x27;t be&quot;</li><li class=\"d0\"><b>William J. Gaynor</b>, former mayor of <b>New York</b></li><li class=\"d1\">Denounced by the press, shot by a maniac, nearly killed</li><li class=\"d1\">From his hospital bed: &quot;every night I forgive everything and everybody&quot;</li><li class=\"d0\"><b>Schopenhauer</b>, author of <i>Studies in Pessimism</i> \u2014 called life a futile, painful adventure \u2014 yet: &quot;if possible, no animosity should be felt for anyone&quot;</li><li class=\"d0\"><b>Bernard Baruch</b> \u2014 trusted adviser to <b>six presidents</b>: <b>Wilson, Harding, Coolidge, Hoover, Roosevelt, Truman</b></li><li class=\"d1\">&quot;No man can humiliate me or disturb me. I won&#x27;t let him.&quot;</li></ul>","img":[]},{"t":587,"lv":2,"h":"Edith Cavell","b":"<ul><li class=\"d0\">Mountain in <b>Jasper National Park, Canada</b>, named in her honor</li><li class=\"d0\">British nurse, executed by a German firing squad, <b>October 12, 1915</b></li><li class=\"d0\">Her &quot;crime&quot;: hid, fed and nursed French and English soldiers in her Belgian home; helped them escape into Holland</li><li class=\"d0\">To the chaplain in her cell: &quot;I realize that patriotism is not enough. I must have no hatred or bitterness toward anyone.&quot;</li><li class=\"d0\">Body returned to England <b>four years later</b>; memorial service at <b>Westminster Abbey</b></li><li class=\"d0\">Statue opposite the <b>National Portrait Gallery</b>, London \u2014 her words carved in granite</li></ul>","img":[]},{"t":744,"lv":2,"h":"Absorbed in a bigger cause \u2014 Lawrence Jones","b":"<ul><li class=\"d0\"><b>1918</b>, pine woods of <b>Mississippi</b> \u2014 a lynching underway</li><li class=\"d0\"><b>Lawrence Jones</b>, Black teacher and preacher, founder of the <b>Piney Woods Country School</b></li><li class=\"d1\">Rumor: Germans inciting Black rebellion</li><li class=\"d1\">A mob heard him preach &quot;fight&quot; and &quot;armor&quot; and seized on the words</li><li class=\"d1\">Dragged him a mile up the road, rope around his neck, stood him on kindling, matches lit</li><li class=\"d1\">Someone shouted: let him speak first</li><li class=\"d0\">Jones spoke for his life and his cause</li><li class=\"d1\">Graduated <b>University of Iowa, 1907</b> \u2014 popular, gifted musically</li><li class=\"d1\">Turned down a business offer and a funded musical education</li><li class=\"d1\">Inspired by <b>Booker T. Washington</b> \u2014 pawned his watch for <b>$65</b>, started his school in the open woods, a stump for a desk, 25 miles south of <b>Jackson, Mississippi</b></li><li class=\"d1\">Told of white men who&#x27;d given land, lumber, pigs, cows, money</li><li class=\"d0\">An old <b>Confederate veteran</b>: &quot;I believe this boy is telling the truth... we ought to help him instead of hang him&quot;</li><li class=\"d1\">Passed his hat \u2014 raised <b>$52.40</b> from the very men who&#x27;d come to hang him</li></ul>","img":[]},{"t":912,"lv":2,"h":"Fate settles the account","b":"<ul><li class=\"d0\"><b>Epictetus</b>, 19 centuries ago: we reap what we sow; every man pays for his own misdeeds</li><li class=\"d1\">The man who remembers this is angry with no one, hates no one</li><li class=\"d0\"><b>Lincoln</b> \u2014 most denounced and hated president in American history, per <b>Herndon&#x27;s</b> biography</li><li class=\"d1\">Never judged men by like or dislike; gave the job to the fittest man even if an enemy \u2014 <b>McClellan, Seward, Stanton, Chase</b></li><li class=\"d1\">Believed all men shaped by conditions, circumstance, environment, heredity</li><li class=\"d0\"><b>Sioux prayer</b>: &quot;O Great Spirit, keep me from ever judging a man until I have walked in his moccasins for two weeks&quot;</li><li class=\"d0\">Pity enemies instead of condemning them \u2014 give understanding, sympathy, help, forgiveness, prayer</li></ul>","img":[]},{"t":1023,"lv":2,"h":"Carnegie&#x27;s father","b":"<ul><li class=\"d0\"><b>Missouri</b> farmhouse, nightly family Scripture reading, family prayer</li><li class=\"d0\">Repeated Jesus&#x27; words: &quot;Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you and persecute you&quot;</li><li class=\"d0\">It gave him an <b>inner peace</b> that captains and kings have often sought in vain</li></ul>","img":[]},{"t":1079,"lv":2,"h":"Rule 2","b":"<ul><li class=\"p\"><b>Never try to get even with our enemies \u2014 it hurts us far more than it hurts them.</b></li><li class=\"p\">Do as Eisenhower does: never waste a minute thinking about people we don&#x27;t like.</li></ul>","img":[]}]},{"n":14,"slug":"ch-14-if-you-do-this-you-will-never-worry-about-ingratitude","label":"Chapter 14","title":"If You Do This, You Will Never Worry About Ingratitude","audio":"ch-14-if-you-do-this-you-will-never-worry-about-ingratitude.mp3","dur":832,"imgs":[],"secs":[{"t":1,"lv":2,"h":"Dale Carnegie \u2014 Chapter 14: If You Do This, You Will Never Worry About Ingratitude","b":"","img":[]},{"t":1,"lv":2,"h":"The Texas Businessman","b":"<ul><li class=\"d0\">Businessman, <b>Texas</b>, burned up with indignation</li><li class=\"d0\">Told Carnegie within <b>15 minutes</b> of meeting him</li><li class=\"d0\">Incident <b>11 months</b> old \u2014 still stewing</li><li class=\"d0\">Gave <b>34 employees</b> <b>$10,000</b> in Christmas bonuses \u2014 about <b>$300 each</b></li><li class=\"d0\">No one thanked him</li><li class=\"d0\">&quot;I&#x27;m sorry I ever gave them a penny&quot;</li><li class=\"d0\">Confucius: an angry man is <b>full of poison</b></li><li class=\"d0\">Carnegie pitied him</li><li class=\"d1\">About <b>60</b> years old</li><li class=\"d1\">Actuarial rule: years left = two-thirds of (80 minus present age)</li><li class=\"d1\">So maybe <b>14\u201315 years</b> left to live</li><li class=\"d1\">Already wasted almost <b>one whole year</b> on bitterness</li></ul>","img":[]},{"t":104,"lv":3,"h":"What he never asked himself","b":"<ul><li class=\"d0\">Maybe he <b>underpaid / overworked</b> them</li><li class=\"d0\">Maybe they saw the bonus as <b>earned</b>, not a gift</li><li class=\"d0\">Maybe he was too <b>critical, unapproachable</b> to thank</li><li class=\"d0\">Maybe they figured it was just leftover <b>tax money</b></li><li class=\"d0\">Maybe the employees were simply selfish</li><li class=\"d0\">Samuel Johnson: <b>gratitude is a fruit of great cultivation</b> \u2014 not found among gross people</li><li class=\"d0\">The mistake: <b>expecting gratitude</b> \u2014 not knowing human nature</li></ul>","img":[]},{"t":154,"lv":2,"h":"Nobody Says Thanks, Even for the Biggest Favors","b":"<ul><li class=\"d0\"><b>Samuel Leibowitz</b>, famed criminal lawyer, later judge</li><li class=\"d1\">Saved <b>78 men</b> from the <b>electric chair</b></li><li class=\"d1\">How many thanked him? <b>None</b></li><li class=\"d0\"><b>Christ</b> healed <b>10 lepers</b> in one afternoon</li><li class=\"d1\">Only <b>1</b> came back to thank him</li><li class=\"d1\">&quot;Where are the other nine?&quot; \u2014 St. Luke</li><li class=\"d1\">The other nine vanished</li><li class=\"d0\">Why expect more thanks than Christ got?</li></ul>","img":[]},{"t":206,"lv":3,"h":"Money makes it worse","b":"<ul><li class=\"d0\"><b>Charles Schwab</b> saved a bank cashier who&#x27;d speculated with the bank&#x27;s funds</li><li class=\"d1\">Cashier grateful \u2014 briefly</li><li class=\"d1\">Then turned, <b>reviled and denounced</b> Schwab</li><li class=\"d0\"><b>Andrew Carnegie</b> gave a relative <b>$1 million</b></li><li class=\"d1\">Relative later <b>cursed him</b></li><li class=\"d1\">Why: Carnegie left <b>$365 million</b> to public charities, only &quot;one measly million&quot; to him</li></ul>","img":[]},{"t":206,"lv":3,"h":"Marcus Aurelius&#x27; answer","b":"<ul><li class=\"d0\">Diary: expects to meet people today who are <b>selfish, egotistical, ungrateful</b></li><li class=\"d0\">Won&#x27;t be surprised or disturbed \u2014 &quot;couldn&#x27;t imagine a world without such people&quot;</li><li class=\"d0\"><b>Don&#x27;t expect gratitude</b> \u2014 if it comes, a delightful surprise; if not, no sting</li></ul>","img":[]},{"t":321,"lv":2,"h":"The Lonely Woman in New York","b":"<ul><li class=\"d0\">Always complains she&#x27;s lonely \u2014 relatives avoid her</li><li class=\"d0\">Nursed her nieces through <b>measles, mumps, whooping cough</b></li><li class=\"d0\">Boarded them for years; sent one through <b>business school</b>; made a home for the other until she married</li><li class=\"d0\">Nieces visit <b>out of duty</b>, dread it \u2014 hours of half-veiled reproaches</li><li class=\"d0\">She develops a <b>nervous heart</b> \u2014 palpitations are real, but doctors say the cause is <b>emotional</b>, nothing they can do</li><li class=\"d0\">She calls it wanting <b>gratitude</b> \u2014 really wants <b>love</b></li><li class=\"d0\"><b>Only way to be loved: stop demanding it, pour out love without expecting return</b></li></ul>","img":[]},{"t":431,"lv":2,"h":"Carnegie&#x27;s Own Parents","b":"<ul><li class=\"d0\">Poor, always in debt</li><li class=\"d0\">Still sent money <b>every year</b> to the <b>Christian Home orphanage, Council Bluffs, Iowa</b></li><li class=\"d0\">Never visited it; rarely thanked, maybe by letter</li><li class=\"d0\">Repaid by <b>the joy of giving itself</b></li><li class=\"d0\">Carnegie sent them a Christmas check, urged them to spend it on themselves \u2014 they rarely did</li><li class=\"d0\">Father instead bought <b>coal and groceries</b> for a widow in town with many children, no money for food or fuel</li><li class=\"d0\">Aristotle: the <b>ideal man takes joy in doing favors for others</b></li></ul>","img":[]},{"t":484,"lv":2,"h":"Raising Grateful Children","b":"<ul><li class=\"d0\"><b>King Lear</b>: &quot;sharper than a serpent&#x27;s tooth... a thankless child&quot;</li><li class=\"d0\">Parents have complained of children&#x27;s ingratitude for <b>10,000 years</b></li><li class=\"d0\"><b>Ingratitude is natural, like weeds. Gratitude is like a rose</b> \u2014 fed, watered, cultivated, protected</li></ul>","img":[]},{"t":535,"lv":3,"h":"The Chicago stepfather","b":"<ul><li class=\"d0\">Worked a <b>box factory</b>, rarely more than <b>$40 a week</b></li><li class=\"d0\">Married a widow; paid to send her <b>two grown sons through college</b></li><li class=\"d0\">Did it for <b>4 years</b> \u2014 food, rent, fuel, clothes, plus loan payments</li><li class=\"d0\">No thanks \u2014 wife and sons took it for granted</li><li class=\"d0\">Wife never taught gratitude \u2014 called it &quot;the least he can do&quot;</li><li class=\"d0\">Result: one son tried to borrow from an employer, ended up in <b>jail</b></li></ul>","img":[]},{"t":641,"lv":3,"h":"Aunt Viola Alexander, Minneapolis","b":"<ul><li class=\"d0\">Carnegie&#x27;s mother&#x27;s sister</li><li class=\"d0\">Took in <b>her own mother</b> and <b>her husband&#x27;s mother</b> \u2014 cared for both by the fire</li><li class=\"d0\">Had <b>6 children</b> of her own; never thought it noble, just natural</li><li class=\"d0\">Widow <b>20-odd years</b> now; has <b>5 grown children</b>, <b>5 households</b>, all wanting her</li><li class=\"d0\">They adore her \u2014 not gratitude, <b>love</b> \u2014 raised in warmth, now give it back</li></ul>","img":[]},{"t":698,"lv":3,"h":"The dish cloths","b":"<ul><li class=\"d0\">Don&#x27;t say: &quot;cost her nothing, she just knit them&quot;</li><li class=\"d0\">Instead: &quot;look at the hours Cousin Sue spent \u2014 let&#x27;s write her a thank-you note right now&quot;</li><li class=\"d0\">Children absorb what we <b>model</b></li></ul>","img":[]},{"t":752,"lv":2,"h":"Rule 3","b":"<ul><li class=\"num\"><span>1</span><b>Expect ingratitude</b> \u2014 remember only 1 of 10 lepers thanked Jesus</li><li class=\"num\"><span>2</span><b>Give for the joy of giving</b>, not for gratitude</li><li class=\"num\"><span>3</span><b>Gratitude is a cultivated trait</b> \u2014 train children to be grateful</li></ul>","img":[]}]},{"n":15,"slug":"ch-15-would-you-take-a-million-dollars-for-what-you-have","label":"Chapter 15","title":"Would You Take a Million Dollars for What You Have?","audio":"ch-15-would-you-take-a-million-dollars-for-what-you-have.mp3","dur":854,"imgs":[],"secs":[{"t":52,"lv":2,"h":"Harold Abbott&#x27;s Story","b":"<ul><li class=\"d0\">Former <b>lecture manager</b>, Webb City, Missouri; story told driving to farm in <b>Belton, Missouri</b></li><li class=\"d0\"><b>Spring 1934</b>, <b>West Doherty Street</b> \u2014 sight banished worry in <b>10 seconds</b>; taught more than the previous <b>10 years</b></li><li class=\"d0\">Background: ran a <b>grocery store</b> 2 years, lost all savings, debts took <b>7 years</b> to repay, store closed the Saturday before</li><li class=\"d1\">Walking to <b>Merchants and Miners Bank</b> for a loan \u2014 &quot;walked like a <b>beaten man</b>&quot;</li><li class=\"d0\">The man with no legs: small wooden platform on <b>roller-skate wheels</b>, propelled by a block of wood in each hand</li><li class=\"d1\">Grand smile: &quot;<b>Morning, sir. It&#x27;s a fine morning, isn&#x27;t it?</b>&quot;</li><li class=\"d0\">The turn: &quot;I had two legs. I could walk.&quot; Ashamed of self-pity</li><li class=\"d1\">Asked the bank for <b>$200</b>, not the planned <b>$100</b></li><li class=\"d1\">Announced he was <b>going</b> to get a job, not trying to. Got the loan. Got the job.</li><li class=\"d0\">Words on his <b>bathroom mirror</b>, read every morning shaving</li><li class=\"d1\">&quot;I had the blues because I had no shoes, until upon the street I met a man who had no feet.&quot;</li></ul>","img":[]},{"t":156,"lv":2,"h":"Perspective From the Edge","b":"<ul><li class=\"d0\"><b>Eddie Rickenbacker</b> \u2014 <b>21 days</b> adrift on life rafts, Pacific, hopelessly lost</li><li class=\"d1\">Lesson: fresh water, food to eat \u2014 <b>never complain</b> about anything</li><li class=\"d0\"><i>Time</i> \u2014 sergeant wounded on <b>Guadalcanal</b>, shell fragment in throat, <b>7 blood transfusions</b></li><li class=\"d1\">&quot;Will I live?&quot; Yes. &quot;Will I talk again?&quot; Yes.</li><li class=\"d1\">&quot;<b>Then what in the hell am I worrying about?</b>&quot;</li></ul>","img":[]},{"t":208,"lv":2,"h":"The 90/10 Rule","b":"<ul><li class=\"d0\"><b>90%</b> of things in life are right, <b>10%</b> are wrong</li><li class=\"d0\">Happy = concentrate on the 90%. Bitter, ulcers = concentrate on the 10%.</li><li class=\"d0\">&quot;<b>Think and Thank</b>&quot; \u2014 inscribed in Cromwellian churches of England</li></ul>","img":[]},{"t":262,"lv":2,"h":"Even the Pessimist Agreed","b":"<ul><li class=\"d0\"><b>Jonathan Swift</b>, author of <i>Gulliver&#x27;s Travels</i> \u2014 &quot;most devastating pessimist in English literature&quot;</li><li class=\"d1\">Wore black, fasted on his birthdays, sorry he was born</li><li class=\"d1\">Yet named the best doctors: <b>Dr. Diet, Dr. Quiet, and Dr. Merryman</b></li></ul>","img":[]},{"t":312,"lv":2,"h":"Riches Beyond Counting","b":"<ul><li class=\"d0\">Sell both eyes for a <b>billion dollars</b>? Your legs, hands, hearing, family?</li><li class=\"d0\">Wouldn&#x27;t sell what you have for the gold of the <b>Rockefellers, Fords, and Morgans</b> combined \u2014 treasures exceeding <b>Ali Baba&#x27;s</b></li><li class=\"d0\"><b>Schopenhauer</b>: &quot;We seldom think of what we have, but always of what we lack&quot; \u2014 the greatest tragedy on earth</li></ul>","img":[]},{"t":366,"lv":2,"h":"John Palmer&#x27;s Story","b":"<ul><li class=\"d0\"><b>Paterson, New Jersey</b> \u2014 back from the army, started his own business; couldn&#x27;t get <b>parts and materials</b>, feared losing it</li><li class=\"d0\">Worry turned him into an &quot;<b>old grouch</b>&quot; \u2014 nearly wrecked his home</li><li class=\"d0\">A <b>young disabled veteran</b> on his staff: &quot;Johnny, you ought to be ashamed of yourself&quot;</li><li class=\"d1\">&quot;I&#x27;ve only got one arm and half of my face is shot away \u2014 and I&#x27;m not complaining&quot;</li><li class=\"d1\">Warned: keep growling, lose the business, the health, the home, the friends</li><li class=\"d0\">Stopped him &quot;dead in his tracks&quot; \u2014 resolved to change back</li></ul>","img":[]},{"t":524,"lv":2,"h":"Lucille Blake&#x27;s Story","b":"<ul><li class=\"d0\">Met at <b>Columbia University School of Journalism</b>; living in <b>Tucson, Arizona</b> \u2014 organ study, speech clinic, teaching at <b>Desert Willow Ranch</b></li><li class=\"d0\">Heart collapse \u2014 doctor ordered <b>a year in bed</b>, no promise of full recovery</li><li class=\"d0\">Neighbor <b>Mr. Rudolph</b>, an artist: &quot;more spiritual growth in these next few months than in all your previous life&quot;</li><li class=\"d0\">Radio: &quot;you can express only what is in your own consciousness&quot; \u2014 resolved to think only joy, happiness, health</li><li class=\"d0\">Counted blessings every morning: no pain, a young daughter, eyesight, hearing, music, books, food, friends</li><li class=\"d0\">So many visitors the doctor posted a sign: <b>one visitor at a time</b></li><li class=\"d0\">Now: full, active life \u2014 &quot;never really learned to live until I feared I was going to die&quot;</li></ul>","img":[]},{"t":575,"lv":2,"h":"Confirmed 200 Years Earlier","b":"<ul><li class=\"d0\"><b>Dr. Samuel Johnson</b>: best side of every event &quot;worth more than a <b>thousand pounds a year</b>&quot; \u2014 said after <b>20 years</b> of anxiety, rags and hunger</li><li class=\"d0\"><b>Logan Pearsall Smith</b>: first get what you want, then <b>enjoy</b> it \u2014 only the wisest achieve the second</li></ul>","img":[]},{"t":692,"lv":2,"h":"Borghild Dahl&#x27;s Story","b":"<ul><li class=\"d0\">Book: <i>I Wanted to See</i>. Blind, practically, for <b>half a century</b> \u2014 one eye, dense scars</li><li class=\"d0\">Refused pity \u2014 as a child, crawled to <b>memorize</b> hopscotch markings she couldn&#x27;t see</li><li class=\"d0\"><b>A.B., University of Minnesota</b>; <b>M.A., Columbia University</b></li><li class=\"d0\">Taught <b>Twin Valley, Minnesota</b> \u2192 professor, <b>Augustana College, Sioux Falls, South Dakota</b>, <b>13 years</b></li><li class=\"d0\">Always feared total blindness \u2014 kept a cheerful, &quot;almost hilarious&quot; attitude</li><li class=\"d0\"><b>1943</b>, age <b>52</b> \u2014 operation at the <b>Mayo Clinic</b>; could see <b>40 times</b> as well as before</li><li class=\"d0\">Dishwashing became thrilling: soap bubbles held to the light showed miniature rainbows</li><li class=\"d1\">Sparrows&#x27; gray-black wings through falling snow, seen from the kitchen window</li><li class=\"d1\">&quot;Dear Lord... I thank Thee. I thank Thee.&quot;</li></ul>","img":[]},{"t":846,"lv":2,"h":"Rule 4","b":"<ul><li class=\"p\"><b>Count your blessings \u2014 not your troubles.</b></li></ul>","img":[]}]},{"n":16,"slug":"ch-16-find-yourself-and-be-yourself-remember-there-is-no-one-else-on-earth-like-you","label":"Chapter 16","title":"Find Yourself and Be Yourself: Remember There Is No One Else on Earth Like You","audio":"ch-16-find-yourself-and-be-yourself-remember-there-is-no-one-else-on-earth-like-you.mp3","dur":936,"imgs":[],"secs":[{"t":1,"lv":2,"h":"Mrs. Edith Allred \u2014 Mount Airy, N.C.","b":"<ul><li class=\"d0\"><b>Shy</b>, overweight child; mother dressed her plain</li><li class=\"d1\">mother&#x27;s rule: &quot;<b>wide</b> will wear while <b>narrow</b> will tear&quot;</li><li class=\"d0\">No parties, no athletics \u2014 felt <b>different</b>, <b>undesirable</b></li><li class=\"d0\">Married an older man; in-laws <b>poised</b>, <b>self-confident</b> \u2014 she couldn&#x27;t match them</li><li class=\"d1\">every push to draw her out drove her <b>further into her shell</b></li><li class=\"d0\">Grew nervous, irritable \u2014 <b>dreaded</b> the doorbell</li><li class=\"d0\">Overacted &quot;gay&quot; in public to hide her failure \u2014 miserable for days after</li><li class=\"d0\">Grew unhappy enough to think of <b>suicide</b></li></ul>","img":[]},{"t":106,"lv":3,"h":"The turn","b":"<ul><li class=\"d0\">Mother-in-law, on raising her own kids: &quot;I always insisted on their <b>being themselves</b>&quot;</li><li class=\"d0\">That line changed everything \u2014 saw the misery was self-made</li><li class=\"d0\">Studied her own personality \u2014 colors, styles that suited <b>her</b>, not the pattern</li><li class=\"d0\">Joined a small organization; <b>petrified</b> the first time on a program</li><li class=\"d1\">gained a little courage <b>each time</b> she spoke</li><li class=\"d0\">Taught her own children the same lesson ever after</li></ul>","img":[]},{"t":214,"lv":2,"h":"The general problem","b":"<ul><li class=\"d0\">Dr. <b>James Gordon Gilkey</b>: unwillingness to be yourself is the hidden spring behind many neuroses, psychoses, complexes</li><li class=\"d0\"><b>Angelo Petrie</b> (13 books, thousands of syndicated newspaper articles): nobody more miserable than one who longs to be someone else</li><li class=\"d0\">Worst in <b>Hollywood</b></li><li class=\"d1\"><b>Sam Wood</b>, director (<i>Goodbye, Mr. Chips</i>, <i>For Whom the Bell Tolls</i>): his headache \u2014 actors all wanting to be &quot;second-rate <b>Lana Turners</b>&quot; or &quot;third-rate <b>Clark Gables</b>&quot;</li><li class=\"d1\">public already has that flavor, wants something else</li><li class=\"d1\">same rule from his years selling <b>real estate</b></li><li class=\"d1\">drops fastest anyone who <b>pretends</b> to be what they aren&#x27;t</li></ul>","img":[]},{"t":271,"lv":3,"h":"Applying for work","b":"<ul><li class=\"d0\"><b>Paul Boynton</b>, oil-company employment director \u2014 interviewed <b>60,000+</b> job seekers, wrote <i>Six Ways to Get a Job</i></li><li class=\"d1\">biggest mistake: not being themselves \u2014 giving the answer they think you want</li><li class=\"d1\">&quot;nobody wants a <b>counterfeit coin</b>&quot;</li></ul>","img":[]},{"t":326,"lv":3,"h":"Cass Daly \u2014 the streetcar conductor&#x27;s daughter","b":"<ul><li class=\"d0\">Big mouth, protruding buck teeth \u2014 hid them, &quot;acted glamorous&quot; \u2014 <b>ridiculous</b>, failing in a New Jersey nightclub</li><li class=\"d0\">A man in the crowd: stop hiding your teeth \u2014 they &quot;may make your <b>fortune</b>&quot;</li><li class=\"d0\">She opened her mouth wide, sang with gusto \u2014 became a <b>top star</b> in movies and radio</li><li class=\"d0\">Other comedians then tried to copy <b>her</b></li></ul>","img":[]},{"t":432,"lv":2,"h":"You are unrepeatable","b":"<ul><li class=\"d0\"><b>William James</b>: average person develops only <b>10%</b> of latent mental ability \u2014 &quot;only half awake&quot;</li><li class=\"d0\">Genetics: <b>23</b> chromosomes from father + <b>23</b> from mother = <b>46</b></li><li class=\"d1\">each chromosome: scores to hundreds of genes (Amram Shinefeld)</li><li class=\"d1\">only <b>one chance in 300 billion</b> you&#x27;d ever be born at all</li><li class=\"d1\">source: <i>You and Heredity</i>, Amram Scheinfeld</li></ul>","img":[]},{"t":488,"lv":2,"h":"Carnegie&#x27;s own lesson \u2014 learned twice","b":"<ul><li class=\"d0\">Came to New York from <b>Missouri</b> cornfields; enrolled at American Academy of Dramatic Arts</li><li class=\"d0\">His &quot;shortcut&quot;: imitate the best of <b>John Drew</b>, <b>Walter Hampden</b>, <b>Otis Skinner</b> \u2014 blend into one composite</li><li class=\"d1\">wasted years before it sank in</li><li class=\"d0\">Didn&#x27;t learn it \u2014 repeated the mistake writing his public-speaking book</li><li class=\"d1\">spent a <b>year</b> stitching together other writers&#x27; ideas</li><li class=\"d1\">result: dull, synthetic \u2014 <b>tossed the whole manuscript</b></li><li class=\"d1\">started over: &quot;you&#x27;ve got to be <b>Dale Carnegie</b>&quot;</li></ul>","img":[]},{"t":643,"lv":3,"h":"Sir Walter Raleigh (the Oxford English professor, <b>1904</b> \u2014 not the Elizabethan)","b":"<ul><li class=\"d0\">&quot;I can&#x27;t write a book commensurate with Shakespeare, but I can write a book <b>by me</b>&quot;</li></ul>","img":[]},{"t":643,"lv":3,"h":"Irving Berlin and George Gershwin","b":"<ul><li class=\"d0\">Gershwin: struggling composer, <b>$35 a week</b> in Tin Pan Alley</li><li class=\"d0\">Berlin offered him a job as musical secretary at nearly <b>3x</b> the pay</li><li class=\"d0\">Berlin&#x27;s advice: <b>don&#x27;t take it</b> \u2014 &quot;you may develop into a second-rate Berlin... if you insist on being yourself, someday you&#x27;ll be a first-rate Gershwin&quot;</li><li class=\"d0\">Gershwin heeded it \u2014 became a major American composer</li></ul>","img":[]},{"t":747,"lv":3,"h":"More who learned it the hard way","b":"<ul><li class=\"d0\"><b>Charlie Chaplin</b> \u2014 director had him imitate a German comedian; got nowhere until he was himself</li><li class=\"d0\"><b>Bob Hope</b> \u2014 years in a singing-and-dancing act; broke through once he wisecracked as himself</li><li class=\"d0\"><b>Will Rogers</b> \u2014 twirled a rope in vaudeville for <b>years without saying a word</b>; broke through once he talked while roping</li><li class=\"d0\"><b>Mary Margaret McBride</b> \u2014 failed as an Irish comedian on radio; succeeded as a plain <b>Missouri</b> country girl</li><li class=\"d0\"><b>Gene Autry</b> \u2014 tried losing his <b>Texas accent</b>, posing as a New Yorker, was laughed at; broke through twanging his banjo, singing cowboy ballads \u2014 became the world&#x27;s most popular cowboy star</li></ul>","img":[]},{"t":797,"lv":2,"h":"Closing appeal","b":"<ul><li class=\"d0\"><b>Emerson</b>, <i>Self-Reliance</i>: envy is ignorance, <b>imitation is suicide</b> \u2014 take yourself, for better or worse, as your portion</li><li class=\"d1\">no nourishing corn comes to you but through your own toil on your own plot</li><li class=\"d0\"><b>Douglas Mallock</b>&#x27;s poem: can&#x27;t be a pine \u2014 be a scrub; can&#x27;t be a tree \u2014 be a bush; can&#x27;t be the sun \u2014 be a star</li><li class=\"d1\">&quot;be the <b>best</b> of whatever you are&quot;</li></ul>","img":[]},{"t":907,"lv":2,"h":"Rule 5","b":"<ul><li class=\"p\"><b>Let&#x27;s not imitate others. Let&#x27;s find ourselves and be ourselves.</b></li></ul>","img":[]}]},{"n":17,"slug":"ch-17-if-you-have-a-lemon-make-a-lemonade","label":"Chapter 17","title":"If You Have a Lemon, Make a Lemonade","audio":"ch-17-if-you-have-a-lemon-make-a-lemonade.mp3","dur":994,"imgs":[],"secs":[{"t":1,"lv":2,"h":"Chapter 17: If You Have a Lemon, Make a Lemonade","b":"","img":[]},{"t":1,"lv":3,"h":"Dale Carnegie","b":"","img":[]},{"t":1,"lv":2,"h":"Opening idea \u2014 Hutchins &amp; Rosenwald","b":"<ul><li class=\"d0\"><b>Robert Maynard Hutchins</b>, Chancellor, University of Chicago</li><li class=\"d0\">advice from the late <b>Julius Rosenwald</b>, president of Sears, Roebuck and Company</li><li class=\"d0\">&quot;When you have a <b>lemon</b>, make a <b>lemonade</b>&quot;</li><li class=\"d0\">the fool: gives up \u2014 &quot;I&#x27;m beaten. It is fate.&quot; \u2014 self-pity</li><li class=\"d0\">the wise man asks: &quot;What lesson can I learn? How can I improve my situation?&quot;</li></ul>","img":[]},{"t":52,"lv":2,"h":"Alfred Adler","b":"<ul><li class=\"d0\">psychologist, lifetime studying people&#x27;s hidden reserves of power</li><li class=\"d0\">humans&#x27; power to turn a <b>minus into a plus</b></li></ul>","img":[]},{"t":105,"lv":2,"h":"Thelma Thompson \u2014 the desert","b":"<ul><li class=\"d0\">husband stationed near the <b>Mojave Desert</b>, California, during the war</li><li class=\"d0\">hated it, loathed it \u2014 <b>125 degrees</b> in the shade of a cactus</li><li class=\"d0\">alone in a tiny shack \u2014 wind, sand in the food, sand in the air</li><li class=\"d0\">wrote her parents: giving up, coming home, &quot;rather be in jail&quot;</li><li class=\"d0\">father&#x27;s reply \u2014 just <b>two lines</b>:</li><li class=\"d1\">&quot;Two men looked out from prison bars. One saw the mud, the other saw the stars.&quot;</li><li class=\"d0\">ashamed of herself \u2014 decided to look for the stars</li><li class=\"d0\">made friends with the natives \u2014 given pottery and weaving they&#x27;d refused to sell tourists</li><li class=\"d0\">studied cactus, yuccas, Joshua trees</li><li class=\"d0\">learned prairie dogs, watched desert sunsets, hunted <b>sea shells</b> \u2014 desert once an ocean floor</li><li class=\"d0\">&quot;The Mojave Desert hadn&#x27;t changed, but I had.&quot;</li><li class=\"d0\">wrote a novel, published as <b><i>Bright Ramparts</b></i></li></ul>","img":[]},{"t":212,"lv":3,"h":"Old truths","b":"<ul><li class=\"d0\">Greeks, <b>500 years</b> before Christ \u2014 the best things are the most difficult</li><li class=\"d0\"><b>Harry Emerson Fosdick</b>: &quot;Happiness is not mostly pleasure. It is mostly victory.&quot;</li></ul>","img":[]},{"t":264,"lv":2,"h":"The rattlesnake farmer \u2014 Florida","b":"<ul><li class=\"d0\">land so wretched \u2014 no fruit, no pigs, nothing but scrub oaks and <b>rattlesnakes</b></li><li class=\"d0\">turned the liability into an asset \u2014 canned rattlesnake meat</li><li class=\"d0\">tourists pouring in \u2014 <b>20,000 a year</b></li><li class=\"d0\">venom shipped to labs to make anti-venom toxin</li><li class=\"d0\">skins sold at fancy prices \u2014 women&#x27;s shoes, handbags</li><li class=\"d0\">canned meat shipped worldwide</li><li class=\"d0\">village rechristened <b>Rattlesnake, Florida</b></li></ul>","img":[]},{"t":322,"lv":2,"h":"William Bolitho","b":"<ul><li class=\"d0\">author, <b><i>Twelve Against the Gods</b></i></li><li class=\"d0\">&quot;The most important thing in life is not to capitalize on your gains... The really important thing is to profit from your losses.&quot;</li><li class=\"d0\">said this after losing a <b>leg</b> in a railway accident</li></ul>","img":[]},{"t":374,"lv":2,"h":"Ben Fortson \u2014 the Atlanta elevator","b":"<ul><li class=\"d0\">met in a hotel elevator, <b>Atlanta, Georgia</b> \u2014 both legs gone, in a wheelchair</li><li class=\"d0\">cheerful, warm smile \u2014 apologized for the inconvenience</li><li class=\"d0\">the accident: <b>1929</b>, age <b>24</b></li><li class=\"d1\">hauling hickory poles to stake beans in his garden</li><li class=\"d1\">a pole slipped under the car, jammed the steering mid-turn</li><li class=\"d1\">car shot over an embankment, hurled him against a tree</li><li class=\"d1\">spine hurt, legs paralyzed \u2014 never took a step since</li><li class=\"d0\">at first: raged, rebelled, fumed at his fate \u2014 got him only bitterness</li><li class=\"d0\">realized others were kind to him \u2014 so he&#x27;d be kind to them</li><li class=\"d0\">&quot;I am almost glad now that it happened&quot;</li><li class=\"d0\">read at least <b>1,400 books</b> in <b>14 years</b></li><li class=\"d0\">developed a love of good literature, thrilled now by great symphonies</li><li class=\"d0\">for the first time had time to <b>think</b> \u2014 a real sense of values</li><li class=\"d0\">got interested in politics, studied public questions, made speeches</li><li class=\"d0\">from his wheelchair became <b>Secretary of State for Georgia</b></li></ul>","img":[]},{"t":529,"lv":2,"h":"Al Smith","b":"<ul><li class=\"d0\">Carnegie&#x27;s adult-education students often regret never going to college</li><li class=\"d0\">Carnegie knew thousands of successful men who never went past high school</li><li class=\"d0\">the man who never finished grade school:</li><li class=\"d1\">father died \u2014 his friends chipped in to pay for the coffin</li><li class=\"d1\">mother worked in an umbrella factory <b>10 hours a day</b>, piecework till <b>11 o&#x27;clock</b> at night</li><li class=\"d1\">amateur dramatics at his church \u2192 thrill of acting \u2192 public speaking \u2192 politics</li><li class=\"d1\">elected to the New York State legislature at <b>30</b></li><li class=\"d1\">woefully unprepared \u2014 bills read like the language of the Choctaw Indians</li><li class=\"d1\">put on the forests committee \u2014 never set foot in a forest</li><li class=\"d1\">put on the state banking commission \u2014 never had a bank account</li><li class=\"d1\">nearly resigned \u2014 ashamed to admit defeat to his mother</li><li class=\"d1\">decided to study <b>16 hours a day</b> \u2014 turn the lemon of ignorance into the lemonade of knowledge</li><li class=\"d0\">10 years later: greatest living authority on the government of New York State</li><li class=\"d0\">New York Times called him &quot;the best loved citizen of New York&quot;</li><li class=\"d0\">elected Governor of New York for <b>four terms</b> \u2014 a record never before attained</li><li class=\"d0\"><b>1928</b> \u2014 Democratic candidate for President</li><li class=\"d0\"><b>six</b> universities, including Columbia and Harvard, conferred honorary degrees on him</li><li class=\"d0\">this is <b>Al Smith</b></li></ul>","img":[]},{"t":686,"lv":2,"h":"Nietzsche &amp; William James","b":"<ul><li class=\"d0\">Nietzsche&#x27;s superior man: not only bears necessity, but <i>loves</i> it</li><li class=\"d0\">many men of achievement succeeded because handicaps spurred them on</li><li class=\"d0\">William James: &quot;our very infirmities help us unexpectedly&quot;</li></ul>","img":[]},{"t":745,"lv":2,"h":"The infirmity list","b":"<ul><li class=\"d0\"><b>Milton</b> \u2014 wrote better poetry because he was blind</li><li class=\"d0\"><b>Beethoven</b> \u2014 composed better music because he was deaf</li><li class=\"d0\"><b>Helen Keller</b> \u2014 brilliant career made possible by blindness and deafness</li><li class=\"d0\"><b>Tchaikovsky</b> \u2014 driven near suicide by a tragic marriage \u2192 composed <i>Symphonie Path\u00e9tique</i></li><li class=\"d0\"><b>Dostoevsky</b> and <b>Tolstoy</b> \u2014 tortured lives \u2192 immortal novels</li><li class=\"d0\"><b>Charles Darwin</b> \u2014 &quot;If I had not been so great an invalid, I should not have done so much work as I have accomplished&quot;</li><li class=\"d0\"><b>Abraham Lincoln</b> \u2014 born the same day as Darwin, log cabin in the forests of Kentucky</li><li class=\"d1\">found the words for Gettysburg and the second inauguration: &quot;with malice toward none, with charity for all&quot;</li></ul>","img":[]},{"t":804,"lv":2,"h":"Harry Emerson Fosdick \u2014 <i>The Power to See It Through</i>","b":"<ul><li class=\"d0\">Scandinavian saying: &quot;The north wind made the Vikings&quot;</li><li class=\"d0\">secure, pleasant living never of itself made people good or happy</li><li class=\"d0\">self-pity persists even laid softly on a cushion</li><li class=\"d0\">character and happiness come when people shoulder their own responsibility</li></ul>","img":[]},{"t":861,"lv":2,"h":"If too discouraged to try \u2014 two reasons anyway","b":"<ul><li class=\"num\"><span>1</span>We may succeed</li><li class=\"num\"><span>2</span>Even failing, the attempt turns us to look forward instead of backward \u2014 replaces negative thoughts with positive ones, releases creative energy</li></ul>","img":[]},{"t":913,"lv":2,"h":"Ole Bull","b":"<ul><li class=\"d0\">world-famous violinist, concert in Paris</li><li class=\"d0\">the <b>A string</b> on his violin suddenly snapped</li><li class=\"d0\">finished the melody on <b>three strings</b></li><li class=\"d0\">Fosdick: &quot;That is life... It is more than life. It is life triumphant.&quot;</li></ul>","img":[]},{"t":913,"lv":2,"h":"Closing \u2014 Bolitho again","b":"<ul><li class=\"d0\">wanted these words &quot;carved in eternal bronze&quot; in every schoolhouse</li><li class=\"d0\">not capitalizing on gains, but profiting from losses \u2014 that takes intelligence</li></ul>","img":[]},{"t":968,"lv":2,"h":"Rule 6","b":"<ul><li class=\"d0\">When fate hands us a lemon, let&#x27;s try to make a lemonade</li></ul>","img":[]}]},{"n":18,"slug":"ch-18-how-to-cure-depression-in-fourteen-days","label":"Chapter 18","title":"How to Cure Depression in Fourteen Days","audio":"ch-18-how-to-cure-depression-in-fourteen-days.mp3","dur":1958,"imgs":[],"secs":[{"t":2,"lv":2,"h":"Chapter 18: How to Cure Depression in Fourteen Days","b":"","img":[]},{"t":2,"lv":2,"h":"The $200 Contest","b":"<ul><li class=\"d0\">Carnegie offered a <b>$200</b> prize for the best true story on conquering worry</li><li class=\"d0\">Judges: <b>Eddie Rickenbacker</b> (Pres., Eastern Airlines), <b>Dr. Stuart W. McClelland</b> (Pres., Lincoln Memorial University), <b>H.B. Colton</b>, radio news analyst</li><li class=\"d0\">Two stories tied \u2014 prize <b>split</b></li></ul>","img":[]},{"t":54,"lv":2,"h":"C.R. Burton&#x27;s Story \u2014 Whizzear Motor Sales, Springfield","b":"<ul><li class=\"d0\">Lost his mother at <b>9</b>, father at <b>12</b></li><li class=\"d0\">Mother <b>walked out</b> 19 years ago with his two little sisters \u2014 never seen again</li><li class=\"d1\">didn&#x27;t write for <b>7 years</b></li><li class=\"d0\">Father killed in a car accident at <b>Salinas, Kansas</b></li><li class=\"d1\">his caf\u00e9 partner sold the business for cash and <b>skipped out</b></li><li class=\"d0\">Father&#x27;s sisters took in three of the children \u2014 nobody wanted Ralph and his little brother</li><li class=\"d0\">Lived briefly with a poor family; they lost their job, couldn&#x27;t feed him</li><li class=\"d0\"><b>Mr. and Mrs. Lofton</b> took him in \u2014 farm <b>11 miles</b> from town</li><li class=\"d1\">Mr. Lofton, <b>70</b>, sick in bed with <b>shingles</b></li><li class=\"d1\">three rules only: don&#x27;t lie, don&#x27;t steal, do as told \u2014 &quot;my Bible&quot;</li><li class=\"d0\">At school: mocked for his big nose, called <b>&quot;orphan brat&quot;</b></li><li class=\"d1\">Lofton: takes a <b>bigger man</b> to walk away from a fight than to stay and fight</li><li class=\"d1\">finally fought back after a boy threw chicken manure in his face \u2014 won friends</li><li class=\"d1\">a girl ruined his new cap, filled it with water</li><li class=\"d0\"><b>Mrs. Lofton&#x27;s</b> advice: they&#x27;ll stop teasing you once you get <b>interested</b> in them and see how much you can do for them</li><li class=\"d1\">he studied hard, headed the class, was never envied \u2014 because he <b>helped</b></li><li class=\"d1\">wrote themes, essays, debates, book reviews for other kids; tutored a girl in math</li><li class=\"d1\">one boy pretended to go <b>possum hunting</b> to hide that he was getting help</li><li class=\"d0\">Death struck the neighborhood \u2014 two farmers died, one wife deserted</li><li class=\"d1\">he was the only male for <b>four families</b>, <b>two years</b> \u2014 cut wood, milked cows, fed stock</li><li class=\"d0\">Came home from the <b>Navy</b> \u2014 over <b>200 farmers</b> visited the first day, some drove <b>80 miles</b></li><li class=\"d0\">Hasn&#x27;t been called orphan brat in <b>13 years</b></li></ul>","img":[]},{"t":319,"lv":2,"h":"Dr. Frank Loup \u2014 Seattle","b":"<ul><li class=\"d0\">Invalid <b>23 years</b>, arthritis</li><li class=\"d0\">Stuart Whithouse (Seattle Star): the most unselfish man, got more out of life than anyone</li><li class=\"d0\">Motto: <b>&quot;Ich dien&quot;</b> \u2014 &quot;I serve&quot; \u2014 the Prince of Wales&#x27;s own words</li><li class=\"d0\">Wrote an average of <b>1,400 letters a year</b>, cheering other invalids</li><li class=\"d0\">Founded the <b>Shut-In Society</b> \u2014 a national organization; got radios and books for shut-ins</li><li class=\"d0\">Had <b>purpose</b> \u2014 not, as Shaw put it, &quot;a self-centred little clod of ailments&quot;</li></ul>","img":[]},{"t":427,"lv":2,"h":"Alfred Adler&#x27;s Prescription","b":"<ul><li class=\"d0\">To melancholia patients: <b>&quot;you can be cured in 14 days&quot;</b> if you follow this prescription</li><li class=\"d1\"><b>&quot;Try to think every day how you can please someone&quot;</b></li><li class=\"d0\">From Adler&#x27;s book <i>What Life Should Mean to You</i></li><li class=\"d0\">Melancholia = a long <b>rage and reproach</b> against others, disguised as guilt</li><li class=\"d0\">First rule of treatment: <b>never do anything you don&#x27;t like</b></li><li class=\"d1\">removes the patient&#x27;s grievance, his excuse to dominate or accuse</li><li class=\"d1\">Adler: never a <b>suicide</b> among his patients under this rule</li><li class=\"d0\">Patients resist the 14-day challenge: &quot;I&#x27;ve done it all my life&quot; (they hadn&#x27;t) / &quot;I could never \u2014 I&#x27;m too worried&quot;</li><li class=\"d0\">Adler&#x27;s answer: don&#x27;t stop worrying, but <b>think of others too</b></li><li class=\"d0\">The cure = connecting with fellow men on <b>equal, cooperative</b> footing</li><li class=\"d0\">&quot;Love thy neighbor&quot; \u2014 the one uninterested in others causes the greatest <b>injury</b></li><li class=\"d0\">Prophet Muhammad: a good deed <b>&quot;brings a smile of joy to the face of another&quot;</b></li></ul>","img":[]},{"t":799,"lv":2,"h":"Mrs. William T. Moon \u2014 Moon Secretarial School, NYC","b":"<ul><li class=\"d0\">Beat Adler by <b>13 days</b> \u2014 cured her own melancholy in <b>one day</b></li><li class=\"d0\">Five years back, Christmas Eve, first Christmas alone since her husband&#x27;s death</li><li class=\"d0\">Declined friends&#x27; invitations \u2014 didn&#x27;t want to be a wet blanket</li><li class=\"d0\">Walked aimlessly up <b>Fifth Avenue</b>, boarded a random bus at the terminal</li><li class=\"d0\">Crossed the <b>Hudson River</b>, rode to the last stop \u2014 an unknown town</li><li class=\"d0\">Wandered into a church, heard <b>&quot;Silent Night,&quot;</b> fell asleep in a pew</li><li class=\"d0\">Woke to two small orphans staring \u2014 the girl: <b>&quot;I wonder if Santa Claus brought her&quot;</b></li><li class=\"d0\">Showed them the tree, took them to a <b>drugstore</b> \u2014 refreshments, candy, presents</li><li class=\"d0\">&quot;Those two orphans did <b>far more for me</b> than I did for them&quot;</li><li class=\"d0\">Happiness is <b>contagious</b> \u2014 found by giving</li></ul>","img":[]},{"t":1063,"lv":2,"h":"Margaret Taylor Yates \u2014 Pearl Harbor","b":"<ul><li class=\"d0\">Popular US Navy novelist; bad <b>heart</b>, invalid over a year, <b>22 of 24 hours</b> in bed</li><li class=\"d0\">Dec. 7 attack \u2014 a bomb&#x27;s concussion <b>threw her out of bed</b></li><li class=\"d0\">Red Cross made her a phone <b>clearinghouse</b> for Army/Navy families</li><li class=\"d0\">Husband, Commander <b>Robert Raleigh Yates</b>, confirmed safe</li><li class=\"d0\"><b>2,117</b> officers/enlisted killed, <b>960</b> missing, Navy and Marine Corps</li><li class=\"d0\">Took calls lying down, then sitting up, then <b>out of bed at a table</b></li><li class=\"d0\">Never returned to bed except her normal <b>8 hours&#x27;</b> sleep</li><li class=\"d0\">&quot;It took my attention off myself and focused it on others&quot;</li></ul>","img":[]},{"t":1121,"lv":2,"h":"Carl Jung&#x27;s Third","b":"<ul><li class=\"d0\">About <b>one-third</b> of his patients suffer not from real neurosis but from the <b>senselessness and emptiness</b> of their lives</li><li class=\"d0\">They &quot;miss the boat,&quot; then blame everyone but themselves</li></ul>","img":[]},{"t":1278,"lv":2,"h":"The Ordinary Life","b":"<ul><li class=\"d0\">No crisis needed \u2014 you meet people daily: the <b>postman</b>, the grocery boy, the newspaper vendor, the shoeshine boy</li><li class=\"d0\">Do you ever really ask about them?</li><li class=\"d0\">Don&#x27;t need to be a <b>Florence Nightingale</b> \u2014 start tomorrow with the people you meet</li><li class=\"d0\"><b>Aristotle</b>: &quot;enlightened selfishness&quot;</li><li class=\"d0\"><b>Zoroaster</b>: doing good for others is a <b>joy</b>, not a duty</li><li class=\"d0\"><b>Benjamin Franklin</b>: &quot;When you are good to others, you are best to yourself&quot;</li><li class=\"d0\"><b>Henry C. Link</b>, director, Psychological Service Center, NY: self-sacrifice is essential to self-realization</li></ul>","img":[]},{"t":1383,"lv":2,"h":"Professor William Lyon Phelps \u2014 Yale","b":"<ul><li class=\"d0\">Never enters a hotel, barber shop, or store without saying something <b>agreeable</b></li><li class=\"d0\">Compliments the shopgirl&#x27;s eyes or hair; asks the barber about his day</li><li class=\"d0\">Shakes hands with the <b>redcap</b> who carried his bag</li><li class=\"d0\">Sweltering day, <b>New Haven Railway</b> dining car, slow service</li><li class=\"d1\">sympathized aloud with the cooks sweating in the hot kitchen</li><li class=\"d1\">the steward: in <b>19 years</b>, the first passenger ever to pity the cooks</li><li class=\"d0\">Compliments strangers&#x27; <b>dogs</b> \u2014 the owner later seen petting his dog with new pride</li><li class=\"d0\">England: praised a <b>shepherd&#x27;s sheepdog</b>, asked how it was trained \u2014 dog ends up with paws on the shepherd&#x27;s shoulders, both beaming</li><li class=\"d0\">Chinese proverb: <b>&quot;A bit of fragrance always clings to the hand that gives you roses&quot;</b></li></ul>","img":[]},{"t":1588,"lv":2,"h":"The Grandmother&#x27;s Secret","b":"<ul><li class=\"d0\">Reared in a <b>social register family in Philadelphia</b> \u2014 but poor</li><li class=\"d0\">Ashamed of her outdated clothes, cried herself to sleep</li><li class=\"d0\">At dinner parties, asked her partner about <b>his</b> life, plans, ideas \u2014 only to hide her clothes</li><li class=\"d0\">Grew genuinely interested \u2014 became the <b>most popular girl</b> in her set</li><li class=\"d0\"><b>Three men proposed</b> marriage to her</li><li class=\"d0\">Confessed this to Carnegie after driving him <b>50 miles</b> to catch the New York Central</li></ul>","img":[]},{"t":1745,"lv":2,"h":"The Atheists&#x27; Testimony","b":"<ul><li class=\"d0\"><b>A.E. Housman</b>, Cambridge scholar, contemplated suicide \u2014 1936 address called Jesus&#x27;s words the greatest truth ever spoken: &quot;He that findeth his life shall lose it...&quot;</li><li class=\"d0\"><b>Theodore Dreiser</b> called life &quot;a tale told by an idiot, full of sound and fury, signifying nothing&quot; \u2014 yet still preached <b>service to others</b></li><li class=\"d0\">&quot;I shall pass this way but once&quot; \u2014 do good now, don&#x27;t defer</li></ul>","img":[]},{"t":1798,"lv":2,"h":"Rule 7","b":"<ul><li class=\"p\"><b>Forget yourself by becoming interested in others every day \u2014 do a good deed that puts a smile of joy on someone&#x27;s face.</b></li></ul>","img":[]},{"t":1905,"lv":2,"h":"Part Four Recap \u2014 Seven Rules for Peace and Happiness","b":"<ul><li class=\"num\"><span>1</span>Fill your mind with thoughts of <b>peace</b>, courage, health, hope</li><li class=\"num\"><span>2</span>Never try to get even with <b>enemies</b> \u2014 it hurts you more than them; never waste a minute on people you don&#x27;t like</li><li class=\"num\"><span>3</span>Expect <b>ingratitude</b></li><li class=\"d1\">Jesus healed 10 lepers, only one gave thanks</li><li class=\"d1\">happiness comes from giving for the joy of it, not for gratitude</li><li class=\"d1\">gratitude is a cultivated trait \u2014 train children to it</li><li class=\"d1\"><b>count your blessings</b>, not your troubles</li><li class=\"num\"><span>5</span>Don&#x27;t <b>imitate</b> others \u2014 find and be yourself; envy is ignorance, imitation is suicide</li><li class=\"num\"><span>6</span>When fate hands you a <b>lemon</b>, make lemonade</li><li class=\"num\"><span>7</span>Forget your own unhappiness by creating happiness for <b>others</b></li></ul>","img":[]}]},{"n":19,"slug":"ch-19-how-my-mother-and-father-conquered-worry","label":"Chapter 19","title":"How My Mother and Father Conquered Worry","audio":"ch-19-how-my-mother-and-father-conquered-worry.mp3","dur":2639,"imgs":[],"secs":[{"t":10,"lv":2,"h":"Chapter 19: How My Mother and Father Conquered Worry","b":"","img":[]},{"t":10,"lv":2,"h":"Missouri Farm Childhood","b":"<ul><li class=\"d0\">Born and raised on Missouri farm</li><li class=\"d0\">Parents: <b>mother</b> country school teacher, <b>father</b> farmhand</li><li class=\"d1\">Father worked for <b>$12 a month</b></li><li class=\"d0\">Mother made not just clothes but <b>soap</b></li><li class=\"d0\">Cash only once a year \u2014 from selling hogs</li><li class=\"d0\">Traded butter and eggs for flour, sugar, coffee</li><li class=\"d0\">At 12: less than <b>50 cents</b> a year to spend</li><li class=\"d1\">Fourth of July: father gave him <b>10 cents</b> \u2014 felt &quot;the wealth of the Indies&quot;</li><li class=\"d0\">Walked <b>a mile</b> to one-room school</li><li class=\"d1\">Snow deep, thermometer <b>28 below zero</b></li><li class=\"d1\">No rubbers or overshoes until age <b>14</b></li><li class=\"d1\">Feet always wet and cold</li><li class=\"d0\">Parents slaved <b>16 hours a day</b></li><li class=\"d0\">Still oppressed by debt, hard luck</li></ul>","img":[]},{"t":114,"lv":2,"h":"The Floods and the Losses","b":"<ul><li class=\"d0\">Earliest memory: flood waters of the <b>102 River</b> rolling over corn and hay</li><li class=\"d0\">Floods destroyed crops <b>six years out of seven</b></li><li class=\"d0\">Hogs died of <b>cholera</b>, year after year \u2014 burned the carcasses</li><li class=\"d1\">Pungent odor of burning hog flesh</li><li class=\"d0\">The one flood-free year:</li><li class=\"d1\">Bumper corn crop</li><li class=\"d1\">Bought feed cattle, fattened them on their own corn</li><li class=\"d1\">Cattle prices <b>fell</b> on the Chicago market</li><li class=\"d1\">Net gain for the whole year&#x27;s work: only <b>$30</b></li><li class=\"d0\">Mule colts: fed <b>3 years</b>, hired men to break them</li><li class=\"d1\">Shipped to <b>Memphis, Tennessee</b></li><li class=\"d1\">Sold for <b>less</b> than they&#x27;d paid</li><li class=\"d0\">After <b>10 years</b> of hard work: penniless, deep in debt, farm mortgaged</li><li class=\"d1\">Couldn&#x27;t even pay the interest</li><li class=\"d1\">Bank <b>abused and insulted</b> father, threatened foreclosure</li></ul>","img":[]},{"t":220,"lv":2,"h":"Father&#x27;s Despair","b":"<ul><li class=\"d0\">Father was <b>47</b>, after more than <b>30 years</b> of hard work \u2014 nothing but debts and humiliation</li><li class=\"d0\">Worried himself sick</li><li class=\"d1\">Health broke, no appetite, took medicine just to eat, lost flesh</li><li class=\"d1\">Doctor told mother: dead within <b>6 months</b></li><li class=\"d0\">Mother feared finding him hanged in the barn</li><li class=\"d0\">Returning from <b>Maryville</b> (banker had threatened foreclosure)</li><li class=\"d1\">Stopped the wagon on the bridge over the <b>102 River</b></li><li class=\"d1\">Stood a long time looking at the water, debating whether to jump</li><li class=\"d1\">Only thing that stopped him: mother&#x27;s <b>deep, abiding, joyous</b> faith</li><li class=\"d0\">Outcome: father lived <b>42 more happy years</b> \u2014 died <b>1941</b>, age <b>89</b></li></ul>","img":[]},{"t":272,"lv":2,"h":"Mother&#x27;s Faith","b":"<ul><li class=\"d0\">Never worried, through it all</li><li class=\"d0\">Took every trouble to God in prayer</li><li class=\"d0\">Read a <b>Bible chapter</b> every night</li><li class=\"d0\">Knelt with the family before chairs in the farmhouse to pray</li><li class=\"d0\"><b>William James</b> (Harvard philosophy): &quot;sovereign cure for worry is religious faith&quot; \u2014 mother found it on a Missouri farm</li><li class=\"d0\">Sang while she worked: &quot;Peace, peace, wonderful peace&quot;</li></ul>","img":[]},{"t":325,"lv":2,"h":"Carnegie&#x27;s Own Doubt","b":"<ul><li class=\"d0\">Mother wanted him for religious work \u2014 he considered foreign missionary work</li><li class=\"d0\">College changed him: biology, science, philosophy, comparative religion</li><li class=\"d0\">Began to doubt scripture, doctrine</li><li class=\"d0\">Became <b>agnostic</b> \u2014 believed life planless, aimless</li><li class=\"d1\">Humans no more purposeful than dinosaurs <b>200 million years</b> ago</li><li class=\"d1\">Sun cooling; a <b>10%</b> drop in temperature would end life on earth</li><li class=\"d0\">Still surrounded by mystery: the body, electricity, a flower, green grass</li><li class=\"d1\"><b>Charles F. Kettering</b> (GM Research) gave Antioch College <b>$30,000 a year</b> just to learn why grass is green</li><li class=\"d1\">GM spent years and millions trying to explain why a spark makes an engine run</li><li class=\"d0\">Not understanding a mystery never stopped us from using it \u2014 same true of prayer</li><li class=\"d0\"><b>Santayana</b>: man not made to understand life, but to live it</li><li class=\"d0\">Carnegie: not &quot;back&quot; to religion but forward to a new concept of it</li><li class=\"d1\">No interest in creed differences \u2014 interested in what religion <b>does</b></li><li class=\"d1\">Gives zest, faith, hope, courage; banishes anxiety; gives purpose and health</li><li class=\"d0\"><b>Francis Bacon</b>, over 300 years ago: &quot;a little philosophy inclineth man&#x27;s mind to atheism, but depth in philosophy bringeth men&#x27;s minds about to religion&quot;</li></ul>","img":[]},{"t":590,"lv":2,"h":"Psychiatry Meets Faith","b":"<ul><li class=\"d0\">Newest science, psychiatry, teaching what Jesus taught</li><li class=\"d0\"><b>Dr. A.A. Brill</b>: truly religious people don&#x27;t develop neurosis</li><li class=\"d0\">Interviewed <b>Henry Ford</b>, a few years before his death</li><li class=\"d1\">Expected strain \u2014 found him calm, well, at <b>78</b></li><li class=\"d1\">Ford: &quot;I believe God is managing affairs... what is there to worry about?&quot;</li><li class=\"d0\">Psychiatrists becoming modern evangelists \u2014 not to dodge hellfire, but ulcers, angina, breakdowns, insanity</li><li class=\"d0\">Recommends Dr. Henry C. Link&#x27;s book <i>Return to Religion</i></li><li class=\"d0\">Jesus: &quot;I came that ye might have life more abundantly&quot;</li><li class=\"d1\">Denounced dead ritual \u2014 a <b>rebel</b>, crucified for it</li><li class=\"d1\">Religion for man, not man for religion; Sabbath for man</li><li class=\"d1\">Talked more of fear than sin \u2014 the wrong kind of fear is itself a sin</li><li class=\"d0\"><b>Emerson</b>: &quot;professor of the science of joy&quot; \u2014 so was Jesus</li><li class=\"d0\"><b>Henry Price</b> of Tulsa, Oklahoma (Carnegie&#x27;s father-in-law): agnostic, doesn&#x27;t attend church, but lives the Golden Rule</li><li class=\"d0\"><b>John Baillie</b> (theology, Edinburgh): what makes a man Christian is spirit and participation, not doctrine</li><li class=\"d0\"><b>William James</b>, letter to Thomas Davidson: less and less able to get along without God as the years passed</li></ul>","img":[]},{"t":863,"lv":2,"h":"Mary Cushman&#x27;s Story (disguised name \u2014 tied for first prize)","b":"<ul><li class=\"d0\">The Depression: husband&#x27;s average wage <b>$18 a week</b>, often less \u2014 sick often (mumps, scarlet fever, flu)</li><li class=\"d0\">Lost the house they&#x27;d built themselves</li><li class=\"d0\">Owed <b>$50</b> at the grocery store, five children to feed</li><li class=\"d0\">Took in washing and ironing; wore secondhand Salvation Army clothes</li><li class=\"d0\">Grocer accused her <b>11-year-old son</b> of stealing pencils \u2014 the last straw</li><li class=\"d0\">Shut off the washing machine, took her <b>5-year-old daughter</b> upstairs</li><li class=\"d1\">Sealed windows and cracks with paper and rags</li><li class=\"d1\">Turned on the gas heater, unlit</li><li class=\"d1\">Lay down beside her daughter, listening to the gas escape</li><li class=\"d0\">Heard a hymn on the radio she&#x27;d forgotten to turn off: &quot;What a Friend We Have in Jesus&quot;</li><li class=\"d0\">Realized her mistake \u2014 jumped up, turned off gas, opened windows</li><li class=\"d0\">Spent the day weeping and praying \u2014 thanksgiving, not pleading</li><li class=\"d0\">Promised God she&#x27;d never be ungrateful again</li><li class=\"d0\">Moved into a rented country schoolhouse, <b>$5 a month</b> \u2014 thanked God for it</li><li class=\"d0\">Things slowly improved: hat-check girl at a country club, sold stockings on the side</li><li class=\"d1\">One son milked <b>13 cows</b> morning and night to help pay for college</li><li class=\"d0\">Now: children grown, married, <b>3 grandchildren</b></li><li class=\"d0\">On suicide: &quot;the blackest moments... can only last a little time&quot;</li></ul>","img":[]},{"t":1238,"lv":2,"h":"The Statistics and the Testimony","b":"<ul><li class=\"d0\">On average: a suicide every <b>35 minutes</b> in the US; someone goes insane every <b>120 seconds</b></li><li class=\"d0\"><b>Dr. Carl Jung</b> (<i>Modern Man in Search of a Soul</i>, p. 264): of patients over <b>35</b>, across <b>30 years</b> of practice, every one&#x27;s real problem was a lost religious outlook \u2014 none healed without regaining it</li><li class=\"d0\"><b>William James</b>: &quot;faith is one of the forces by which men live... the total absence of it means collapse&quot;</li><li class=\"d0\"><b>Gandhi</b>: &quot;Without prayer, I should have been a lunatic long ago&quot;</li><li class=\"d0\">Carnegie&#x27;s own father would have drowned himself without mother&#x27;s prayers</li><li class=\"d0\">&quot;No atheists in foxholes&quot; \u2014 but why wait for desperation?</li></ul>","img":[]},{"t":1290,"lv":2,"h":"Carnegie&#x27;s Own Habit","b":"<ul><li class=\"d0\">Drops into empty churches on weekday afternoons when he feels rushed</li><li class=\"d0\">Frequently visits <b>St. Patrick&#x27;s Cathedral</b>, Fifth Avenue, though a Protestant</li><li class=\"d0\">Reminds himself he&#x27;ll be dead within <b>30 years</b> \u2014 the truths churches teach are eternal</li><li class=\"d0\">Calms nerves, rests body, clarifies perspective</li></ul>","img":[]},{"t":1453,"lv":2,"h":"John R. Anthony&#x27;s Story (Houston, Texas \u2014 book salesman)","b":"<ul><li class=\"d0\">Closed his law office to sell a set of law books for a book company</li><li class=\"d0\">Well trained, well prepared \u2014 still couldn&#x27;t get orders</li><li class=\"d0\">Grew afraid to even enter a prospect&#x27;s office \u2014 paced the hallway, circled the block</li><li class=\"d0\">Sales manager threatened to cut his advances; wife pleaded for grocery money; <b>3 children</b></li><li class=\"d0\">Broke, couldn&#x27;t pay the hotel bill, couldn&#x27;t afford the ticket home</li><li class=\"d0\">One night: only a glass of hot milk for dinner</li><li class=\"d0\">Turned to God \u2014 prayed for light, understanding, orders, money</li><li class=\"d0\">Opened a <b>Gideon Bible</b> on the dresser \u2014 read Matthew: &quot;take no thought for your life...&quot;</li><li class=\"d0\">Miracle: tension fell away, fear turned to courage and hope</li><li class=\"d0\">Slept soundly for the first time in years</li><li class=\"d0\">Next morning: walked into the first prospect&#x27;s office with confidence \u2014 made the sale</li><li class=\"d0\">Made more sales that day than in the weeks before</li><li class=\"d0\">That night: <b>steak with all the fixings</b>, not hot milk</li><li class=\"d0\">&quot;Born anew&quot; <b>22 years ago</b> in a small hotel in <b>Amarillo, Texas</b></li></ul>","img":[]},{"t":1831,"lv":2,"h":"Mrs. L.G. Baird&#x27;s Story (Highland, Illinois)","b":"<ul><li class=\"d0\">Phone rang <b>14 times</b> before she found courage to answer \u2014 feared the hospital</li><li class=\"d0\">Son had <b>meningitis</b>; penicillin given, fever fluctuating, feared brain damage</li><li class=\"d0\">Doctor: only <b>one chance in four</b> the baby would live</li><li class=\"d0\">Husband broke down driving home, fist on the wheel: &quot;Bets, I can&#x27;t give that little guy up&quot;</li><li class=\"d0\">Stopped at a church, prayed: &quot;not my will, but thine be done&quot;</li><li class=\"d0\">Felt peace immediately; slept soundly that night for the first time in a week</li><li class=\"d0\">Days later: doctor called \u2014 the boy, <b>Bobby</b>, had passed the crisis</li><li class=\"d0\">Today: a strong, healthy <b>4-year-old</b></li></ul>","img":[]},{"t":1936,"lv":2,"h":"The He-Men Who Pray","b":"<ul><li class=\"d0\"><b>Jack Dempsey</b>: prayed before every meal, every night, and before the bell each round</li><li class=\"d0\"><b>Connie Mack</b>: couldn&#x27;t sleep without praying</li><li class=\"d0\"><b>Eddie Rickenbacker</b>: believed prayer saved his life</li><li class=\"d0\"><b>Edward R. Stettinius</b>: prayed for wisdom morning and night</li><li class=\"d0\"><b>J. Pierpont Morgan</b>: knelt in prayer at Trinity Church, Wall Street, Saturday afternoons</li><li class=\"d0\"><b>Eisenhower</b>: took only the Bible on the plane to take command in England</li><li class=\"d0\"><b>General Mark Clark</b>: read his Bible daily during the war</li><li class=\"d0\">Also: <b>Chiang Kai-Shek</b>, <b>General Montgomery</b>, <b>Lord Nelson</b> at Trafalgar, <b>Washington</b>, <b>Robert E. Lee</b>, <b>Stonewall Jackson</b></li><li class=\"d0\"><b>72 million</b> Americans church members \u2014 an all-time record</li></ul>","img":[]},{"t":1990,"lv":2,"h":"Prayer as Energy","b":"<ul><li class=\"d0\"><b>Dr. Alexis Carrel</b> (Nobel Prize, <i>Man the Unknown</i>): &quot;prayer is the most powerful form of energy one can generate... a force as real as gravity&quot;</li><li class=\"d1\">Has seen men lifted out of disease and melancholy by prayer after all other therapy failed</li></ul>","img":[]},{"t":2095,"lv":2,"h":"Admiral Byrd, Alone","b":"<ul><li class=\"d0\"><b>1934</b>: five months alone in a hut under the ice cap of the Ross Barrier, Antarctic</li><li class=\"d1\">Only living creature south of latitude <b>78</b></li><li class=\"d1\">Cold to <b>82 degrees below zero</b></li><li class=\"d1\">Poisoned slowly by carbon monoxide leaking from his stove</li><li class=\"d1\">Nearest help: <b>123 miles</b> away</li><li class=\"d1\">Repeatedly knocked unconscious; couldn&#x27;t eat or sleep; feared he&#x27;d die there</li><li class=\"d0\">Wrote in his diary: &quot;the human race is not alone in the universe... I am not alone&quot;</li><li class=\"d0\">That realization saved him</li><li class=\"d0\">&quot;Few men in their lifetime come anywhere near exhausting the resources dwelling within them&quot;</li></ul>","img":[]},{"t":2249,"lv":2,"h":"Glenn A. Arnold&#x27;s Story (Chillicothe, Illinois \u2014 insurance broker)","b":"<ul><li class=\"d0\"><b>8 years</b> before telling it: locked his door believing it was for the last time</li><li class=\"d0\">Appliance business collapsed; mother dying; wife expecting their second child</li><li class=\"d0\">Mortgaged everything \u2014 car, furniture, even his insurance policies</li><li class=\"d0\">Drove toward the river to end it \u2014 stopped, sat on the ground, wept</li><li class=\"d0\">Decided to give the whole problem to God instead \u2014 prayed hard</li><li class=\"d0\">Peace came; went home and slept like a child</li><li class=\"d0\">Next morning: applied for and got a sales job with confidence</li><li class=\"d0\">Later sold life insurance under &quot;the management of my great guide&quot;</li><li class=\"d0\">Now: bills paid, <b>3 children</b>, owns his home, a new car, <b>$25,000</b> in life insurance</li></ul>","img":[]},{"t":2406,"lv":2,"h":"Why Faith Brings Peace","b":"<ul><li class=\"d0\"><b>William James</b>: turbulent surface billows leave the ocean&#x27;s deep parts undisturbed \u2014 the religious person stays unshakable</li><li class=\"d0\"><b>Immanuel Kant</b>: accept belief in God because we need such a belief</li></ul>","img":[]},{"t":2507,"lv":2,"h":"What Prayer Practically Does","b":"<ul><li class=\"num\"><span>1</span>Puts the problem into words \u2014 hard to solve what stays vague and nebulous</li><li class=\"num\"><span>2</span>Gives a sense of sharing the burden \u2014 tell God what you can&#x27;t tell anyone else</li><li class=\"num\"><span>3</span>Puts into force an active principle of doing \u2014 a first step toward action</li></ul>","img":[]},{"t":2615,"lv":2,"h":"Closing \u2014 The Prayer of St. Francis","b":"<ul><li class=\"d0\">Written <b>700 years ago</b></li><li class=\"d0\">&quot;Lord, make me an instrument of thy peace...&quot;</li><li class=\"d0\">Ends: &quot;it is in giving that we receive, it is in pardoning that we are pardoned, and it is in dying that we are born to eternal life&quot;</li></ul>","img":[]}]},{"n":20,"slug":"ch-20-remember-that-no-one-ever-kicks-a-dead-dog","label":"Chapter 20","title":"Remember That No One Ever Kicks a Dead Dog","audio":"ch-20-remember-that-no-one-ever-kicks-a-dead-dog.mp3","dur":416,"imgs":[],"secs":[{"t":1,"lv":2,"h":"Chapter 20: Remember That No One Ever Kicks a Dead Dog","b":"","img":[]},{"t":1,"lv":2,"h":"Hutchins at Chicago","b":"<ul><li class=\"d0\"><b>1929</b> \u2014 national sensation, educational circles</li><li class=\"d0\"><b>Robert Hutchins</b> \u2014 through Yale as waiter, lumberjack, tutor, clothesline salesman</li><li class=\"d0\">8 years later \u2014 president, University of Chicago, <b>4th richest</b> in America</li><li class=\"d0\">Age <b>30</b></li><li class=\"d0\">Older educators: &quot;young,&quot; &quot;inexperienced,&quot; &quot;cockeyed&quot; \u2014 newspapers joined in</li><li class=\"d0\">Father&#x27;s reply to a shocked friend: no one kicks a <b>dead dog</b></li></ul>","img":[]},{"t":106,"lv":2,"h":"The Principle","b":"<ul><li class=\"d0\">More important the dog, more satisfaction kicking him</li><li class=\"d0\"><b>Prince of Wales</b> (later <b>Edward VIII</b>) \u2014 Dartmouth College, Devonshire, age <b>14</b></li><li class=\"d0\">Found crying \u2014 kicked by the naval cadets</li><li class=\"d0\">Cadets&#x27; confession: wanted to say, once <b>commanders and captains</b>, &quot;I kicked the king&quot;</li><li class=\"d0\">Being kicked/criticized often = the kicker&#x27;s own feeling of importance</li><li class=\"d0\">Often means you&#x27;re <b>accomplishing something</b></li></ul>","img":[]},{"t":164,"lv":2,"h":"The Booth Letter","b":"<ul><li class=\"d0\">Woman&#x27;s letter denounces <b>General William Booth</b>, Salvation Army founder</li><li class=\"d0\">Claim: stole <b>$8 million</b> meant for the poor \u2014 absurd</li><li class=\"d0\">She wanted &quot;mean-spirited gratification,&quot; not truth \u2014 letter to the wastebasket</li><li class=\"d0\"><b>Schopenhauer</b>: vulgar people delight in the faults of great men</li></ul>","img":[]},{"t":219,"lv":2,"h":"Jefferson","b":"<ul><li class=\"d0\">Ex-Yale president <b>Timothy Dwight</b> denounced a man running for President</li><li class=\"d0\">Warning: wives, daughters &quot;victims of legal prostitution&quot;</li><li class=\"d0\">Sounds like Hitler \u2014 was <b>Thomas Jefferson</b>, author, Declaration of Independence</li></ul>","img":[]},{"t":219,"lv":2,"h":"Washington","b":"<ul><li class=\"d0\">Denounced: hypocrite, imposter, &quot;little better than a murderer&quot;</li><li class=\"d0\">Cartoon: on a guillotine</li><li class=\"d0\">Crowds jeered, hissed \u2014 <b>George Washington</b></li></ul>","img":[]},{"t":272,"lv":2,"h":"Admiral Perry","b":"<ul><li class=\"d0\">North Pole by dog sled \u2014 <b>April 6, 1909</b></li><li class=\"d0\">Nearly died \u2014 cold, starvation</li><li class=\"d0\"><b>8 toes</b> frozen, cut off</li><li class=\"d0\">Naval superiors jealous of his publicity \u2014 accused him of loafing in the Arctic</li><li class=\"d0\">Only <b>President McKinley&#x27;s</b> direct order saved his career</li><li class=\"d0\">A desk job draws no envy</li></ul>","img":[]},{"t":323,"lv":2,"h":"General Grant","b":"<ul><li class=\"d0\"><b>1862</b> \u2014 first great Northern victory, won in one afternoon</li><li class=\"d0\">National idol overnight \u2014 bells ringing, bonfires, Maine to the Mississippi</li><li class=\"d0\"><b>Six weeks</b> later \u2014 arrested, army taken from him, wept in despair</li><li class=\"d0\">Cause: jealousy of his arrogant superiors</li></ul>","img":[]},{"t":377,"lv":2,"h":"Rule One","b":"<ul><li class=\"d0\">Unjust criticism is often a <b>disguised compliment</b></li><li class=\"d0\">No one ever kicks a <b>dead dog</b></li></ul>","img":[]}]},{"n":21,"slug":"ch-21-do-this-and-criticism-can-t-hurt-you","label":"Chapter 21","title":"Do This and Criticism Can't Hurt You","audio":"ch-21-do-this-and-criticism-can-t-hurt-you.mp3","dur":531,"imgs":[],"secs":[{"t":1,"lv":2,"h":"Chapter 21: Do This and Criticism Can&#x27;t Hurt You","b":"","img":[]},{"t":1,"lv":2,"h":"Smedley Butler \u2014 &quot;Old Gimlet Eye&quot;","b":"<ul><li class=\"d0\">Colorful, swashbuckling <b>Marine</b> general</li><li class=\"d0\">Young: desperate to be popular, thin-skinned</li><li class=\"d0\"><b>30 years</b> in Marines toughened his hide</li><li class=\"d0\">Called yellow dog, snake, skunk \u2014 cursed by <b>experts</b></li><li class=\"d0\">&quot;Words... bother me. Ha.&quot; \u2014 doesn&#x27;t turn his head anymore</li><li class=\"d0\">Maybe <b>too indifferent</b> \u2014 but most take jibes too seriously</li></ul>","img":[]},{"t":51,"lv":2,"h":"Carnegie&#x27;s own reporter story","b":"<ul><li class=\"d0\"><b>New York Sun</b> reporter lampooned his adult-ed class demo</li><li class=\"d0\">Carnegie <b>burned up</b>, took it personal</li><li class=\"d0\">Phoned <b>Gil Hodges</b>, chairman of Sun&#x27;s executive committee \u2014 demanded a correction</li><li class=\"d0\">Now ashamed of it</li><li class=\"d0\">Half the readers never saw the article</li><li class=\"d0\">Half who saw it \u2192 innocent merriment</li><li class=\"d0\">Half who gloated \u2192 forgot it in a <b>few weeks</b></li><li class=\"d0\">Lesson: people aren&#x27;t thinking about you \u2014 thinking about <b>themselves</b>, before breakfast, after breakfast, till <b>ten past midnight</b></li></ul>","img":[]},{"t":102,"lv":2,"h":"Even Jesus","b":"<ul><li class=\"d0\">Lied about, betrayed \u2014 no <b>self-pity</b></li><li class=\"d0\">One of <b>12</b> closest friends betrayed him for a bribe \u2248 <b>$19</b> in modern money</li><li class=\"d0\">Another denied knowing him <b>three times</b>, swore to it</li><li class=\"d0\"><b>1 in 6</b> \u2014 why expect a better score?</li></ul>","img":[]},{"t":158,"lv":2,"h":"The rule","b":"<ul><li class=\"d0\">Not ignoring <i>all</i> criticism \u2014 only the <b>unjust</b> kind</li><li class=\"d0\">Can&#x27;t stop people criticizing \u2014 can decide whether it <b>disturbs</b> you</li></ul>","img":[]},{"t":213,"lv":2,"h":"Eleanor Roosevelt","b":"<ul><li class=\"d0\">Asked how she handled unjust criticism \u2014 she&#x27;d had <b>plenty</b></li><li class=\"d0\">More ardent friends, more violent enemies than any woman in the White House</li><li class=\"d0\">As a girl: <b>morbidly shy</b>, afraid of criticism</li><li class=\"d0\">Asked her aunt (Theodore Roosevelt&#x27;s sister), &quot;<b>Auntie Bye</b>&quot; \u2014 for advice</li><li class=\"d0\">Auntie Bye: &quot;Never be bothered by what people say <b>as long as you know in your heart you are right</b>&quot;</li><li class=\"d0\">Became her <b>Rock of Gibraltar</b></li><li class=\"d0\">Only way to escape <i>all</i> criticism: be a <b>Dresden china figure</b>, stay on a shelf</li><li class=\"d0\">Damned if you do, damned if you don&#x27;t</li></ul>","img":[]},{"t":266,"lv":2,"h":"Matthew C. Brush (president, American International Corp)","b":"<ul><li class=\"d0\">Very sensitive early on \u2014 wanted every <b>employee</b> to think him perfect</li><li class=\"d0\">Patching up one \u2192 stirred up <b>another</b> (&quot;bumblebees&quot;)</li><li class=\"d0\">Realized: the more he tried to pacify, the more <b>enemies</b> he made</li><li class=\"d0\">Decision: &quot;get your head above the <b>crowd</b>, you&#x27;re going to be criticized \u2014 get used to it&quot;</li><li class=\"d0\">Rule: do the best he could, then put up his <b>old umbrella</b>, let criticism drain off instead of run down his neck</li></ul>","img":[]},{"t":318,"lv":2,"h":"Deems Taylor","b":"<ul><li class=\"d0\">Radio commentator, <b>NY Philharmonic</b> Sunday broadcasts</li><li class=\"d0\">One woman&#x27;s letter: liar, traitor, <b>snake</b>, moron</li><li class=\"d0\">Read her letter <b>on air</b>, to millions</li><li class=\"d0\">She wrote again \u2014 same insults, unaltered</li><li class=\"d0\">Taylor <b>laughed</b> it off publicly \u2014 admired for serenity, poise, humor</li></ul>","img":[]},{"t":368,"lv":2,"h":"Charles Schwab&#x27;s lesson (Princeton speech)","b":"<ul><li class=\"d0\">Old <b>German</b> worker at Schwab&#x27;s steel mill</li><li class=\"d0\">Wartime argument \u2192 other steelworkers <b>threw him in the river</b></li><li class=\"d0\">Came into the office <b>covered in mud and water</b></li><li class=\"d0\">Asked what he&#x27;d said to them: <b>&quot;I just laughed&quot;</b></li><li class=\"d0\">Schwab adopted it as his own <b>motto</b></li></ul>","img":[]},{"t":418,"lv":2,"h":"Lincoln","b":"<ul><li class=\"d0\">Might have broken under <b>Civil War</b> strain answering every attack</li><li class=\"d0\">His words on this became a literary <b>classic</b></li><li class=\"d0\"><b>MacArthur</b> kept a copy above his headquarters desk, during the war</li><li class=\"d0\"><b>Churchill</b> had a framed copy on the wall of his study at <b>Chartwell</b></li><li class=\"d0\">&quot;If I were to read, much less answer, all the attacks... this shop might as well be closed&quot;</li><li class=\"d0\">Does the best he can \u2014 right, criticism won&#x27;t matter; wrong, <b>ten angels swearing</b> he was right wouldn&#x27;t help</li></ul>","img":[]},{"t":476,"lv":2,"h":"Rule 2","b":"<ul><li class=\"num\"><span>1</span>Do the very best you can</li><li class=\"num\"><span>2</span>Put up your old <b>umbrella</b></li><li class=\"num\"><span>3</span>Keep the rain of criticism from running down the back of your <b>neck</b></li></ul>","img":[]}]},{"n":22,"slug":"ch-22-fool-things-i-have-done","label":"Chapter 22","title":"Fool Things I Have Done","audio":"ch-22-fool-things-i-have-done.mp3","dur":692,"imgs":[],"secs":[{"t":0,"lv":2,"h":"The FTD Folder","b":"<ul><li class=\"d0\">Private filing cabinet, folder marked <b>FTD</b> = <i>Fool Things I&#x27;ve Done</i></li><li class=\"d0\">Written records of his own blunders</li><li class=\"d0\">Personal ones written in <b>longhand</b>, not dictated to secretary \u2014 too embarrassing</li><li class=\"d0\">Still recalls self-criticism written <b>15 years</b> ago</li><li class=\"d0\">Quotes <b>King Saul</b>: &quot;played the fool... erred exceedingly&quot;</li></ul>","img":[]},{"t":52,"lv":2,"h":"Blame Himself, Not Others","b":"<ul><li class=\"d0\">Used to blame others \u2014 grown older, wiser, blames <b>himself</b></li><li class=\"d0\"><b>Napoleon</b> at St. Helena: &quot;No one but myself can be blamed for my fall&quot;</li><li class=\"d0\">Introduces <b>H.P. Howell</b> \u2014 artist at self-appraisal and self-management</li></ul>","img":[]},{"t":120,"lv":2,"h":"H.P. Howell&#x27;s System","b":"<ul><li class=\"d0\">Chairman, <b>Commercial National Bank and Trust Co.</b>; director of several corporations</li><li class=\"d0\">Little formal education \u2014 started clerking in a country store</li><li class=\"d0\">Became credit manager, <b>U.S. Steel</b></li><li class=\"d0\">Died suddenly, drugstore of the <b>Hotel Ambassador</b>, New York, <b>July 31, 1944</b> \u2014 Wall Street shocked</li><li class=\"d0\">Kept an <b>engagement book</b> of daily appointments</li><li class=\"d0\">Family never schedules him anything <b>Saturday night</b> \u2014 kept for self-review</li><li class=\"d0\">After dinner, alone, goes through the week&#x27;s interviews and meetings</li><li class=\"d0\">Self-review questions:</li><li class=\"num\"><span>1</span>What mistakes did I make that time?</li><li class=\"num\"><span>2</span>What did I do that was right \u2014 how could I have improved?</li><li class=\"num\"><span>3</span>What lesson can I learn from that experience?</li><li class=\"d0\">Sometimes leaves him <b>unhappy</b>, astonished at his own blunders</li><li class=\"d0\">Blunders <b>grew less frequent</b> over the years</li><li class=\"d0\">Calls it the thing that&#x27;s done more for him than anything else he&#x27;s ever attempted</li></ul>","img":[]},{"t":173,"lv":2,"h":"Ben Franklin&#x27;s Version","b":"<ul><li class=\"d0\">Maybe Howell borrowed the idea \u2014 but Franklin didn&#x27;t wait for Saturday</li><li class=\"d0\">Reviewed himself <b>every night</b></li><li class=\"d0\">Found <b>13 serious faults</b></li><li class=\"d1\">wasting time stewing over trifles</li><li class=\"d1\">arguing and contradicting people</li><li class=\"d0\">Fought <b>one fault per week</b></li><li class=\"d0\">Kept a record of who won each day&#x27;s &quot;slugging match&quot;</li><li class=\"d0\">New week, new fault \u2014 &quot;put on the gloves&quot;</li><li class=\"d0\">Kept it up <b>more than two years</b></li><li class=\"d0\">Became one of the best loved, most influential men the nation produced</li></ul>","img":[]},{"t":231,"lv":2,"h":"On Being a Fool","b":"<ul><li class=\"d0\"><b>Elbert Hubbard</b>: every man&#x27;s a fool for at least <b>five minutes</b> a day \u2014 wisdom is not exceeding the limit</li><li class=\"d0\">Small man rages at criticism; wise man learns from those who reprove him</li><li class=\"d0\"><b>Walt Whitman</b>: the great lessons come from those who <b>rejected</b> you, not those who admired you</li></ul>","img":[]},{"t":288,"lv":2,"h":"Beat Your Critics To It","b":"<ul><li class=\"d0\">Be your <b>own</b> most severe critic \u2014 find and fix the weaknesses first</li><li class=\"d0\"><b>Charles Darwin</b> \u2014 spent <b>15 years</b> checking data, challenging reasoning, criticizing his own conclusions before publishing <i>The Origin of Species</i>, knowing it would rock the intellectual and religious world</li></ul>","img":[]},{"t":340,"lv":2,"h":"Lincoln and Stanton","b":"<ul><li class=\"d0\"><b>Edward M. Stanton</b>, Lincoln&#x27;s Secretary of War, called him &quot;<b>a damned fool</b>&quot;</li><li class=\"d0\">Lincoln had signed an order transferring regiments to please a politician</li><li class=\"d0\">Stanton refused to carry it out</li><li class=\"d0\">Lincoln&#x27;s reply: &quot;If Stanton said I am a damned fool, then I must be, for he is nearly always right. I&#x27;ll just step over and see for myself.&quot;</li><li class=\"d0\">Went to Stanton \u2014 was convinced the order was wrong \u2014 <b>withdrew it</b></li><li class=\"d0\">Welcomed criticism when sincere, informed, and given to help</li></ul>","img":[]},{"t":394,"lv":2,"h":"Nobody&#x27;s Right Very Often","b":"<ul><li class=\"d0\"><b>Theodore Roosevelt</b> \u2014 hoped to be right <b>three times out of four</b> in the White House</li><li class=\"d0\"><b>Einstein</b> \u2014 confessed his conclusions wrong <b>99%</b> of the time</li><li class=\"d0\"><b>La Rochefoucauld</b>: our enemies&#x27; opinions come nearer the truth about us than our own</li></ul>","img":[]},{"t":447,"lv":2,"h":"Why We Resist","b":"<ul><li class=\"d0\">Resent criticism, lap up praise \u2014 whether either is deserved</li><li class=\"d0\">Not creatures of logic \u2014 creatures of <b>emotion</b></li><li class=\"d0\">Logic like a <b>birch bark canoe</b> tossed on a dark, stormy sea of emotion</li></ul>","img":[]},{"t":498,"lv":2,"h":"The Disarming Move","b":"<ul><li class=\"d0\">Don&#x27;t defend yourself \u2014 every fool does that</li><li class=\"d0\">Say instead: if my critic knew all my other faults, he&#x27;d have criticized me far worse</li><li class=\"d0\">Facing unjust criticism: &quot;I am far from perfect. If Einstein is wrong 99% of the time, maybe I&#x27;m wrong <b>80%</b>. Maybe I deserve this.&quot;</li></ul>","img":[]},{"t":498,"lv":2,"h":"Asking For It","b":"<ul><li class=\"d0\"><b>Charles Luckman</b>, former president, <b>Pepsodent Company</b> \u2014 spent <b>$1,000,000 a year</b> putting Bob Hope on the air</li><li class=\"d0\">Skipped the letters praising the program \u2014 read only the <b>critical</b> ones</li><li class=\"d0\"><b>Ford Motor Company</b> polled its own employees, invited them to criticize the company</li></ul>","img":[]},{"t":550,"lv":2,"h":"The Soap Salesman","b":"<ul><li class=\"d0\">Started selling soap for <b>Colgate</b>, orders slow, feared losing his job</li><li class=\"d0\">Knew the soap and price weren&#x27;t the problem \u2014 must be <b>himself</b></li><li class=\"d0\">After a lost sale, walked around the block asking what went wrong \u2014 too vague? lacked enthusiasm?</li><li class=\"d0\">Went back to the merchant: &quot;I&#x27;ve come back to get your advice and criticism... be frank, don&#x27;t pull your punches&quot;</li><li class=\"d0\">Won friends, priceless advice</li><li class=\"d0\">Rose to <b>president of Colgate-Palmolive-Peet Soap Company</b></li><li class=\"d0\">His name: <b>E.H. Little</b></li></ul>","img":[]},{"t":604,"lv":2,"h":"Rule 3","b":"<ul><li class=\"d0\">Keep a record of the fool things we&#x27;ve done \u2014 criticize ourselves</li><li class=\"d0\">Since we can&#x27;t hope to be perfect \u2014 ask for <b>unbiased, helpful, constructive</b> criticism, like E.H. Little did</li></ul>","img":[]},{"t":604,"lv":2,"h":"Part 6 Recap \u2014 How to Keep from Worrying About Criticism","b":"<ul><li class=\"num\"><span>1</span>Unjust criticism is often a <b>disguised compliment</b> \u2014 means you&#x27;ve aroused jealousy and envy \u2014 &quot;no one ever kicks a <b>dead dog</b>&quot;</li><li class=\"num\"><span>2</span>Do the very best you can, then put up your old <b>umbrella</b> and keep the rain of criticism from running down your neck</li><li class=\"num\"><span>3</span>Keep a record of the fool things we&#x27;ve done and criticize ourselves \u2014 ask for <b>unbiased, helpful, constructive</b> criticism</li></ul>","img":[]}]},{"n":23,"slug":"ch-23-how-to-add-one-hour-a-day-to-your-waking-life","label":"Chapter 23","title":"How to Add One Hour a Day to Your Waking Life","audio":"ch-23-how-to-add-one-hour-a-day-to-your-waking-life.mp3","dur":601,"imgs":[],"secs":[{"t":1,"lv":2,"h":"Dale Carnegie \u2014 How to Stop Worrying and Start Living","b":"","img":[]},{"t":1,"lv":3,"h":"Chapter 23: How to Add One Hour a Day to Your Waking Life","b":"","img":[]},{"t":1,"lv":2,"h":"Why fatigue matters","b":"<ul><li class=\"d0\"><b>Fatigue</b> produces worry, lowers resistance to fear \u2014 prevent fatigue, prevent worry</li><li class=\"d0\">Dr. Edmund Jacobson (<i>Progressive Relaxation</i>, <i>You Must Relax</i>): no nervous or emotional state survives <b>complete relaxation</b></li><li class=\"d0\">Rule: <b>rest before you get tired</b> \u2014 fatigue builds fast</li></ul>","img":[]},{"t":104,"lv":2,"h":"The army &amp; the heart","b":"<ul><li class=\"d0\">Soldiers march farther, hold up longer \u2014 <b>rest 10 min</b> every hour, forced by the army</li><li class=\"d0\">Heart pumps enough blood daily to fill a <b>railway tank car</b>; shovels energy-equivalent of <b>20 tons of coal</b> onto a 3-ft platform, every 24 hrs, for <b>50\u201390 years</b></li><li class=\"d0\">Dr. Walter B. Cannon (Harvard): heart rests after every contraction \u2014 at 70 beats/min, works only <b>9 of 24 hrs</b>, rests <b>15</b></li></ul>","img":[]},{"t":265,"lv":2,"h":"Famous nappers","b":"<ul><li class=\"d0\"><b>Churchill</b>, WWII: <b>16-hr</b> days for years \u2014 bed till <b>11am</b>, hour&#x27;s nap after lunch, <b>2-hr</b> sleep before 8pm dinner</li><li class=\"d0\"><b>Rockefeller</b>: greatest fortune of his day, lived to <b>98</b> \u2014 <b>half-hour nap</b> on his office couch every noon; not even the President could reach him</li><li class=\"d0\">Daniel Josselyn, <i>Why Be Tired</i>: rest is <b>repair</b> \u2014 even <b>5 min</b> forestalls fatigue</li><li class=\"d0\"><b>Connie Mack</b>: no nap \u2192 dead by the 5th inning; <b>5-min nap</b> \u2192 full doubleheader</li><li class=\"d0\"><b>Eleanor Roosevelt</b>: <b>20 min</b>, eyes closed, before any crowd or speech</li><li class=\"d0\"><b>Gene Autry</b>: army cot in his Madison Square Garden dressing room \u2014 hour&#x27;s nap between shows; in Hollywood, 2\u20133 <b>10-min naps</b>/day</li><li class=\"d0\"><b>Henry Ford</b>, near 80: never stands when he can sit, never sits when he can lie down</li><li class=\"d0\"><b>Jack Chertock</b> (MGM): nothing worked till he took conferences stretched on his couch \u2014 2 yrs later, &quot;a miracle,&quot; works <b>2 hrs a day longer</b></li></ul>","img":[]},{"t":422,"lv":2,"h":"For everyone else","b":"<ul><li class=\"d0\">Can&#x27;t nap at a desk? Home for lunch \u2192 <b>10-min nap</b>, as <b>Gen. George C. Marshall</b> did directing the wartime army</li><li class=\"d0\">Over 50, too rushed? Buy all the life insurance you can get \u2014 funerals come high and suddenly</li><li class=\"d0\">Can&#x27;t nap at noon \u2192 <b>hour before dinner</b>, cheaper than a cocktail, <b>5,467 times</b> more effective</li><li class=\"d0\">Nap + <b>6 hrs</b> sleep = <b>7 hrs</b>, beats <b>8 hrs</b> unbroken</li></ul>","img":[]},{"t":481,"lv":2,"h":"Taylor&#x27;s Schmidt, Bethlehem Steel","b":"<ul><li class=\"d0\">Men loading <b>12\u00bd tons</b> pig iron/day, exhausted by noon \u2014 Taylor: could load <b>47 tons</b>, nearly <b>4x</b></li><li class=\"d0\"><b>Schmidt</b>, worked by stopwatch:</li><li class=\"num\"><span>1</span>Pick up a pig and walk</li><li class=\"num\"><span>2</span>Sit down and rest</li><li class=\"num\"><span>3</span>Walk</li><li class=\"num\"><span>4</span>Rest</li><li class=\"d0\"><b>47 tons a day</b>, held <b>3 years</b> straight</li><li class=\"d0\"><b>26 min</b> work, <b>34 min</b> rest, per hour \u2014 did almost <b>4x</b> the work</li><li class=\"d0\">Source: <i>Principles of Scientific Management</i>, pages <b>41\u201362</b></li></ul>","img":[]},{"t":587,"lv":2,"h":"Takeaway","b":"<ul><li class=\"d0\">Army: rest often. Heart: rest before tired.</li><li class=\"d0\">Result: <b>one hour</b> added to your waking life</li></ul>","img":[]}]},{"n":24,"slug":"ch-24-what-makes-you-tired-and-what-you-can-do-about-it","label":"Chapter 24","title":"What Makes You Tired \u2014 and What You Can Do About It","audio":"ch-24-what-makes-you-tired-and-what-you-can-do-about-it.mp3","dur":593,"imgs":[],"secs":[{"t":1,"lv":2,"h":"Chapter 24 \u2014 What Makes You Tired and What You Can Do About It","b":"","img":[]},{"t":1,"lv":2,"h":"The brain never tires","b":"<ul><li class=\"d0\">Scientists tested how long the brain works before <b>fatigue</b></li><li class=\"d0\">Day laborer&#x27;s blood: full of fatigue toxins. A drop from <b>Einstein&#x27;s</b>: none</li><li class=\"d0\">8 to 12 hours in, still fast as the start \u2014 brain is <b>utterly tireless</b></li></ul>","img":[]},{"t":60,"lv":2,"h":"So what tires you?","b":"<ul><li class=\"d0\">Psychiatrists: fatigue is <b>mental and emotional</b>, not physical</li><li class=\"d0\"><b>A.J. Hadfield</b> (England), <i>The Psychology of Power</i> \u2014 mostly mental; pure physical exhaustion <b>rare</b></li><li class=\"d0\"><b>Dr. A.A. Brill</b> (America) \u2014 <b>100%</b> of a sedentary worker&#x27;s fatigue is psychological</li><li class=\"d0\">Tiring emotions: <b>boredom</b>, resentment, feeling unappreciated, futility, hurry, anxiety, worry</li></ul>","img":[]},{"t":111,"lv":2,"h":"Tension does the damage","b":"<ul><li class=\"d0\"><b>Metropolitan Life Insurance Co.</b> leaflet \u2014 hard work alone rarely causes fatigue</li><li class=\"d0\">Worry, tenseness, emotional upset \u2014 the <b>three</b> biggest causes</li><li class=\"d0\">A <b>tense muscle is a working muscle</b></li><li class=\"d0\">Self-checkup: scowling? shoulders hunched? face tight? \u2014 should be limp as an <b>old rag doll</b></li><li class=\"d0\">Cause: belief that effort itself is required (<b>Daniel W. Josselyn</b>)</li><li class=\"d1\">squandering energy like <b>seven drunken sailors in Singapore</b></li></ul>","img":[]},{"t":221,"lv":2,"h":"The cure is relaxation","b":"<ul><li class=\"d0\"><b>William James</b>, <i>The Gospel of Relaxation</i> \u2014 American over-tension is just a <b>bad habit</b></li><li class=\"d0\">Tension is a habit, relaxing is a habit \u2014 both can be broken, formed</li><li class=\"d0\">Relaxation begins with the <b>muscles</b>, never the mind</li></ul>","img":[]},{"t":331,"lv":3,"h":"The eye exercise","b":"<ul><li class=\"d0\">Close the eyes, repeat <b>&quot;let go&quot;</b> slowly, one minute</li><li class=\"d0\">Same for jaw, face, neck, shoulders \u2014 eyes matter most</li><li class=\"d0\"><b>Dr. Edmund Jacobson</b> (Univ. of Chicago) \u2014 relax eyes fully, forget your troubles</li><li class=\"d0\">Eyes burn <b>one-fourth</b> of the body&#x27;s nervous energy</li></ul>","img":[]},{"t":383,"lv":2,"h":"The crumpled sock","b":"<ul><li class=\"d0\"><b>Vicki Baum</b>, the novelist \u2014 childhood fall, an old circus clown: &quot;limp as an <b>old crumpled sock</b>&quot;</li><li class=\"d0\">Taught the children to fall, flip-flop, somersault</li></ul>","img":[]},{"t":434,"lv":2,"h":"Galli-Curci before the curtain","b":"<ul><li class=\"d0\"><b>Helen Jepson</b> told Carnegie \u2014 soprano sat before performances, muscles slack, jaw <b>sagging</b>, nerves and fatigue both kept off</li></ul>","img":[]},{"t":484,"lv":2,"h":"Four rules for relaxing","b":"<ul><li class=\"num\"><span>1</span>Relax in odd moments \u2014 limp like an old sock</li><li class=\"d1\">Carnegie&#x27;s own <b>maroon</b> sock, kept on his desk</li><li class=\"d1\">no sock? study a <b>cat</b> \u2014 sunning kitten sags like a wet newspaper, say the <b>yogis of India</b> \u2014 no tired cat, no ulcers</li><li class=\"num\"><span>2</span>Work in a <b>comfortable position</b> \u2014 tension means aching shoulders, fatigue</li><li class=\"num\"><span>3</span>Check yourself <b>four or five times a day</b> \u2014 &quot;Am I making this harder than it is?&quot;</li><li class=\"d1\"><b>Dr. David Harold Fink</b> \u2014 it&#x27;s <b>habits two to one</b></li><li class=\"num\"><span>4</span>Test at day&#x27;s end \u2014 &quot;just how tired am I?&quot;</li></ul>","img":[]},{"t":535,"lv":2,"h":"The real measure","b":"<ul><li class=\"d0\"><b>Daniel W. Josselyn</b> \u2014 measures the day by how tired he is <b>not</b></li><li class=\"d0\">Tired, irritable at the close \u2014 an <b>inefficient</b> day</li><li class=\"d0\">If businessmen learned this \u2014 <b>hypertension</b> deaths would drop overnight</li><li class=\"d0\">Sanitariums, asylums would stop filling with people broken by <b>fatigue and worry</b></li></ul>","img":[]}]},{"n":25,"slug":"ch-25-how-to-avoid-fatigue-and-keep-looking-young","label":"Chapter 25","title":"How to Avoid Fatigue and Keep Looking Young","audio":"ch-25-how-to-avoid-fatigue-and-keep-looking-young.mp3","dur":634,"imgs":[],"secs":[{"t":1,"lv":2,"h":"Chapter 25: How to Avoid Fatigue and Keep Looking Young","b":"","img":[]},{"t":52,"lv":2,"h":"The Boston Dispensary Class","b":"<ul><li class=\"d0\">Meets once a week, <b>Boston Dispensary</b> \u2014 full medical exam before admission</li><li class=\"d0\">Officially &quot;Class in <b>Applied Psychology</b>,&quot; formerly <b>Thought Control</b> class</li><li class=\"d0\">Purpose: people ill from <b>worry</b>, many <b>housewives</b></li><li class=\"d0\"><b>1930</b> \u2014 Dr. <b>Joseph H. Pratt</b>, pupil of Sir <b>William Osler</b></li><li class=\"d1\">Outpatients with no physical cause, full symptoms \u2014 <b>arthritic hands</b>, agony of <b>stomach cancer</b>, chronic tiredness</li><li class=\"d1\">Old doctors: &quot;all imagination&quot; \u2014 opened class despite doubters \u2014 <b>thousands</b> cured since</li></ul>","img":[]},{"t":157,"lv":2,"h":"The Nine-Year Patient","b":"<ul><li class=\"d0\">Attending <b>more than nine years</b>, faithful &quot;as going to church&quot;</li><li class=\"d0\">Once convinced: <b>floating kidney</b>, heart ailment, <b>spells of blindness</b> from tension</li><li class=\"d0\">Now looks about <b>40</b> \u2014 holding a <b>grandchild</b> asleep in her lap</li><li class=\"d0\">&quot;I used to worry so much... I wished I could die&quot; \u2014 learned the <b>futility of worrying</b>, life now &quot;serene&quot;</li></ul>","img":[]},{"t":261,"lv":2,"h":"Catharsis \u2014 Talking It Out","b":"<ul><li class=\"d0\">Dr. <b>Rose Hilverding</b>, medical adviser: talk troubles over with someone you <b>trust</b> \u2014 she calls it <b>catharsis</b></li><li class=\"d0\">Brooding alone \u2192 nervous tension</li><li class=\"d0\">Woman &quot;like a <b>wound-up spring</b>&quot; \u2014 talked, calmed, ended smiling \u2014 problem unsolved, but relief came anyway</li><li class=\"d0\">Healing power of <b>words</b> \u2014 basis of <b>psychoanalysis</b>, since <b>Freud</b></li><li class=\"d0\">How: pick one trusted person \u2014 relative, doctor, lawyer, <b>minister or priest</b> \u2014 make an appointment, ask them just to listen</li></ul>","img":[]},{"t":317,"lv":2,"h":"Five Things to Do at Home","b":"<ul><li class=\"num\"><span>1</span>Keep a <b>notebook or scrapbook</b> \u2014 paste in poems, prayers, quotations \u2014 &quot;spiritual shot in the arm&quot;</li><li class=\"num\"><span>2</span>Don&#x27;t dwell on others&#x27; <b>shortcomings</b> \u2014 nagging wife asked &quot;what would you do if your husband <b>died</b>?&quot; \u2014 shocked into listing his good points</li><li class=\"num\"><span>3</span>Get <b>interested in people</b> \u2014 lonely woman told to invent stories about strangers on the <b>bus</b> \u2014 now happy, alert, cured of her pains</li><li class=\"num\"><span>4</span>Make a <b>schedule</b> for tomorrow&#x27;s work before bed \u2014 cures being &quot;chased by the clock&quot; \u2014 more work done, less fatigue</li><li class=\"num\"><span>5</span>Avoid <b>tension and fatigue</b>, relax, relax \u2014 nothing ages looks faster</li></ul>","img":[]},{"t":477,"lv":2,"h":"Relaxation at the Clinic","b":"<ul><li class=\"d0\"><b>Professor Paul E. Johnson</b>, director \u2014 reviewed relaxing rules from previous chapter</li><li class=\"d0\"><b>10 minutes</b> of exercises \u2014 assistant nearly asleep sitting upright</li><li class=\"d0\">A <b>hard floor</b> beats an innerspring bed \u2014 more resistance, good for the spine</li></ul>","img":[]},{"t":527,"lv":3,"h":"Exercises for a week","b":"<ul><li class=\"d0\">A. Lie flat on floor \u2014 stretch tall \u2014 roll around \u2014 twice a day</li><li class=\"d0\">B. Close eyes \u2014 &quot;the sun is shining... sky is blue and sparkling... nature is calm&quot; \u2014 or pray</li><li class=\"d0\">C. No time to lie down? Sit in a hard chair like a seated <b>Egyptian statue</b>, palms down on thighs</li><li class=\"d0\">D. Tense toes, release \u2014 up through legs to the neck \u2014 head rolls &quot;as though a football&quot; \u2014 &quot;<b>let go, let go</b>&quot;</li><li class=\"d0\">E. Slow deep <b>breathing</b> \u2014 the <b>yogis of India</b> \u2014 soothes the nerves</li><li class=\"d0\">F. Picture the wrinkles and frowns, smooth them out \u2014 <b>twice a day</b> \u2014 &quot;lines disappear from the inside out&quot;</li></ul>","img":[]}]},{"n":26,"slug":"ch-26-four-good-working-habits-that-will-help-prevent-fatigue-and-worry","label":"Chapter 26","title":"Four Good Working Habits That Will Help Prevent Fatigue and Worry","audio":"ch-26-four-good-working-habits-that-will-help-prevent-fatigue-and-worry.mp3","dur":573,"imgs":[],"secs":[{"t":1,"lv":2,"h":"The Four Good Working Habits","b":"<ul><li class=\"num\"><span>1</span><b>Clear your desk</b> of all papers except those relating to the immediate problem at hand</li><li class=\"num\"><span>2</span><b>Do things</b> in the order of their importance</li><li class=\"num\"><span>3</span>When you have the facts \u2014 <b>solve it then and there</b>, don&#x27;t put off the decision</li><li class=\"num\"><span>4</span>Learn to <b>organize, deputize and supervise</b></li></ul>","img":[]},{"t":1,"lv":2,"h":"Habit One \u2014 Clear the Desk","b":"<ul><li class=\"d0\"><b>Roland L. Williams</b>, pres. <b>Chicago &amp; Northwestern Railway</b> \u2014 clear desk of all but the immediate problem: &quot;<b>Good Housekeeping</b>&quot;</li><li class=\"d0\"><b>Library of Congress</b>, Washington D.C. \u2014 five words on the ceiling, poet <b>Pope</b>: &quot;<b>Order is heaven&#x27;s first law</b>&quot;</li><li class=\"d0\"><b>New Orleans</b> publisher&#x27;s secretary cleared a desk \u2014 found a <b>typewriter missing two years</b></li><li class=\"d0\">Dr. <b>John H. Stokes</b>, U. of Pennsylvania, paper to the <b>AMA</b> \u2014 11 warning signs in a patient&#x27;s mind</li><li class=\"d1\">#1: <b>&quot;the sense of must&quot;</b> \u2014 an unending stretch of things to do</li><li class=\"d0\">Dr. <b>William L. Sadler</b> \u2014 patient: Chicago exec, tense, near a <b>nervous breakdown</b></li><li class=\"d1\">settles each interruption <b>on the spot</b>; drawers <b>empty</b> \u2014 unfinished business? <b>&quot;Finished.&quot;</b> unanswered mail? <b>&quot;Answered.&quot;</b></li><li class=\"d1\"><b>six weeks later</b> \u2014 had <b>three desks, two offices</b>, now <b>one desk</b>, <b>fully recovered</b></li><li class=\"d0\"><b>Charles Evans Hughes</b>, former Chief Justice, U.S. Supreme Court \u2014 &quot;Men do not die from overwork. They die from <b>dissipation and worry</b>.&quot;</li></ul>","img":[]},{"t":317,"lv":2,"h":"Habit Two \u2014 Order of Importance","b":"<ul><li class=\"d0\"><b>Henry L. Doherty</b>, founder <b>Cities Service Co.</b> \u2014 two abilities almost impossible to find: to <b>think</b>, to do things <b>in order of importance</b></li><li class=\"d0\"><b>Charles Luckman</b> \u2014 12 years to president of <b>Pepsodent</b>, salary <b>$100,000/yr</b>, made <b>a million dollars</b> besides; up at <b>5 a.m.</b></li><li class=\"d0\"><b>Frank Bettger</b>, insurance salesman \u2014 plans the night before, sets a <b>daily goal</b>; miss it, rolls to next day</li><li class=\"d0\"><b>George Bernard Shaw</b> \u2014 <b>5 pages a day</b>, <b>9 years</b>, earned only <b>$30</b> \u2014 about <b>a penny a day</b></li><li class=\"d0\"><b>Robinson Crusoe</b> \u2014 schedule for <b>every hour</b> of the day</li></ul>","img":[]},{"t":423,"lv":2,"h":"Habit Three \u2014 Decide On the Spot","b":"<ul><li class=\"d0\"><b>H.P. Howell</b>, Carnegie&#x27;s former student, board member, <b>U.S. Steel</b> \u2014 meetings long, <b>few decisions</b>, members hauled reports home</li><li class=\"d1\">persuaded the board: <b>one problem at a time</b>, decide before moving on</li><li class=\"d1\">result: <b>docket cleared</b>, no more unresolved problems</li></ul>","img":[]},{"t":526,"lv":2,"h":"Habit Four \u2014 Organize, Deputize, Supervise","b":"<ul><li class=\"d0\">won&#x27;t delegate \u2192 <b>premature graves</b></li><li class=\"d0\">hard for Carnegie too \u2014 &quot;<b>awfully hard</b>&quot;</li><li class=\"d0\">danger both ways: hoard it, or delegate to the <b>wrong people</b></li><li class=\"d0\">never learn it \u2192 <b>heart trouble in their 50s or early 60s</b></li><li class=\"d0\">check the <b>death notices</b> in your local paper</li></ul>","img":[]}]},{"n":27,"slug":"ch-27-how-to-banish-the-boredom-that-produces-fatigue-worry-and-resentment","label":"Chapter 27","title":"How to Banish the Boredom That Produces Fatigue, Worry, and Resentment","audio":"ch-27-how-to-banish-the-boredom-that-produces-fatigue-worry-and-resentment.mp3","dur":1082,"imgs":[],"secs":[{"t":1,"lv":2,"h":"Boredom causes fatigue, not work","b":"","img":[]},{"t":1,"lv":3,"h":"Alice&#x27;s story","b":"<ul><li class=\"d0\"><b>Alice</b>, executive, home <b>utterly exhausted</b> one night</li><li class=\"d1\">Headache, backache, skipped dinner, wanted bed</li><li class=\"d1\">Phone rings \u2014 boyfriend, dance invitation</li><li class=\"d1\">Eyes sparkle \u2014 danced till <b>3 o&#x27;clock in the morning</b> in her Alice blue gown</li><li class=\"d1\">Came home <b>not tired at all</b>, too exhilarated to sleep</li><li class=\"d0\">Exhausted 8 hours earlier not from work \u2014 from <b>boredom</b>, maybe with life itself</li><li class=\"d0\">&quot;Millions of Alices&quot;</li></ul>","img":[]},{"t":53,"lv":3,"h":"Attitude beats exertion","b":"<ul><li class=\"d0\"><b>Dr. Joseph E. Barmak</b>, <i>Archives of Psychology</i></li><li class=\"d1\">Students tested on deliberately boring tasks</li><li class=\"d1\">Tired, sleepy, headaches, eye strain, irritable, some upset stomachs</li><li class=\"d1\">Confirmed by <b>metabolism tests</b>: blood pressure, oxygen use <b>drop</b> when bored, jump back up with interest</li></ul>","img":[]},{"t":106,"lv":3,"h":"Carnegie&#x27;s own test \u2014 Canadian Rockies","b":"<ul><li class=\"d0\">Lake Louise, trout fishing on <b>Coral Creek</b>, <b>8 hours</b>, brush over his head</li><li class=\"d0\">Excited, not exhausted \u2014 <b>six cutthroat trout</b>, altitude <b>7,000 ft</b></li><li class=\"d0\">Boredom, not the climb, would have worn him out</li></ul>","img":[]},{"t":156,"lv":3,"h":"Climbers vs. guides \u2014 S.H. Kingman","b":"<ul><li class=\"d0\">Kingman, president, Farmers and Mechanics Savings Bank, <b>Minneapolis</b></li><li class=\"d0\"><b>July 1953</b> \u2014 Canadian Alpine Club trains the Prince of Wales Rangers</li><li class=\"d0\">Guides aged <b>42 to 59</b>; glaciers, snow fields, a <b>40-ft</b> roped cliff; <b>Michael&#x27;s Peak</b>, <b>Vice President Peak</b>, Little Yoho Valley</li><li class=\"d0\">After <b>15 hours</b>:</li><li class=\"d1\">Soldiers, fresh off <b>six weeks</b> commando training \u2014 exhausted, asleep before eating</li><li class=\"d1\">Guides, <b>two to three times</b> their age \u2014 tired, not exhausted; ate, talked for hours</li><li class=\"d1\">Soldiers <b>bored</b>; guides <b>interested</b></li></ul>","img":[]},{"t":269,"lv":3,"h":"Thorndike","b":"<ul><li class=\"d0\"><b>Dr. Edward Thorndike</b>, Columbia \u2014 kept young men awake almost <b>a week</b> by keeping them interested</li><li class=\"d0\">&quot;<b>Boredom</b> is the only real cause of diminution of work&quot;</li></ul>","img":[]},{"t":269,"lv":3,"h":"The mental worker","b":"<ul><li class=\"d0\">Bad day of interruptions \u2014 nothing done, home exhausted, splitting headache</li><li class=\"d0\">Next day, everything clicks \u2014 <b>40 times</b> the work, home &quot;fresh as a snowy white gardenia&quot;</li></ul>","img":[]},{"t":321,"lv":2,"h":"Fatigue is worry and resentment, not labor","b":"<ul><li class=\"d0\">Revival of Jerome Kern&#x27;s <b>Showboat</b> \u2014 Captain Andy of the <i>Cotton Blossom</i>: the <b>lucky</b> ones do what they enjoy</li><li class=\"d0\">Walking <b>10 blocks</b> with a nagging spouse can tire more than <b>10 miles</b> with an adoring sweetheart</li></ul>","img":[]},{"t":372,"lv":3,"h":"The stenographer&#x27;s private contest \u2014 Tulsa oil company","b":"<ul><li class=\"d0\">Dullest job imaginable \u2014 oil-lease forms, columns of figures</li><li class=\"d0\"><b>Daily contest with herself</b>:</li><li class=\"num\"><span>1</span>Count forms filled each morning</li><li class=\"num\"><span>2</span>Beat that record by afternoon</li><li class=\"num\"><span>3</span>Beat the day&#x27;s total tomorrow</li><li class=\"d0\">Became the <b>fastest</b> in her division \u2014 no praise, no raise, no promotion, but no fatigue</li><li class=\"d0\">She is <b>Carnegie&#x27;s own wife</b></li></ul>","img":[]},{"t":477,"lv":3,"h":"&quot;Act as if&quot; \u2014 Ms. Vallie G. Golden, Elmhurst, Illinois","b":"<ul><li class=\"d0\">One of four stenographers; ordered to <b>retype</b> a letter \u2014 started to rebel</li><li class=\"d0\">Caught herself: others would want her job; she&#x27;s <b>paid</b> to do it</li><li class=\"d0\">Decided to act <b>as if</b> she enjoyed it \u2014 came to enjoy it some, worked <b>faster</b>, no more overtime</li><li class=\"d0\">Reputation as good worker \u2192 made <b>private secretary</b></li><li class=\"d0\">Source: <b>Professor Hans Vaihinger</b>&#x27;s &quot;as if&quot; philosophy</li></ul>","img":[]},{"t":591,"lv":3,"h":"Harlan A. Howard \u2014 ice cream to the lab","b":"<ul><li class=\"d0\">High-school job dishing ice cream, <b>despised</b> it</li><li class=\"d0\">Resolved to <b>study ice cream</b> chemistry instead</li><li class=\"d0\">Chemistry whiz \u2192 <b>Massachusetts State College</b>, food technology</li><li class=\"d0\">Won <b>$100</b>, New York Cocoa Exchange essay prize on cocoa and chocolate</li><li class=\"d0\">Private lab in his basement, <b>Amherst, Massachusetts</b></li><li class=\"d0\">New law required milk bacteria counts \u2014 counted for <b>14 milk companies</b>, hired <b>two assistants</b></li><li class=\"d0\">Forecast: leader in 25 years, while old classmates sit <b>sour, unemployed</b>, blaming the government</li></ul>","img":[]},{"t":696,"lv":3,"h":"Sam (Samuel Vauclain) \u2014 the lathe race","b":"<ul><li class=\"d0\">Bored turning bolts, ready to quit</li><li class=\"d0\">Raced the mechanic at the next machine, switching jobs and machines, comparing totals</li><li class=\"d0\">Foreman noticed speed and accuracy, promoted him</li><li class=\"d0\"><b>30 years later</b> \u2014 president of the <b>Baldwin Locomotive Works</b></li></ul>","img":[]},{"t":751,"lv":3,"h":"H.V. Kaltenborn \u2014 selling in Paris","b":"<ul><li class=\"d0\">Age <b>22</b> \u2014 crossed the Atlantic on a cattle boat, watering steers; arrived in Paris <b>hungry and broke</b></li><li class=\"d0\">Pawned his camera for <b>$5</b>; ad in the Paris <b>New York Herald</b></li><li class=\"d0\">Sold <b>stereopticon</b> machines door to door \u2014 no French; sales talk memorized, a copy pasted inside his <b>hat</b></li><li class=\"d0\">Earned <b>$5,000</b> in commissions his first year \u2014 among France&#x27;s highest-paid salesmen</li><li class=\"d0\">Daily mirror pep talk: &quot;you have to do this if you want to eat&quot;</li><li class=\"d0\">Advice to young men: <b>&quot;go to bat with yourself&quot;</b> every morning</li></ul>","img":[]},{"t":966,"lv":2,"h":"The close","b":"<ul><li class=\"d0\">Marcus Aurelius, <b>18 centuries</b> ago: &quot;Our life is what our thoughts make it&quot;</li><li class=\"d0\">Direct your own thoughts toward courage, happiness, gratitude</li><li class=\"d0\">Interest in your work can <b>double</b> your happiness, ease worry, and bring promotion \u2014 at minimum, it cuts fatigue and sweetens your leisure</li></ul>","img":[]}]},{"n":28,"slug":"ch-28-how-to-keep-from-worrying-about-insomnia","label":"Chapter 28","title":"How to Keep from Worrying About Insomnia","audio":"ch-28-how-to-keep-from-worrying-about-insomnia.mp3","dur":843,"imgs":[],"secs":[{"t":0,"lv":2,"h":"Chapter 28: How to Keep from Worrying About Insomnia","b":"","img":[]},{"t":53,"lv":2,"h":"Samuel Untermyer \u2014 never slept, never suffered for it","b":"<ul><li class=\"d0\">Famous <b>international lawyer</b> \u2014 never one decent night&#x27;s sleep</li><li class=\"d0\">College: worried over <b>asthma</b>, <b>insomnia</b> \u2014 stopped fighting it, <b>got up and studied</b></li><li class=\"d1\">Prodigy, <b>College of the City of New York</b></li><li class=\"d0\">Law career, insomnia stayed \u2014 &quot;<b>Nature</b> will take care of me&quot;</li><li class=\"d0\">Age <b>21</b>: <b>$75,000</b> a year. <b>1931</b>: highest lawyer&#x27;s fee ever \u2014 <b>a cool million</b>, cash on the barrel head</li><li class=\"d0\">Read half the night, up at <b>5am</b> dictating letters \u2014 lived to <b>81</b></li></ul>","img":[]},{"t":104,"lv":2,"h":"What sleep actually is","b":"<ul><li class=\"d0\"><b>A third</b> of life spent sleeping \u2014 nobody knows what sleep <i>is</i></li><li class=\"d0\"><b>Paul Kern</b>, Hungarian soldier, WWI, shot through the <b>frontal lobe</b> \u2014 recovered, never slept again</li><li class=\"d1\">Sedatives, narcotics, <b>hypnotism</b> \u2014 none worked. Got a job, lived on in good health</li></ul>","img":[]},{"t":157,"lv":3,"h":"Sleep needs vary","b":"<ul><li class=\"d0\"><b>Toscanini</b>: 5 hours a night. <b>Calvin Coolidge</b>: 11 hours out of 24</li><li class=\"d1\">Toscanini slept away <b>a fifth</b> of his life; Coolidge, nearly <b>half</b></li></ul>","img":[]},{"t":209,"lv":2,"h":"Ira Sandner \u2014 worry made the insomnia","b":"<ul><li class=\"d0\">Carnegie&#x27;s student, <b>Bridgefield Park, New Jersey</b></li><li class=\"d0\">Too sound a sleeper \u2014 overslept, boss warned him</li><li class=\"d0\">Friend&#x27;s fix: concentrate on the alarm clock before bed \u2014 backfired</li><li class=\"d1\"><b>Tick tick</b> became an obsession \u2014 <b>8 weeks</b> of torture, floor-pacing, thoughts of the window</li><li class=\"d0\">Old doctor&#x27;s cure: stop caring \u2014 &quot;I don&#x27;t care a hang if I don&#x27;t go to sleep&quot;</li><li class=\"d1\">Lying still, eyes closed, is rest</li><li class=\"d0\">Asleep within <b>2 weeks</b>; <b>8 hours</b> a night within a month</li><li class=\"d0\">Not the insomnia that nearly broke him \u2014 the <b>worry</b></li></ul>","img":[]},{"t":265,"lv":2,"h":"Dr. Kleitman&#x27;s verdict","b":"<ul><li class=\"d0\"><b>Dr. Nathaniel Kleitman</b>, University of Chicago \u2014 most sleep research of any living man</li><li class=\"d0\">Never known <b>anyone</b> to die of insomnia; worriers sleep more than they realize</li></ul>","img":[]},{"t":318,"lv":3,"h":"Herbert Spencer didn&#x27;t know he&#x27;d slept","b":"<ul><li class=\"d0\">Old bachelor \u2014 bored everyone about his insomnia</li><li class=\"d0\">Ear stoppings, <b>opium</b>, to sleep</li><li class=\"d0\">Shared a hotel room with <b>Professor Sacy of Oxford</b></li><li class=\"d0\">Swore he hadn&#x27;t slept a wink</li><li class=\"d1\">It was <b>Sacy</b> who hadn&#x27;t \u2014 kept up all night by Spencer&#x27;s <b>snoring</b></li></ul>","img":[]},{"t":424,"lv":2,"h":"Security, prayer, the body","b":"<ul><li class=\"d0\">First requisite for sleep: <b>security</b></li><li class=\"d0\"><b>Dr. Thomas Hyslop</b>, Great West Riding Asylum \u2014 prayer, &quot;most adequate...pacifier of mind&quot;</li><li class=\"d0\"><b>Jeanette MacDonald</b> \u2014 repeated <b>Psalm 23</b> when worried, sleepless</li><li class=\"d0\">Not religious? \u2014 <b>Dr. David Harold Fink</b>, <i>Release from Nervous Tension</i></li><li class=\"d1\">Talk to your body: &quot;let go, loosen up, relax&quot;</li><li class=\"d1\">Pillow under <b>knees</b>, small pillows under <b>arms</b></li></ul>","img":[]},{"t":485,"lv":2,"h":"Exhaustion cures it","b":"<ul><li class=\"d0\"><b>Theodore Dreiser</b>, struggling author \u2014 <b>section hand</b>, New York Central Railway</li><li class=\"d1\">Driving spikes, shoveling gravel \u2014 too tired to eat</li></ul>","img":[]},{"t":544,"lv":3,"h":"Carnegie&#x27;s own story","b":"<ul><li class=\"d0\">Age <b>13</b> \u2014 father shipped hogs to <b>St. Joseph, Missouri</b>; never seen a town over <b>4,000</b></li><li class=\"d0\">St. Joe: <b>60,000</b> people, a <b>six-story</b> skyscraper, his first streetcar</li><li class=\"d0\">Train home to <b>Ravenwood, Missouri</b>, arrived <b>2am</b> \u2014 walked <b>four miles</b></li><li class=\"d0\"><b>Slept and dreamed while walking</b>; also slept on horseback</li></ul>","img":[]},{"t":598,"lv":3,"h":"War-exhausted soldiers","b":"<ul><li class=\"d0\"><b>Dr. Foster Kennedy</b>, neurologist \u2014 retreat of the <b>5th British Army</b>, <b>1918</b></li><li class=\"d0\">Soldiers so tired, raising their eyelids didn&#x27;t wake them \u2014 pupils rolled <b>upward</b></li><li class=\"d0\">Kennedy later used it himself \u2014 roll the eyeballs up, drowsy in seconds</li></ul>","img":[]},{"t":703,"lv":2,"h":"No one dies of sleeplessness","b":"<ul><li class=\"d0\"><b>Dr. Henry C. Link</b>, <i>The Rediscovery of Man</i> \u2014 VP, Psychological Corporation</li><li class=\"d1\">Suicidal patient \u2014 Link&#x27;s answer: run around the block <b>until you drop dead</b></li><li class=\"d1\">Tried it, felt better each time</li><li class=\"d1\">By the <b>third night</b>, slept like a log \u2014 later joined an athletic club</li></ul>","img":[]},{"t":703,"lv":2,"h":"Five rules against insomnia","b":"<ul><li class=\"num\"><span>1</span>Can&#x27;t sleep \u2014 get up and <b>work or read</b> until sleepy</li><li class=\"num\"><span>2</span>No one killed by lack of sleep \u2014 the <b>worry</b> does the damage</li><li class=\"num\"><span>3</span>Try <b>prayer</b>, or repeat <b>Psalm 23</b></li><li class=\"num\"><span>4</span><b>Relax</b> your body</li><li class=\"num\"><span>5</span><b>Exercise</b> \u2014 get physically tired enough you can&#x27;t stay awake</li></ul>","img":[]},{"t":757,"lv":2,"h":"Part 7 in a nutshell \u2014 six ways to beat fatigue and worry","b":"<ul><li class=\"num\"><span>1</span><b>Rest</b> before you get tired</li><li class=\"num\"><span>2</span>Relax <b>at work</b></li><li class=\"num\"><span>3</span>Relax <b>at home</b></li><li class=\"num\"><span>4</span>Four working habits</li><li class=\"d1\">Clear desk but for the problem at hand</li><li class=\"d1\">Do things in order of <b>importance</b></li><li class=\"d1\">Solve it <b>then and there</b> if you have the facts</li><li class=\"d1\"><b>Organize</b>, deputize, supervise</li><li class=\"num\"><span>5</span>Put <b>enthusiasm</b> into your work</li><li class=\"num\"><span>6</span>No one ever killed by lack of sleep \u2014 the <b>worry</b> about it does the damage</li></ul>","img":[]}]}];